// Display ordering by sale type: I (inter-state) first, then L (local), then
// any other/blank. Ties break on buyer code ascending. Used by the on-screen
// buyer pickers (eligible-buyers, pre-invoice preview) so both agree.
const _saleRank = (s) => {
  const t = String(s || '').trim().toUpperCase();
  return t === 'I' ? 0 : t === 'L' ? 1 : 2;
};
const _bySaleThenBuyer = (a, b) => {
  const ra = _saleRank(a.default_sale ?? a.sale ?? a.saleType);
  const rb = _saleRank(b.default_sale ?? b.sale ?? b.saleType);
  if (ra !== rb) return ra - rb;
  const ka = String(a.buyer ?? a.code ?? '');
  const kb = String(b.buyer ?? b.code ?? '');
  return ka.localeCompare(kb, undefined, { numeric: true });
};

const app = express();

// Performance instrumentation — MUST be the first middleware so it also times
// body parsing and static file serving (the 80s homepage hang was a static
// request, which never touches the DB). See perf-monitor.js for the why.
const perf = require('./perf-monitor');
app.use(perf.middleware);

// Capture the raw request body so the WhatsApp webhook can verify Meta's
// HMAC (X-Hub-Signature-256) over the exact bytes received. Cheap — just
// stashes the Buffer express already has in hand.
app.use(express.json({ limit: '50mb', verify: (req, _res, buf) => { req.rawBody = buf; } }));

// Disable caching of HTML files so users always get the latest UI without
// needing a hard-reload. This is critical for ngrok-tunnelled deployments
// where intermediate proxies may cache aggressively. JavaScript/CSS/
// images can still be cached normally (handled by the static middleware
// after this).
app.use((req, res, next) => {
  if (req.path === '/' || req.path.endsWith('.html')) {
    res.set('Cache-Control', 'no-store, no-cache, must-revalidate, private');
    res.set('Pragma', 'no-cache');
    res.set('Expires', '0');
  }
  next();
});

app.use(express.static(path.join(__dirname, 'public')));

// ══════════════════════════════════════════════════════════════
// APP-WIDE ACTIVITY AUDIT (breadth) — feeds Backup → App Activity log
// ══════════════════════════════════════════════════════════════
// Records who changed what across the master + transaction modules into
// the shared audit_log, with a field-level A→B diff on the known tables.
// Lot entry has its OWN feed (entity='lot', logged separately) and Fix Data
// edits are intentionally excluded — neither is mapped here. Best-effort: it
// never blocks or fails a request (all DB work is wrapped in try/catch and the
// write happens on res 'finish', after the handler has already responded).
//
// Registered before the API routes so it can snapshot the pre-edit row on the
// way IN; the actual log row is written on the way OUT (successful status only).
//
// Every row also carries a one-line human `summary` — WHICH document, for
// WHOM, in which trade, for how much — because "generate · invoice" on its own
// can't answer the question the log exists to answer. The summary is built
// from the request body, the handler's own JSON response (captured below) and
// one cheap lookup of the row that was just written; the structured fields it
// was assembled from are stored alongside it so the UI can show them as chips.
const AUDIT_RESOURCES = {
  traders:               { entity: 'seller',              table: 'traders' },
  buyers:                { entity: 'buyer',               table: 'buyers' },
  auctions:              { entity: 'auction',             table: 'auctions' },
  invoices:              { entity: 'invoice',             table: 'invoices' },
  purchases:             { entity: 'purchase',            table: 'purchases' },
  bills:                 { entity: 'bill',                table: 'bills' },
  'debit-notes':         { entity: 'debit note',          table: 'debit_notes' },
  'debit-notes-planter': { entity: 'planter debit note',  table: 'debit_notes_planter' },
  // Money movement and account administration — no single table backs these
  // routes (payments writes lots / payment_advances / lot_advances), so they
  // are summarised from the request + response instead of an A→B row diff.
  payments:              { entity: 'payment',             table: null },
  users:                 { entity: 'user',                table: 'users' },
};
// Columns never surfaced in an A→B diff (derived / volatile / noisy), plus
// the credential columns that must never reach a log line.
const AUDIT_SKIP_COLS = new Set([
  'id', 'created_at', 'updated_at',
  'password_hash', 'password', 'token', 'session_token', 'api_key',
]);
// POST sub-paths that don't mutate business data (PDF/print/preview/preflight)
// — logging them would just be noise, so skip.
const AUDIT_SKIP_POST = /\b(pdf|print|preview|preflight|export|download)\b/i;

function _auditTrunc(v) {
  const s = v == null ? '' : String(v);
  return s.length > 160 ? s.slice(0, 157) + '…' : s;
}
function _auditResourceFor(pathname) {
  const m = String(pathname || '').match(/^\/api\/([a-z0-9-]+)/i);
  if (!m) return null;
  const key = m[1].toLowerCase();
  return AUDIT_RESOURCES[key] ? { key, ...AUDIT_RESOURCES[key] } : null;
}
function _auditIdFromPath(pathname) {
  const m = String(pathname || '').match(/^\/api\/[a-z0-9-]+\/(\d+)(?:\/|$)/i);
  return m ? parseInt(m[1], 10) : null;
}
function _auditDiff(oldRow, newRow) {
  if (!oldRow || !newRow) return [];
  const out = [];
  for (const k of Object.keys(newRow)) {
    if (AUDIT_SKIP_COLS.has(k)) continue;
    const a = oldRow[k], b = newRow[k];
    const na = a == null ? '' : String(a), nb = b == null ? '' : String(b);
    if (na === nb) continue;
    // Numeric-aware equality so 3 vs "3.0" isn't flagged.
    if (na !== '' && nb !== '' && !Number.isNaN(Number(a)) && !Number.isNaN(Number(b)) && Number(a) === Number(b)) continue;
    out.push({ field: k, label: k, from: _auditTrunc(a), to: _auditTrunc(b) });
    if (out.length >= 40) break;
  }
  return out;
}
// Best-effort human label for a row of a given resource.
function _auditRowLabel(key, row) {
  if (!row) return '';
  const pick = (...ks) => { for (const k of ks) { const v = row[k]; if (v != null && String(v).trim() !== '') return String(v).trim(); } return ''; };
  switch (key) {
    case 'traders':
    case 'buyers':               return pick('name', 'buyer1', 'buyer', 'trade_name');
    case 'auctions':             return pick('ano', 'name', 'date');
    case 'invoices':
    case 'purchases':
    case 'bills':                return pick('invo', 'invoice_no', 'buyer1', 'buyer', 'name');
    case 'debit-notes':
    case 'debit-notes-planter':  return pick('dn_no', 'invo', 'buyer1', 'buyer', 'name');
    default:                     return pick('name', 'buyer', 'invo');
  }
}

// ── Activity-log context helpers ──────────────────────────────────────
// People read this log asking "who raised THAT invoice, for whom, in which
// trade?". These build the answer. All of it is best-effort — a lookup that
// throws just leaves its field out of the summary.

// How many per-document entries a bulk run records by name. A trade-wide
// generate can touch hundreds of documents; the log names the first 100 and
// says how many more there were, so the details blob stays a sane size.
const AUDIT_MAX_ITEMS = 100;
const AUDIT_SALE_LABEL = { L: 'Local', I: 'Inter-state', E: 'Export' };

function _auditMoney(n) {
  const v = Number(n);
  if (!Number.isFinite(v) || Math.round(v) === 0) return '';
  return '₹' + Math.round(v).toLocaleString('en-IN');
}
function _auditQty(n) {
  const v = Number(n);
  if (!Number.isFinite(v) || v === 0) return '';
  return (Math.round(v * 100) / 100).toLocaleString('en-IN') + ' kg';
}
function _auditDMY(d) {
  const m = String(d || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? `${m[3]}/${m[2]}/${m[1]}` : String(d || '');
}
// The AUCTION id in a path, and only that. Matched against the routes that
// actually take one (/generate/:auctionId, /payments/:auctionId/…) rather than
// "any trailing number" — on /api/invoices/1201/revert the trailing number is
// an invoice row id, and reading it as a trade would name the wrong trade.
function _auditTailId(pathname) {
  const p = String(pathname || '');
  const m = p.match(/\/(?:generate|generate-all|generate-bulk|revert-all|preview)\/(\d+)/i)
         || p.match(/^\/api\/payments\/(?:lots\/)?(\d+)(?:\/|$)/i);
  return m ? parseInt(m[1], 10) : null;
}
// "#15 (12/08/2026)" for a trade, resolved by auction id or by trade number.
// Parenthesised rather than dot-separated so it stays one unit when it is
// dropped into a summary line that is itself dot-separated.
function _auditTrade(db, opts) {
  const aid = opts && opts.auctionId;
  const ano = opts && opts.ano != null ? String(opts.ano).trim() : '';
  let a = null;
  try {
    if (aid) a = db.get('SELECT ano, date FROM auctions WHERE id = ?', [aid]);
    if (!a && ano) a = db.get('SELECT ano, date FROM auctions WHERE ano = ? ORDER BY id DESC LIMIT 1', [ano]);
  } catch (_) {}
  if (a) return `#${a.ano}${a.date ? ` (${_auditDMY(a.date)})` : ''}`;
  return ano ? `#${ano}` : '';
}
// "MURUGAN TRADERS (AK)" from a buyer code — the code alone means nothing to
// whoever is reading the log a month later.
function _auditBuyerName(db, code) {
  const c = String(code == null ? '' : code).trim();
  if (!c) return '';
  try {
    const b = db.get('SELECT buyer1 FROM buyers WHERE buyer = ? LIMIT 1', [c]);
    const n = b && b.buyer1 ? String(b.buyer1).trim() : '';
    if (n && n.toUpperCase() !== c.toUpperCase()) return `${n} (${c})`;
  } catch (_) {}
  return c;
}
// Join the non-empty pieces of a summary into one line.
function _auditLine(parts) {
  return parts.map(p => (p == null ? '' : String(p).trim())).filter(Boolean).join(' · ');
}
// One entry per document a bulk run produced (or skipped), flattened from the
// per-route result shapes: invoices return invoiceNo/buyer, bills billNo/seller,
// debit notes note_no/dealer, planter DNs note_no/planter.
function _auditItems(arr, isSkip) {
  const out = [];
  for (const it of (Array.isArray(arr) ? arr : [])) {
    if (!it || typeof it !== 'object') continue;
    const pick = (...ks) => {
      for (const k of ks) { const v = it[k]; if (v != null && String(v).trim() !== '') return String(v).trim(); }
      return '';
    };
    const num = (...ks) => {
      for (const k of ks) { const v = Number(it[k]); if (Number.isFinite(v) && v !== 0) return v; }
      return 0;
    };
    const e = {};
    const doc = pick('invoiceNo', 'billNo', 'note_no', 'invo', 'bil');
    const party = pick('buyer1', 'seller', 'dealer', 'planter', 'name', 'buyer');
    const lot = pick('lotNo', 'lot_no');
    const ref = pick('purchno', 'bilno');
    const amt = num('grandTotal', 'netAmount', 'total', 'amount');
    if (doc) e.doc = doc;
    if (party) e.party = party;
    if (lot) e.lot = lot;
    if (ref) e.ref = ref;
    if (amt) e.amount = Math.round(amt * 100) / 100;
    if (isSkip) { const r = pick('reason'); if (r) e.reason = r; }
    if (Object.keys(e).length) out.push(e);
    if (out.length >= AUDIT_MAX_ITEMS) break;
  }
  return out;
}
// "1201–1212" when a run's numbers are all numeric, else the first few with a
// "+N more" tail. This is the single most useful thing on a bulk row.
function _auditDocRange(items) {
  const docs = items.map(i => i.doc).filter(Boolean);
  if (!docs.length) return '';
  if (docs.length === 1) return docs[0];
  const nums = docs.map(Number).filter(Number.isFinite);
  if (nums.length === docs.length) {
    const lo = Math.min(...nums), hi = Math.max(...nums);
    return lo === hi ? String(lo) : `${lo}–${hi}`;
  }
  return docs.length <= 4 ? docs.join(', ') : docs.slice(0, 4).join(', ') + ` +${docs.length - 4} more`;
}
// Sum a bulk run's document values, so a trade-wide generate reports what it
// actually billed rather than just how many rows it wrote.
function _auditItemsTotal(items) {
  return items.reduce((t, i) => t + (Number(i.amount) || 0), 0);
}
// Finer-grained verb than method+path alone. Keeps the historic vocabulary
// (create/update/delete/generate/import/revert) and adds the operations that
// used to be indistinguishable from a plain "update".
function _auditActionFor(method, p, resBody) {
  if (/\/(generate-all|generate-bulk)\b/i.test(p)) return 'generate all';
  if (/\/generate\b/i.test(p))                     return 'generate';
  if (/\/raise-original\b/i.test(p))               return 'raise original';
  if (/\/revert-all\b/i.test(p))                   return 'revert all';
  if (/\/revert\b/i.test(p))                       return 'revert';
  if (/\/unmark-paid\b/i.test(p))                  return 'unmark paid';
  if (/\/mark-paid\b/i.test(p))                    return 'mark paid';
  if (/\/advance\b/i.test(p))                      return 'pay advance';
  if (/\/apply-discount\b/i.test(p))               return 'discount';
  if (/\/(delete-sellers|delete-all|bulk-delete)\b/i.test(p)) return 'delete';
  if (/\/revoke-sessions\b/i.test(p))              return 'revoke sessions';
  if (/\/lock\b/i.test(p))  return (resBody && resBody.locked === false) ? 'unlock' : 'lock';
  if (/\/password\b/i.test(p))                     return 'password reset';
  if (/\/role\b/i.test(p))                         return 'role change';
  if (/import/i.test(p))                           return 'import';
  return null;   // caller falls back to method + presence of an /:id
}
// The document row a single-document generate just wrote. Gives the log the
// real party name, quantity, value and row id (so the Item column links to
// something) instead of just echoing what was posted.
function _auditCreatedDoc(db, key, req, resBody) {
  const b = (req.body && typeof req.body === 'object') ? req.body : {};
  const aid = _auditTailId(req.path);
  const g = (sql, params) => { try { return db.get(sql, params); } catch (_) { return null; } };
  if (key === 'invoices') {
    const no = String(b.invoiceNo == null ? '' : b.invoiceNo).trim();
    if (!no) return null;
    return g(`SELECT * FROM invoices WHERE invo = ? AND buyer = ?${aid ? ' AND auction_id = ?' : ''}
              ORDER BY id DESC LIMIT 1`,
      aid ? [no, String(b.buyerCode || ''), aid] : [no, String(b.buyerCode || '')]);
  }
  if (key === 'purchases') {
    const no = String(b.invoiceNo == null ? '' : b.invoiceNo).trim();
    if (!no) return null;
    return g(`SELECT * FROM purchases WHERE invo = ?${aid ? ' AND auction_id = ?' : ''}
              ORDER BY id DESC LIMIT 1`, aid ? [no, aid] : [no]);
  }
  if (key === 'bills') {
    const no = String(b.billNo == null ? '' : b.billNo).trim();
    if (!no) return null;
    const auc = aid ? g('SELECT ano FROM auctions WHERE id = ?', [aid]) : null;
    return g(`SELECT * FROM bills WHERE bil = ?${auc ? ' AND ano = ?' : ''} ORDER BY id DESC LIMIT 1`,
      auc ? [no, String(auc.ano)] : [no]);
  }
  return null;
}
// Fields worth naming on a document row, in display order.
function _auditDocFields(db, key, row, out) {
  if (!row) return;
  if (key === 'invoices') {
    out.doc   = 'Invoice ' + (row.invo || '');
    out.party = row.buyer1 ? `${row.buyer1}${row.buyer ? ` (${row.buyer})` : ''}` : (row.buyer || '');
    out.trade = _auditTrade(db, { auctionId: row.auction_id, ano: row.ano });
    if (row.bag)  out.bags = String(row.bag);
    if (row.qty)  out.qty = _auditQty(row.qty);
    if (row.tot)  out.value = _auditMoney(row.tot);
    if (row.sale) out.sale = AUDIT_SALE_LABEL[String(row.sale).toUpperCase()] || row.sale;
    if (Number(row.is_proforma) === 1) out.kind = 'Proforma';
    if (Number(row.no_ti) === 1) out.no_ti = 'No transport/insurance';
    if (row.date) out.doc_date = _auditDMY(row.date);
    try {
      const li = row.line_items ? JSON.parse(row.line_items) : null;
      if (Array.isArray(li) && li.length) {
        out.lots = String(li.length);
        const nos = li.map(x => String(x && x.lot != null ? x.lot : '')).filter(Boolean);
        if (nos.length) out.lot_nos = nos.length <= 12 ? nos.join(', ') : nos.slice(0, 12).join(', ') + ` +${nos.length - 12}`;
      }
    } catch (_) {}
  } else if (key === 'purchases') {
    out.doc   = 'Purchase ' + (row.invo || '');
    out.party = row.name || '';
    out.trade = _auditTrade(db, { auctionId: row.auction_id, ano: row.ano });
    if (row.lot_no) out.lot_nos = String(row.lot_no);
    if (row.qty)    out.qty = _auditQty(row.qty);
    if (row.total)  out.value = _auditMoney(row.total);
    if (row.date)   out.doc_date = _auditDMY(row.date);
  } else if (key === 'bills') {
    out.doc   = 'Bill ' + (row.bil || '');
    out.party = row.name || '';
    out.trade = _auditTrade(db, { ano: row.ano });
    if (row.lot_no) out.lot_nos = String(row.lot_no);
    if (row.qty)    out.qty = _auditQty(row.qty);
    if (row.net)    out.value = _auditMoney(row.net);
    if (row.date)   out.doc_date = _auditDMY(row.date);
  } else if (key === 'debit-notes' || key === 'debit-notes-planter') {
    out.doc   = 'DN ' + (row.note_no || '');
    out.party = row.name || '';
    out.trade = _auditTrade(db, { ano: row.ano });
    if (row.lot_no) out.lot_nos = String(row.lot_no);
    if (row.total)  out.value = _auditMoney(row.total);
    if (row.date)   out.doc_date = _auditDMY(row.date);
  } else if (key === 'traders' || key === 'buyers') {
    out.party = _auditRowLabel(key, row);
    const place = row.pla || row.place || '';
    if (place) out.place = String(place);
    if (row.gstin) out.gstin = String(row.gstin);
    if (key === 'buyers' && row.buyer) out.code = String(row.buyer);
  } else if (key === 'auctions') {
    out.trade = `#${row.ano || ''}${row.date ? ' · ' + _auditDMY(row.date) : ''}`;
    if (row.crop_type) out.crop = String(row.crop_type);
  } else if (key === 'users') {
    out.account = row.username || '';
    if (row.role)   out.role = String(row.role);
    if (row.branch) out.branch = String(row.branch);
  }
}
// When no stored row can be located (the debit-note routes report everything
// they did in their response, and hand-added masters echo the new row), read
// the document's identity straight out of the JSON that went back to the
// browser. Only known keys are read — a request body is never dumped wholesale,
// since some carry passwords.
function _auditDocFromResponse(db, rsrc, req, resBody, out) {
  const r = (resBody && typeof resBody === 'object') ? resBody : {};
  const b = (req.body && typeof req.body === 'object') ? req.body : {};
  const pick = (src, ...ks) => {
    for (const k of ks) { const v = src[k]; if (v != null && String(v).trim() !== '') return String(v).trim(); }
    return '';
  };
  const docNo = pick(r, 'note_no', 'invoiceNo', 'billNo', 'invo') || pick(b, 'note_no', 'invoiceNo', 'billNo', 'invo');
  if (docNo) {
    const prefix = rsrc.key === 'debit-notes' || rsrc.key === 'debit-notes-planter' ? 'DN '
                 : rsrc.key === 'bills' ? 'Bill '
                 : rsrc.key === 'purchases' ? 'Purchase '
                 : rsrc.key === 'invoices' ? 'Invoice ' : '';
    out.doc = prefix + docNo;
  }
  const party = pick(r, 'dealer', 'planter', 'buyer1', 'name') || pick(b, 'sellerName', 'name', 'buyer1');
  if (party) out.party = party;
  if (!out.party && b.buyerCode) out.party = _auditBuyerName(db, b.buyerCode);
  const trade = _auditTrade(db, { auctionId: _auditTailId(req.path), ano: r.ano || b.ano });
  if (trade) out.trade = trade;
  const ref = pick(r, 'purchno', 'bilno');
  if (ref) out.against = ref;
  const lot = pick(r, 'lot_no', 'lotNo') || pick(b, 'lotNo');
  if (lot) out.lot_nos = lot;
  if (r.mode) out.mode = r.mode === 'lot' ? 'Lot-wise' : 'Seller-wise';
  const inv = (r.invoice && typeof r.invoice === 'object') ? r.invoice
            : (r.bill && typeof r.bill === 'object') ? r.bill : null;
  if (inv) {
    if (inv.totalQty)  out.qty = _auditQty(inv.totalQty);
    if (inv.totalBags) out.bags = String(inv.totalBags);
    const v = inv.grandTotal != null ? inv.grandTotal : inv.netAmount;
    if (v) out.value = _auditMoney(v);
  }
  if (!out.value && (r.total || r.amount)) out.value = _auditMoney(r.total || r.amount);
  if (!out.kind && (r.proforma === true || Number(b.is_proforma) === 1)) out.kind = 'Proforma';
}
// Summarise a bulk run (generate-all / generate-bulk / revert-all) from the
// handler's own response. This is the case the old log was worst at: it said
// "generate · invoice · — · —" for a run that raised forty invoices.
function _auditBulk(db, key, rsrc, req, resBody, out) {
  const r = (resBody && typeof resBody === 'object') ? resBody : {};
  const madeRaw = Array.isArray(r.results) ? r.results : (Array.isArray(r.generated) ? r.generated : []);
  const made = _auditItems(madeRaw, false);
  // `skipped` is an array on the invoice/purchase/bill runs and a plain count
  // on the debit-note runs (which name their skips in `skippedDetails`).
  const skipRaw = Array.isArray(r.skippedDetails) ? r.skippedDetails
                : Array.isArray(r.skipped) ? r.skipped : [];
  const skipped = _auditItems(skipRaw, true);
  const skipCount = Array.isArray(r.skipped) ? r.skipped.length
                  : Number.isFinite(Number(r.skipped)) ? Number(r.skipped)
                  : skipRaw.length;
  const total = Number.isFinite(Number(r.generated)) && !Array.isArray(r.generated) ? Number(r.generated)
              : Number.isFinite(Number(r.created)) ? Number(r.created)
              : madeRaw.length;
  // Invoice runs report the buyer CODE; swap in the trading name (one query,
  // the buyers master is small) so the log names people, not codes.
  if (key === 'invoices' && made.length) {
    try {
      const names = new Map(db.all('SELECT buyer, buyer1 FROM buyers').map(b => [String(b.buyer).toUpperCase(), b.buyer1]));
      for (const it of made) {
        const n = it.party ? names.get(String(it.party).toUpperCase()) : '';
        if (n && String(n).trim()) it.party = `${String(n).trim()} (${it.party})`;
      }
    } catch (_) {}
  }
  const noun = rsrc.entity + (total === 1 ? '' : 's');
  const range = _auditDocRange(made);
  const value = _auditMoney(_auditItemsTotal(made));
  const trade = _auditTrade(db, { auctionId: _auditTailId(req.path), ano: (req.body && req.body.ano) || r.ano });

  out.count = String(total);
  if (range) out.numbers = range;
  if (trade) out.trade = trade;
  if (value) out.value = value;
  if (r.mode) out.mode = r.mode === 'lot' ? 'Lot-wise' : 'Seller-wise';
  if (skipCount > 0) out.skipped = String(skipCount);
  if (Array.isArray(r.errors) && r.errors.length) out.errors = String(r.errors.length);
  if (r.note) out.note = String(r.note);
  // The per-document roll, so "which invoices?" is answerable from the row.
  if (made.length) {
    out.items = made;
    if (madeRaw.length > made.length) out.items_more = madeRaw.length - made.length;
  }
  if (skipped.length) out.skipped_items = skipped;

  out.summary = _auditLine([
    total ? `${total} ${noun}` : `No ${rsrc.entity}s`,
    range ? `no. ${range}` : '',
    trade ? `Trade ${trade}` : '',
    value,
    out.skipped ? `${out.skipped} skipped` : '',
    out.errors ? `${out.errors} failed` : '',
  ]);
}
// Summarise the payments module's money movements — none of which are a row
// edit, so each one is described from its own request + response.
function _auditPayments(db, req, resBody, out) {
  const p = String(req.path || '');
  const b = (req.body && typeof req.body === 'object') ? req.body : {};
  const r = (resBody && typeof resBody === 'object') ? resBody : {};
  const aid = (p.match(/\/api\/payments\/(?:lots\/)?(\d+)/) || [])[1];
  const trade = _auditTrade(db, { auctionId: aid ? parseInt(aid, 10) : null });
  if (trade) out.trade = trade;
  // Name the sellers behind a list of lot ids — a count of lot ids tells the
  // reader nothing about whose money moved.
  const sellersOf = ids => {
    try {
      const nums = ids.map(n => parseInt(n, 10)).filter(Number.isFinite).slice(0, 400);
      if (!nums.length) return [];
      return db.all(`SELECT DISTINCT name FROM lots WHERE id IN (${nums.map(() => '?').join(',')}) AND name <> ''`, nums)
        .map(x => String(x.name)).filter(Boolean);
    } catch (_) { return []; }
  };
  const nameList = ns => ns.length <= 6 ? ns.join(', ') : ns.slice(0, 6).join(', ') + ` +${ns.length - 6} more`;

  if (/mark-paid\b/.test(p)) {
    const undo = /unmark-paid\b/.test(p);
    const n = Number(undo ? r.cleared : r.marked) || 0;
    const sellers = sellersOf(Array.isArray(b.lotIds) ? b.lotIds : []);
    out.lots = String(n);
    if (sellers.length) out.sellers = nameList(sellers);
    out.summary = _auditLine([
      `${undo ? 'Un-marked' : 'Marked'} ${n} lot${n === 1 ? '' : 's'} ${undo ? 'unpaid' : 'paid'}`,
      trade ? `Trade ${trade}` : '', sellers.length ? nameList(sellers) : '',
    ]);
    return;
  }
  if (/\/lots\/\d+\/advance\b/.test(p)) {
    const items = Array.isArray(b.items) ? b.items : [];
    const paid = items.filter(i => Number(i && i.advance) > 0);
    const sum = paid.reduce((t, i) => t + (Number(i.advance) || 0), 0);
    const sellers = sellersOf(items.map(i => i && i.lotId));
    out.lots = String(items.length);
    if (Number(r.saved)) out.saved = String(r.saved);
    if (Number(r.cleared)) out.cleared = String(r.cleared);
    if (sum) out.value = _auditMoney(sum);
    if (sellers.length) out.sellers = nameList(sellers);
    out.summary = _auditLine([
      `Lot-wise advance on ${items.length} lot${items.length === 1 ? '' : 's'}`,
      sum ? _auditMoney(sum) : '', trade ? `Trade ${trade}` : '',
      sellers.length ? nameList(sellers) : '',
    ]);
    return;
  }
  if (/\/advance\b/.test(p)) {
    const name = String(r.name || b.name || '').trim();
    const amt = Number(r.advance != null ? r.advance : b.advance) || 0;
    if (name) out.party = name;
    out.value = _auditMoney(amt) || '₹0';
    out.summary = _auditLine([
      amt > 0 ? `Advance ${_auditMoney(amt)}` : 'Advance cleared',
      name, trade ? `Trade ${trade}` : '',
    ]);
    return;
  }
  if (/apply-discount\b/.test(p)) {
    const on = !!r.applied;
    out.state = on ? 'Applied' : 'Removed';
    out.summary = _auditLine([`Cash discount ${on ? 'applied to' : 'removed from'} the trade`, trade ? `Trade ${trade}` : '']);
    return;
  }
  if (/delete-sellers\b/.test(p)) {
    const names = (Array.isArray(b.sellerNames) ? b.sellerNames : []).map(String).filter(Boolean);
    out.sellers = nameList(names);
    out.lots = String(Number(r.lotsDeleted) || 0);
    if (Number(r.dnsDeleted)) out.debit_notes = String(r.dnsDeleted);
    out.summary = _auditLine([
      `Deleted ${names.length} seller${names.length === 1 ? '' : 's'} — ${Number(r.lotsDeleted) || 0} lot${Number(r.lotsDeleted) === 1 ? '' : 's'}` +
        (Number(r.dnsDeleted) ? `, ${r.dnsDeleted} DN` : ''),
      trade ? `Trade ${trade}` : '', nameList(names),
    ]);
    return;
  }
  out.summary = _auditLine(['Payments update', trade ? `Trade ${trade}` : '']);
}
// Account administration: say WHICH account and WHAT changed, never anything
// derived from the password itself.
function _auditUsers(db, req, action, resBody, out) {
  const r = (resBody && typeof resBody === 'object') ? resBody : {};
  const b = (req.body && typeof req.body === 'object') ? req.body : {};
  const who = String(r.username || b.username || (req._auditOld && req._auditOld.username) || '').trim();
  if (who) out.account = who;
  if (r.role || b.role) out.role = String(r.role || b.role);
  if (b.branch != null && String(b.branch).trim() !== '') out.branch = String(b.branch).trim();
  const verb = {
    'role change':      `Role set to ${out.role || '?'}`,
    'password reset':   'Password reset (all sessions signed out)',
    'revoke sessions':  'Signed out of every device',
    lock:               'Account locked',
    unlock:             'Account unlocked',
    create:             `Account created${out.role ? ` as ${out.role}` : ''}`,
    delete:             'Account deleted',
  }[action] || 'Account updated';
  out.summary = _auditLine([verb, who ? `user ${who}` : '']);
}

function auditMutations(req, res, next) {
  try {
    const method = req.method;
    if (method === 'GET' || method === 'HEAD' || method === 'OPTIONS') return next();
    if (!String(req.path || '').startsWith('/api/')) return next();
    const rsrc = _auditResourceFor(req.path);
    if (!rsrc) return next();
    if (method === 'POST' && AUDIT_SKIP_POST.test(req.path)) return next();
    const id = _auditIdFromPath(req.path);
    // Snapshot the pre-edit row for anything addressing /:id of a known table.
    // POST is included because the sub-action routes (/revert, /raise-original,
    // /lock, /password …) are the ones whose "what did it act on?" answer is
    // gone by the time the response is written.
    if (rsrc.table && id != null && method !== 'GET') {
      try { req._auditOld = getDb().get(`SELECT * FROM ${rsrc.table} WHERE id = ?`, [id]); } catch (_) {}
    }
    // Capture the handler's own JSON so the log can report what it actually
    // produced — the invoice numbers a bulk run handed out, how many lots were
    // marked paid — rather than only what was asked for.
    const _json = res.json.bind(res);
    res.json = body => { try { req._auditRes = body; } catch (_) {} return _json(body); };

    res.on('finish', () => {
      try {
        if (res.statusCode >= 400) return;   // only successful mutations
        const db = getDb();
        const resBody = req._auditRes;
        // Derive a friendly action from method + path + what came back.
        let action = _auditActionFor(method, req.path, resBody);
        if (!action) {
          if (method === 'DELETE') action = 'delete';
          else if (method === 'PUT' || method === 'PATCH') action = 'update';
          else if (id != null) action = 'update';   // POST /api/<r>/:id/<sub-action>
          else action = 'create';
        }
        // A run that is reported as a batch (results/generated arrays, or an
        // explicit created count) is summarised per document, whatever verb
        // the path implied.
        const isBulk = !!resBody && typeof resBody === 'object' &&
          (Array.isArray(resBody.results) || Array.isArray(resBody.generated) ||
           (action === 'generate all' && resBody.created != null));

        const details = {};
        let changes = [];
        let entityId = id;

        if (rsrc.key === 'payments') {
          _auditPayments(db, req, resBody, details);
          entityId = null;
        } else if (rsrc.key === 'users') {
          if (action === 'update' && id != null) {
            let fresh; try { fresh = db.get('SELECT * FROM users WHERE id = ?', [id]); } catch (_) {}
            changes = _auditDiff(req._auditOld, fresh);
          }
          _auditUsers(db, req, action, resBody, details);
        } else if (isBulk) {
          _auditBulk(db, rsrc.key, rsrc, req, resBody, details);
          entityId = null;
        } else if (action === 'generate' || action === 'raise original') {
          // One document. Prefer the row that was just written (real party
          // name, quantity, value, id); fall back to whatever the handler
          // reported, which is all the debit-note routes give us.
          const row = _auditCreatedDoc(db, rsrc.key, req, resBody);
          if (row) { _auditDocFields(db, rsrc.key, row, details); if (row.id) entityId = row.id; }
          else _auditDocFromResponse(db, rsrc, req, resBody, details);
          // Raising an original works FROM a proforma: the draft is the only
          // thing that knows the buyer and trade, and it was snapshotted on
          // the way in.
          if (action === 'raise original' && req._auditOld) {
            const pf = req._auditOld;
            if (!details.party && (pf.buyer1 || pf.buyer)) {
              details.party = pf.buyer1 ? `${pf.buyer1}${pf.buyer ? ` (${pf.buyer})` : ''}` : pf.buyer;
            }
            if (!details.trade) details.trade = _auditTrade(db, { auctionId: pf.auction_id, ano: pf.ano });
            if (pf.invo) details.from_proforma = String(pf.invo);
          }
          details.summary = _auditLine([
            (action === 'raise original' ? 'Raised original ' : 'Generated ') + (details.doc || rsrc.entity),
            details.from_proforma ? `from draft ${details.from_proforma}` : '',
            details.party, details.trade ? `Trade ${details.trade}` : '',
            details.lots ? `${details.lots} lot${details.lots === '1' ? '' : 's'}` : '',
            details.qty, details.value, details.kind, details.mode,
          ]);
        } else if (action === 'update' && id != null) {
          let fresh; try { fresh = rsrc.table ? db.get(`SELECT * FROM ${rsrc.table} WHERE id = ?`, [id]) : null; } catch (_) {}
          changes = _auditDiff(req._auditOld, fresh);
          if (!changes.length) return;       // nothing actually changed → skip
          _auditDocFields(db, rsrc.key, fresh || req._auditOld, details);
          details.summary = _auditLine([
            'Edited ' + (details.doc || details.party || details.account || rsrc.entity),
            details.doc ? details.party : '', details.trade ? `Trade ${details.trade}` : '',
            `${changes.length} field${changes.length === 1 ? '' : 's'} changed`,
          ]);
        } else if (action === 'delete' || action === 'revert' || action === 'revert all') {
          // Describe what was removed from the pre-delete snapshot — after the
          // fact the row is gone, so this is the only chance to name it.
          if (req._auditOld) _auditDocFields(db, rsrc.key, req._auditOld, details);
          const r = (resBody && typeof resBody === 'object') ? resBody : {};
          if (/delete-all/i.test(req.path)) {
            // A whole-table wipe. Say how many rows went, what it cascaded
            // into, and where the rollback snapshot landed.
            const n = Number(r.deleted) || 0;
            details.count = String(n);
            if (r.ano) details.trade = _auditTrade(db, { ano: r.ano });
            const cascade = (r.cascadeCounts && typeof r.cascadeCounts === 'object') ? r.cascadeCounts : {};
            const spill = Object.entries(cascade)
              .filter(([t, c]) => Number(c) > 0 && t !== 'ano')
              .map(([t, c]) => `${t}: ${c}`).join(', ');
            if (spill) details.cascade = spill;
            if (r.backupPath) details.snapshot = String(r.backupPath).split(/[\\/]/).pop();
            details.summary = _auditLine([
              `Wiped every ${rsrc.entity} — ${n} row${n === 1 ? '' : 's'} deleted`,
              details.trade ? `Trade ${details.trade}` : '',
              spill ? `cascade ${spill}` : '',
              details.snapshot ? `rollback ${details.snapshot}` : '',
            ]);
          } else if (action === 'revert all') {
            const n = Number(r.invoicesReverted) || 0;
            details.count = String(n);
            details.trade = _auditTrade(db, { auctionId: _auditTailId(req.path) });
            if (Number(r.lotsFreed)) details.lots_freed = String(r.lotsFreed);
            if (Number(r.skipped_locked)) details.skipped = String(r.skipped_locked);
            details.summary = _auditLine([
              `Reverted ${n} ${rsrc.entity}${n === 1 ? '' : 's'}`,
              details.trade ? `Trade ${details.trade}` : '',
              Number(r.lotsFreed) ? `${r.lotsFreed} lots freed` : '',
              Number(r.skipped_locked) ? `${r.skipped_locked} locked, skipped` : '',
            ]);
          } else {
            if (Number(r.lotsFreed)) details.lots_freed = String(r.lotsFreed);
            details.summary = _auditLine([
              (action === 'revert' ? 'Reverted ' : 'Deleted ') + (details.doc || details.party || details.account || rsrc.entity),
              details.doc ? details.party : '', details.trade ? `Trade ${details.trade}` : '',
              details.qty, details.value,
              Number(r.lotsFreed) ? `${r.lotsFreed} lots freed` : '',
            ]);
          }
        } else {
          // Plain create (master records, hand-added documents).
          const label = _auditRowLabel(rsrc.key, req.body || {});
          _auditDocFromResponse(db, rsrc, req, resBody, details);
          // `name` is the fallback identity — skip it when the row already
          // named the party, or the log shows the same value twice.
          if (label && !details.party) details.name = label;
          details.summary = _auditLine([
            'Added ' + (details.doc || details.party || details.account || label || rsrc.entity),
            details.doc ? details.party : '', details.trade ? `Trade ${details.trade}` : '',
            details.qty, details.value,
          ]);
        }

        // Where it came from — two people editing the same trade from
        // different devices is exactly when this log gets consulted.
        const ip = String(req.headers['x-forwarded-for'] || req.ip || '').split(',')[0].trim();
        if (ip) details.ip = ip.replace(/^::ffff:/, '');
        details.route = `${method} ${req.path}`;

        db.run(
          `INSERT INTO audit_log (user_id, action, entity, entity_id, details) VALUES (?,?,?,?,?)`,
          [(req.user && req.user.username) || 'system', action, rsrc.entity, entityId || null,
           JSON.stringify({ ...details, changes: changes.length ? changes : undefined })]
        );
      } catch (_) { /* never let logging break anything */ }
    });
  } catch (_) {}
  return next();
}
app.use(auditMutations);

// Prevent browser/proxy caching of API responses so Refresh buttons actually
// fetch fresh data (without this, fetch() may return stale cached JSON)
app.use('/api', (req, res, next) => {
  res.set('Cache-Control', 'no-store, no-cache, must-revalidate, private');
  res.set('Pragma', 'no-cache');
  res.set('Expires', '0');
  next();
});

// Health check — used by the Electron wrapper to wait until the server
// is ready to accept requests before loading the window URL. Returns a
// minimal 200 with no auth required.
app.get('/api/health', (req, res) => {
  res.json({ ok: true, ts: Date.now() });
});

// File upload setup
// Honor SPICE_DATA_DIR so uploads also land in userData when packaged.
const uploadDir = path.join(process.env.SPICE_DATA_DIR || path.join(__dirname, 'data'), 'uploads');
if (!fs.existsSync(uploadDir)) fs.mkdirSync(uploadDir, { recursive: true });
const upload = multer({ dest: uploadDir, limits: { fileSize: 20 * 1024 * 1024 } });

const hash = pw => crypto.createHash('sha256').update(pw).digest('hex');

// ── Date helpers ──
// Convert any date-ish input (Date object, Excel serial number, dd/mm/yyyy,
// yyyy-mm-dd, etc.) to canonical ISO yyyy-mm-dd for storage.
function normalizeDate(v) {
  if (v === null || v === undefined || v === '') return '';
  // Date object
  if (v instanceof Date && !isNaN(v)) {
    return v.toISOString().slice(0, 10);
  }
  // Number = Excel serial (days since 1900-01-01, with the famous 1900 leap-year bug)
  if (typeof v === 'number' && v > 0 && v < 80000) {
    // Excel epoch: 1899-12-30 (accounts for the 1900 leap-year bug)
    const ms = (v - 25569) * 86400 * 1000;
    const d = new Date(ms);
    if (!isNaN(d)) return d.toISOString().slice(0, 10);
  }
  const s = String(v).trim();
  // ISO yyyy-mm-dd (or yyyy-mm-dd HH:MM:SS)
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.substring(0, 10);
  // dd/mm/yyyy or dd-mm-yyyy
  const m1 = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (m1) return `${m1[3]}-${m1[2].padStart(2, '0')}-${m1[1].padStart(2, '0')}`;
  // Pure numeric string Excel serial
  if (/^\d+(\.\d+)?$/.test(s)) {
    const n = Number(s);
    if (n > 0 && n < 80000) {
      const ms = (n - 25569) * 86400 * 1000;
      const d = new Date(ms);
      if (!isNaN(d)) return d.toISOString().slice(0, 10);
    }
  }
  // Last resort: try Date parsing
  const d = new Date(s);
  if (!isNaN(d)) return d.toISOString().slice(0, 10);
  return s;
}

// Today's LOCAL date as canonical YYYY-MM-DD. Uses local getters (not
// toISOString, which is UTC) so an invoice raised late in the evening doesn't
// jump to tomorrow. Matches the storage format of auctions.date.
function todayLocalYMD() {
  const d = new Date();
  const p = n => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// Resolve the date to stamp on a generated invoice. dateSource 'auction' uses
// the auction's own date (legacy behaviour); anything else (default) uses
// today's local date — the ship/raise date, which is the sensible default for
// a tax invoice and required when a late invoice is raised long after the sale.
function resolveInvoiceDate(dateSource, auctionDate) {
  return String(dateSource || '').trim().toLowerCase() === 'auction'
    ? auctionDate
    : todayLocalYMD();
}

// Add N days to an ISO date string (YYYY-MM-DD). String-based to avoid
// timezone drift — operating on a plain Date() in JS will silently shift
// the day across DST boundaries or when the server is in a non-UTC TZ.
// Uses Date in UTC mode purely for the calendar math (month/year rollover,
// leap years), then re-extracts the YYYY-MM-DD components.
//
// Edge cases handled:
//   - Month rollover:  '2026-01-31' + 1  → '2026-02-01'
//   - Year rollover:   '2026-12-31' + 1  → '2027-01-01'
//   - Leap year:       '2028-02-28' + 1  → '2028-02-29'
//   - Non-leap year:   '2026-02-28' + 1  → '2026-03-01'
//   - Negative offset: '2026-03-01' + -1 → '2026-02-28'
//   - Empty input:                       → '' (no throw)
function addDays(isoDate, days) {
  const iso = normalizeDate(isoDate);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso)) return '';
  const [y, m, d] = iso.split('-').map(Number);
  // Date.UTC anchors the math at midnight UTC so DST never enters the
  // calculation — month rollover, year rollover, and leap years all
  // resolve correctly via the underlying calendar arithmetic.
  const ms = Date.UTC(y, m - 1, d) + (Number(days) || 0) * 86400 * 1000;
  const out = new Date(ms);
  const yy = out.getUTCFullYear();
  const mm = String(out.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(out.getUTCDate()).padStart(2, '0');
  return `${yy}-${mm}-${dd}`;
}

// Display: render any date-ish value using the operator's configured
// `date_format` setting (Settings → Business Mode → Date Format).
// Default is dd/mm/yyyy if the setting is missing. Storage stays ISO
// yyyy-mm-dd in the DB; this only affects how dates are shown.
function fmtDate(d) {
  if (!d && d !== 0) return '';
  const iso = normalizeDate(d);
  // Cache the active format on the call to avoid getSettingsFlat() for
  // every row of a 500-row list — same DB hit otherwise.
  if (!fmtDate._cachedFormat || (Date.now() - fmtDate._cachedAt) > 2000) {
    try {
      fmtDate._cachedFormat = getSettingsFlat(getDb()).date_format || 'dd/mm/yyyy';
    } catch (_) {
      fmtDate._cachedFormat = 'dd/mm/yyyy';
    }
    fmtDate._cachedAt = Date.now();
  }
  return formatDateForDisplay(iso || d, fmtDate._cachedFormat);
}

function withFmtDate(rows, field = 'date') {
  if (!Array.isArray(rows)) return rows;
  return rows.map(r => ({ ...r, date_fmt: fmtDate(r[field]) }));
}

// ── Account lock ─────────────────────────────────────────────────
// An admin can lock a username from Users → Lock. A locked account is
// refused at BOTH login doors (desktop /api/login and the PWA's
// /api/auth/login) and its existing session tokens stop authenticating,
// so the lock bites immediately rather than at next sign-in.
//
// Returns the 403 body to send, or null when the account is active.
// One function so every door agrees on what "locked" means and says the
// same thing — a second copy of this rule is how one door ends up open.
const LOCKED_ACCOUNT_STATUS = 403;
function lockedAccountError(user) {
  if (!user || !user.locked_at) return null;
  return {
    error: 'account_locked',
    message: `This account is locked. Contact your administrator to unlock ${user.username}.`,
    username: user.username,
    locked_at: user.locked_at,
  };
}

// Auth middleware: verify a valid session, attach req.user/req.session.
// DOES NOT check role — use this for endpoints that any logged-in user
// (admin OR regular user) should be able to hit (GET list endpoints mostly).
function requireAuth(req, res, next) {
  const token = (req.headers.authorization || '').replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  const db = getDb();
  const session = db.get('SELECT * FROM sessions WHERE token = ?', [token]);
  if (!session) return res.status(403).json({ error: 'Session expired — please sign in again' });
  const user = db.get('SELECT * FROM users WHERE id = ?', [session.user_id]);
  if (!user) return res.status(403).json({ error: 'Unauthorized' });
  // Locking revokes sessions, so this normally never fires — it is the
  // backstop that makes the lock hold even if a token survives (a request
  // already in flight, a restored tab, a session row written by a path
  // that didn't clean up).
  const locked = lockedAccountError(user);
  if (locked) return res.status(LOCKED_ACCOUNT_STATUS).json(locked);
  // Touch last_used_at for cleanup / activity display
  db.run(`UPDATE sessions SET last_used_at = datetime('now','localtime') WHERE token = ?`, [token]);
  req.user = user;
  req.session = session;
  next();
}

// Admin-only middleware: gates mutations, settings, deletes, user management.
// Runs requireAuth first, then verifies role.
function requireAdmin(req, res, next) {
  requireAuth(req, res, (err) => {
    if (err) return next(err);
    if (!req.user || req.user.role !== 'admin') {
      return res.status(403).json({ error: 'Admin access required for this action' });
    }
    next();
  });
}

// Diagnostic snapshot of slow requests + event-loop blocks. Admin-only since
// it exposes request URLs. Console logs carry the same data for Railway logs.
app.get('/api/_perf', requireAdmin, (req, res) => res.json(perf.snapshot()));

// ══════════════════════════════════════════════════════════════
// ROLE-BASED PERMISSIONS
// ══════════════════════════════════════════════════════════════
// Four pre-defined role tiers, each granting a fixed set of capabilities.
// Capabilities are referenced by name everywhere in the code that needs
// permission gating, so adding/removing a capability touches one place.
//
// Hierarchy (least → most privileged):
//   viewer    — read-only
//   operator  — daily auction-floor work (lots, invoices, buyers/traders)
//   manager   — branch oversight (auctions, settings, revert)
//   admin     — full control (delete, user management, business state)
//
// Capability names are short snake_case strings. New capabilities are
// added by including the name in the appropriate role(s) below.
const ROLE_PERMISSIONS = {
  viewer: new Set([
    'view',           // read any list / detail
    'export',         // download XLSX / PDF / CSV exports
    'self_password', // change own password
    'lot_entry_view'  // also see the Lot Entry tab + its data (read-only)
                      // — viewers don't get lot_write so they can't modify,
                      //   but they can SEE the shared trade/lot data, which
                      //   is the expected behaviour for "authorised users
                      //   viewing shared valid data".
  ]),
  // Field-staff role for the auction-hall lot entry workflow. Sees only
  // the Lot Entry tab in the sidebar (everything else is gated by
  // `view`, which lot_entry intentionally lacks). The narrow scope —
  // create trades, search sellers, create/edit own lots — matches what
  // the original PWA admin exposed to non-admin users in the field.
  lot_entry: new Set([
    'self_password',
    'view',            // read shared trade/lot data — needed so multi-user
                       // sessions can all see the same in-progress entries.
                       // Without this, a second lot_entry user opening the
                       // same trade hit "do not have permission to view"
                       // because some shared endpoints require general view.
    'lot_entry_view',  // Lot Entry tab + its endpoints (auctions, lots, traders)
    'lot_write',       // create/edit own lots; trader search via lot-entry views
    'auction_write'    // create new trades on the fly during an auction day
  ]),
  operator: new Set([
    'view', 'export', 'self_password',
    'lot_entry_view', // operators can also use the Lot Entry tab if they want
    'lot_write',     // create/edit lots, calculate, validate, price-import
    'invoice_write', // generate sales/purchase/bills + edit
    'trader_write',  // create/edit/delete-bank traders
    'buyer_write'    // create/edit buyers (per user decision: tax fields editable)
  ]),
  manager: new Set([
    'view', 'export', 'self_password', 'lot_entry_view',
    'lot_write', 'invoice_write', 'trader_write', 'buyer_write',
    'auction_write',  // create/edit auctions (trades)
    'invoice_revert', // revert sales/purchase/bills (undo invoice)
    'settings_write', // edit company settings (rates, addresses, flags)
    'state_toggle',   // toggle business state TN ↔ KL
    'auction_desk'    // the Auction Desk — every document for a trade in
                      // one place. Manager and admin only.
  ]),
  admin: new Set([
    'view', 'export', 'self_password', 'lot_entry_view',
    'lot_write', 'invoice_write', 'trader_write', 'buyer_write',
    'auction_write', 'invoice_revert', 'settings_write', 'state_toggle',
    'auction_desk',
    'delete',       // delete any individual record
    'delete_all',   // bulk Delete All (sales, purchases, lots, etc.)
    'user_manage'   // create/delete users, reset passwords, revoke sessions
  ])
};

// Best-effort capability lookup. Unknown roles get treated as 'viewer'
// (safest default — fails closed instead of open).
function userHas(role, capability) {
  const perms = ROLE_PERMISSIONS[role] || ROLE_PERMISSIONS.viewer;
  return perms.has(capability);
}

// Middleware factory: returns an Express middleware that requires the
// authenticated user to have a specific capability.
//
// Usage:
//   app.post('/api/lots', requirePermission('lot_write'), handler)
//   app.delete('/api/invoices/:id', requirePermission('delete'), handler)
//
// Falls through to next() on success; sends 403 with a clear message
// indicating both the user's current role AND the capability required
// (helps the client show a useful error rather than a generic "denied").
function requirePermission(capability) {
  return (req, res, next) => {
    requireAuth(req, res, (err) => {
      if (err) return next(err);
      if (!req.user) return res.status(401).json({ error: 'Authentication required' });
      if (!userHas(req.user.role, capability)) {
        return res.status(403).json({
          error: `Your role (${req.user.role}) does not allow this action`,
          required: capability,
          role: req.user.role
        });
      }
      next();
    });
  };
}

// Same idea but accepts ANY of a list of capabilities. Used for endpoints
// that serve multiple roles — e.g., the trader search endpoint, which
// general operators reach through 'view' and lot-entry users reach
// through their own lot_entry_view capability.
function requireAnyPermission(...capabilities) {
  return (req, res, next) => {
    requireAuth(req, res, (err) => {
      if (err) return next(err);
      if (!req.user) return res.status(401).json({ error: 'Authentication required' });
      const hasAny = capabilities.some(c => userHas(req.user.role, c));
      if (!hasAny) {
        return res.status(403).json({
          error: `Your role (${req.user.role}) does not allow this action`,
          required: capabilities.join(' or '),
          role: req.user.role
        });
      }
      next();
    });
  };
}

// Convenience aliases — readable names for the most common gate points.
// Encapsulates the permission name so callers don't repeat string literals.
const requireView          = requirePermission('view');
const requireViewOrLotEntry = requireAnyPermission('view', 'lot_entry_view');
const requireLotWrite      = requirePermission('lot_write');
const requireInvoiceWrite  = requirePermission('invoice_write');
const requireInvoiceRevert = requirePermission('invoice_revert');
const requireTraderWrite   = requirePermission('trader_write');
const requireBuyerWrite    = requirePermission('buyer_write');
const requireAuctionWrite  = requirePermission('auction_write');
const requireSettingsWrite = requirePermission('settings_write');
const requireStateToggle   = requirePermission('state_toggle');
const requireDelete        = requirePermission('delete');
const requireDeleteAll     = requirePermission('delete_all');
const requireUserManage    = requirePermission('user_manage');
const requireExport        = requirePermission('export');
const requireAuctionDesk   = requirePermission('auction_desk');

// ══════════════════════════════════════════════════════════════
// SESSION POLICY — concurrent-login control
// ══════════════════════════════════════════════════════════════
// Two rules, both configurable under Settings → Logins & Sessions:
//
//   1. single_session — one active sign-in per username. A second person
//      typing the same username is refused with 409 `already_logged_in`
//      and told who holds it. There is no override button: an admin
//      clears a stuck session from Users → Sign out.
//
//   2. admin_login_alert — when an admin signs in while another admin is
//      already online, BOTH are told. The one signing in gets the notice
//      inline in the login response; the one already online gets a row in
//      session_alerts, drained by the /api/session-alerts poll.
//
// "Active" is deliberately not "a session row exists". Browsers get
// closed without logging out and those rows survive for 30 days, so a
// literal check would lock a user out of their own account until an
// admin intervened. A session only counts while its last request is
// inside the idle window (session_idle_minutes, default 15).
//
// Both login handlers — /api/login here and /api/auth/login in
// mobile-bridge.js — run these same helpers, so the desktop and the
// mobile PWA enforce one shared policy rather than two drifting copies.

const SESSION_IDLE_DEFAULT_MIN = 15;

// Idle window in minutes, clamped to 1 min .. 24 h. A zero/blank/garbage
// setting falls back to the default rather than disabling the window
// (a 0-minute window would make every session instantly stale, which
// silently turns the whole feature off).
function sessionIdleMinutes(db) {
  let n = parseInt(getSetting(db, 'session_idle_minutes'), 10);
  if (!Number.isFinite(n) || n <= 0) n = SESSION_IDLE_DEFAULT_MIN;
  return Math.min(n, 1440);
}

// SQLite modifier for the idle cutoff, e.g. '-15 minutes'. Compared
// against last_used_at, which requireAuth touches on every request.
function _idleCutoff(db) { return `-${sessionIdleMinutes(db)} minutes`; }

// Sessions of `userId` that are still inside the idle window, newest
// first. `excludeToken` drops one token from the result — used so a
// browser re-authenticating with its own still-valid token isn't
// treated as a stranger locking itself out.
function activeSessionsForUser(db, userId, excludeToken) {
  const rows = db.all(
    `SELECT token, device_label, created_at, last_used_at,
            CAST((julianday('now','localtime') - julianday(last_used_at)) * 1440 AS INTEGER) AS idle_min
       FROM sessions
      WHERE user_id = ?
        AND last_used_at > datetime('now','localtime', ?)
      ORDER BY last_used_at DESC`,
    [userId, _idleCutoff(db)]
  );
  return excludeToken ? rows.filter(r => r.token !== excludeToken) : rows;
}

// "Desktop" / "Mobile" from a user-agent — the same coarse split
// login_history already stores, so both surfaces read consistently.
function deviceKindFromUA(ua) {
  return /Mobile|Android|iPhone|iPad|iPod/i.test(String(ua || '')) ? 'Mobile' : 'Desktop';
}

// Human phrasing for how long ago a session last did something.
function _agoLabel(idleMin) {
  const m = Math.max(0, Number(idleMin) || 0);
  if (m < 1) return 'just now';
  if (m === 1) return '1 minute ago';
  if (m < 60) return `${m} minutes ago`;
  const h = Math.floor(m / 60);
  return h === 1 ? '1 hour ago' : `${h} hours ago`;
}

// Duplicate-login gate. Returns null when the login may proceed, or a
// { error, message, ... } body to send with 409 when it may not.
// `prevToken` is the caller's existing token, if it still holds one —
// re-authenticating from the same browser is always allowed.
function checkDuplicateLogin(db, user, prevToken) {
  if (String(getSetting(db, 'single_session') || 'true').toLowerCase() !== 'true') return null;
  // A presented token only excuses the login when it really belongs to
  // this user — otherwise anyone could paste a token to bypass the gate.
  let mine = '';
  if (prevToken) {
    const s = db.get('SELECT token, user_id FROM sessions WHERE token = ?', [String(prevToken)]);
    if (s && s.user_id === user.id) mine = s.token;
  }
  const active = activeSessionsForUser(db, user.id, mine);
  if (!active.length) return null;
  const s = active[0];
  const where = s.device_label ? deviceKindFromUA(s.device_label) : 'another device';
  return {
    error: 'already_logged_in',
    message: `Already ${user.username} is logged in (${where}, last active ${_agoLabel(s.idle_min)}). `
           + `Sign out there first, or ask an admin to sign that session out from Users.`,
    username: user.username,
    device: where,
    last_active: s.last_used_at || '',
  };
}

// Cross-notify concurrent admins. Writes one session_alerts row per
// other admin who is currently online, and returns the notice for the
// admin who just signed in ('' when there is nothing to say).
// Never throws — a failed notice must not fail the login.
function notifyConcurrentAdmins(db, user, ua) {
  try {
    if (String(getSetting(db, 'admin_login_alert') || 'true').toLowerCase() !== 'true') return '';
    if (String(user.role || '').toLowerCase() !== 'admin') return '';
    const others = db.all(
      `SELECT u.id, u.username, MAX(s.last_used_at) AS last_used_at
         FROM users u
         JOIN sessions s ON s.user_id = u.id
        WHERE LOWER(u.role) = 'admin'
          AND u.id != ?
          AND s.last_used_at > datetime('now','localtime', ?)
        GROUP BY u.id, u.username
        ORDER BY u.username`,
      [user.id, _idleCutoff(db)]
    );
    if (!others.length) return '';
    const device = deviceKindFromUA(ua);
    for (const o of others) {
      // Don't stack duplicates. Sign-in/sign-out cycles are common (a
      // dropped connection, a reload after a force sign-out), and three
      // identical "admin X signed in" banners say nothing the first one
      // didn't. One unacked notice per actor per recipient is enough.
      const pending = db.get(
        `SELECT id FROM session_alerts
          WHERE user_id = ? AND acked = 0 AND kind = 'admin_login' AND actor_username = ?`,
        [o.id, user.username]
      );
      if (pending) continue;
      db.run(
        `INSERT INTO session_alerts (user_id, kind, actor_username, actor_role, message, device)
         VALUES (?, 'admin_login', ?, 'admin', ?, ?)`,
        [
          o.id,
          user.username,
          `Another admin — "${user.username}" — just signed in on ${device}. You are both working on the same data.`,
          device,
        ]
      );
    }
    const names = others.map(o => `"${o.username}"`).join(', ');
    return others.length === 1
      ? `Another admin — ${names} — is already signed in. You are both working on the same data.`
      : `Other admins are already signed in: ${names}. You are all working on the same data.`;
  } catch (_) {
    return '';
  }
}

// ══════════════════════════════════════════════════════════════
// MOBILE PWA BRIDGE — must mount BEFORE any /api routes below.
// ══════════════════════════════════════════════════════════════
// All PWA-compat routes (/api/auth/*, /api/config, /api/status, /api/logo,
// /api/lots query-string form, trader-bank CRUD, print stubs) live in
// mobile-bridge.js. They register first so they win any path-pattern
// collisions with native spice-config routes — notably /api/lots/print-batch
// would otherwise match /api/lots/:auctionId. Centralising the delta in
// one file makes it easy to audit and remove later if we ever rewrite the
// mobile UI on spice-config's native API.
mountMobile(app, {
  getDb,
  requireAuth,
  hash,
  ROLE_PERMISSIONS,
  // Concurrent-login policy — shared with /api/login so the desktop and
  // the mobile PWA can't drift apart on who is allowed to sign in.
  checkDuplicateLogin,
  notifyConcurrentAdmins,
  // Account-lock policy — same reason: one rule, both login doors, so a
  // username an admin locked cannot sign in from the phone either.
  lockedAccountError,
  LOCKED_ACCOUNT_STATUS,
  // Fire-and-forget WhatsApp notification when an operator raises a
  // lot-reassign request. Defined later in the file (hoisted); safe to
  // reference here. Never throws into the mobile handler.
  onReassignRequest: (row) => { try { sendReassignRequestWhatsApp(getDb(), row); } catch (_) {} },
});

// ══════════════════════════════════════════════════════════════
// AUTH
// ══════════════════════════════════════════════════════════════

// Public branding (no auth) — login screen / topbar pulls company
// name + logo from settings. Returns only the safe-to-expose subset:
// trade name, short name, branch, GSTIN, and a logo URL when present.
// Theme + theme_custom_color + preset bundle are also exposed so the
// per-install branding (which customer this is) is applied BEFORE
// login — gives every device on this install the same look-and-feel
// even before the user signs in.
app.get('/api/branding', (req, res) => {
  try {
    const cfg = getSettingsFlat(getDb());
    const isKL = String(cfg.business_state || '').toUpperCase().includes('KERALA');
    const branch = (isKL ? cfg.kl_branch : cfg.tn_branch) || cfg.tn_branch || cfg.kl_branch || '';
    const gstin  = (isKL ? cfg.kl_gstin  : cfg.tn_gstin)  || cfg.tn_gstin  || cfg.kl_gstin  || '';
    const logoFile = path.join(__dirname, 'public', 'logo-ispl.png');
    // Preset = the full white-label bundle (color + density + font +
    // hide-appearance flag) configured by you via /admin/branding.
    // Empty string when no preset has been set — the frontend then
    // treats it as the legacy "default" state with Appearance visible.
    let presetConfig = null;
    if (cfg.preset_config) {
      try { presetConfig = JSON.parse(cfg.preset_config); }
      catch (_) { presetConfig = null; }
    }
    res.json({
      tradeName: cfg.trade_name || cfg.short_name || '',
      shortName: cfg.short_name || cfg.trade_name || '',
      branch,
      gstin,
      logoUrl: fs.existsSync(logoFile) ? '/logo-ispl.png' : null,
      // Per-install branding choices — empty string when the admin
      // hasn't picked one yet (frontend then falls back to localStorage
      // and finally to 'emerald').
      theme: cfg.theme || '',
      themeCustomColor: cfg.theme_custom_color || '',
      // Preset bundle. preset is the named slug (e.g. 'bluehill');
      // presetConfig is the full {theme, density, font, hideAppearance}
      // payload the frontend applies at boot.
      preset: cfg.tenant_preset || '',
      presetConfig,
    });
  } catch (e) {
    res.json({ tradeName: '', shortName: '', branch: '', gstin: '', logoUrl: null, theme: '', themeCustomColor: '', preset: '', presetConfig: null });
  }
});

// Persist per-install branding (theme + custom color). Upserts directly
// into company_settings — bypasses updateSettings() which only UPDATEs
// existing rows (and these two keys may not be in DEFAULTS yet on
// installs that pre-date the branding feature).
//
// Whitelisted to ONLY these two keys so a misbehaving client can't
// write arbitrary settings through this endpoint. Larger settings
// changes still go through PUT /api/company-settings.
app.put('/api/branding', requireSettingsWrite, (req, res) => {
  try {
    const db = getDb();
    const body = req.body || {};
    const allowed = {};
    if (typeof body.theme === 'string') {
      // Validate against the same theme list the frontend uses
      const THEMES = ['emerald','coral','violet','sunshine','electric','ocean','tech','minimal','trust','rose','indigo','teal','slate','custom'];
      if (THEMES.includes(body.theme)) allowed.theme = body.theme;
    }
    if (typeof body.themeCustomColor === 'string' && /^#[0-9a-fA-F]{6}$/.test(body.themeCustomColor)) {
      allowed.theme_custom_color = body.themeCustomColor;
    }
    if (!Object.keys(allowed).length) {
      return res.status(400).json({ error: 'No valid branding fields supplied' });
    }
    // INSERT OR REPLACE so the row is created on first write and
    // updated on subsequent writes. category='branding' so the row
    // is grouped sensibly if it ever lands in the Settings categories
    // view (currently appearance lives in its own card).
    const stmt = db.prepare(
      `INSERT INTO company_settings (key, value, category, label, field_type)
       VALUES (?, ?, 'branding', ?, 'text')
       ON CONFLICT(key) DO UPDATE SET value = excluded.value`
    );
    const labels = { theme: 'Theme', theme_custom_color: 'Custom primary color' };
    for (const [k, v] of Object.entries(allowed)) {
      stmt.run(k, String(v), labels[k] || k);
    }
    res.json({ success: true, updated: Object.keys(allowed).length });
  } catch (e) {
    res.status(500).json({ error: 'Branding save failed: ' + (e.message || e) });
  }
});

// ══════════════════════════════════════════════════════════════════
// TENANT PRESET (white-label switcher) — DEVELOPER ONLY
// ══════════════════════════════════════════════════════════════════
// The "preset" is a named bundle of color + density + font + hide
// flags. Lets you configure each customer install to look visually
// distinct without changes to the customer's data. End users never
// see this — the Appearance card in Settings is hidden once a preset
// is active.
//
// Access is gated by ADMIN_BRANDING_KEY (env var). The /admin/branding
// page expects ?key=<secret> on every request. Default key for dev is
// 'change-me' so a non-secured deploy is obvious in the URL.
//
// Pre-baked presets — extend this list to add more. Each preset is a
// pure config object; the frontend reads presetConfig from GET
// /api/branding and applies it at boot.
// Each preset also carries a `login` bundle { layout, style } so the
// sign-in page differs per customer too (layout = structure, style =
// palette). The frontend reads presetConfig.login at boot.
const TENANT_PRESETS = {
  cardamom: {
    label: 'Cardamom (default — premium spacious)',
    theme: 'emerald', customColor: '', density: 'roomy', font: 'jakarta', accent: 'glow', bg: 'mesh', hideAppearance: true,
    login: { layout: 'split', style: 'emerald' },
  },
  bluehill: {
    label: 'Bluehill (indigo + dense + inter)',
    theme: 'indigo', customColor: '', density: 'compact', font: 'inter', accent: 'gradient', bg: '', hideAppearance: true,
    login: { layout: 'topbar', style: 'royal' },
  },
  'western-ghats': {
    label: 'Western Ghats (teal + spacious + outfit)',
    theme: 'teal', customColor: '', density: 'spacious', font: 'outfit', accent: 'glow', bg: 'dots', hideAppearance: true,
    login: { layout: 'aside', style: 'ocean' },
  },
  slate: {
    label: 'Slate (corporate grey + dense + system)',
    theme: 'slate', customColor: '', density: 'compact', font: 'system', accent: '', bg: '', hideAppearance: true,
    login: { layout: 'showcase', style: 'royal' },
  },
  marigold: {
    label: 'Marigold (sunshine + roomy + jakarta)',
    theme: 'sunshine', customColor: '', density: 'roomy', font: 'jakarta', accent: 'gradient', bg: 'mesh', hideAppearance: true,
    login: { layout: 'aside', style: 'sunset' },
  },
  ocean: {
    label: 'Ocean (cool blue + roomy + inter)',
    theme: 'ocean', customColor: '', density: 'roomy', font: 'inter', accent: 'gradient', bg: 'dots', hideAppearance: true,
    login: { layout: 'split', style: 'ocean' },
  },
};
// Available font slugs that the frontend knows how to apply. Keep in
// sync with the <link>s and CSS variable handling in index.html.
const TENANT_FONTS = ['jakarta', 'inter', 'outfit', 'system'];
// Available density slugs. Frontend maps each to a `data-density` attr
// + CSS rules that adjust padding / corner radius / row heights.
const TENANT_DENSITIES = ['compact', 'roomy', 'spacious'];
// Available accent slugs — the "vibrant" treatment of buttons / KPI rails
// / cards. Frontend maps each to a `data-accent` attr. '' = flat (default).
const TENANT_ACCENTS = ['', 'gradient', 'glow'];
// Available backdrop slugs — themed page-background texture. Frontend maps
// each to a `data-bg` attr. '' = plain (default).
const TENANT_BACKDROPS = ['', 'dots', 'mesh'];
// Login-page structure + palette. Frontend maps these to `data-login-layout`
// and `data-login` on <body>. Keep in sync with _LOGIN_LAYOUTS / _LOGIN_STYLES
// in index.html.
const TENANT_LOGIN_LAYOUTS = ['split', 'topbar', 'aside', 'showcase'];
const TENANT_LOGIN_STYLES = ['aurora', 'sunset', 'ocean', 'emerald', 'royal', 'rose', 'forest', 'honey', 'grape', 'candy', 'lagoon', 'graphite', 'midnight'];

// Gatekeeper. Compares against ADMIN_BRANDING_KEY env var, falling back
// to 'change-me' so an unsecured deploy is loud — running ?key=change-me
// in production logs is a clear signal to set the env var.
function checkAdminKey(req) {
  const expected = process.env.ADMIN_BRANDING_KEY || 'change-me';
  const supplied = String(req.query.key || req.headers['x-admin-key'] || '');
  return supplied === expected && supplied.length > 0;
}

// GET /admin/branding?key=… — hidden HTML control panel. Lists presets,
// shows current selection, has a small form for the "custom" preset
// (manual color/density/font picker). NOT linked from anywhere in the
// app; you reach it by typing the URL.
app.get('/admin/branding', (req, res) => {
  if (!checkAdminKey(req)) {
    return res.status(403).type('html').send(
      '<html><body style="font-family:system-ui;padding:40px;text-align:center;color:#666"><h2>403 — Access denied</h2><p>This page requires a valid <code>?key=</code> in the URL.</p></body></html>'
    );
  }
  const db = getDb();
  const cfg = getSettingsFlat(db);
  const currentPreset = cfg.tenant_preset || '';
  let currentConfig = null;
  try { currentConfig = JSON.parse(cfg.preset_config || 'null'); } catch (_) {}

  const presetOptions = Object.entries(TENANT_PRESETS).map(([slug, p]) => {
    const sel = slug === currentPreset ? 'selected' : '';
    return `<option value="${slug}" ${sel}>${slug} — ${p.label}</option>`;
  }).join('');
  const customSel = currentPreset === 'custom' ? 'selected' : '';
  const noneSel = !currentPreset ? 'selected' : '';

  // Custom-preset form field defaults — populated from current config
  // if the active preset IS 'custom', otherwise blank.
  const c = (currentPreset === 'custom' && currentConfig) ? currentConfig : {};
  const cTheme    = c.theme || 'emerald';
  const cColor    = c.customColor || '';
  const cDensity  = c.density || 'roomy';
  const cFont     = c.font || 'jakarta';
  const cAccent   = c.accent || '';
  const cBg       = c.bg || '';
  const cHide     = c.hideAppearance !== false; // default true
  const cLogin    = (c.login && typeof c.login === 'object') ? c.login : {};
  const cLoginLayout = cLogin.layout || 'split';
  const cLoginStyle  = cLogin.style  || 'aurora';
  const cLoginTitle  = cLogin.title  || '';
  const cLoginSub    = cLogin.sub    || '';
  const cLoginCredit = cLogin.credit || '';

  // Human labels for the vibrant option slugs (slug '' = the plain default).
  const ACCENT_LABELS = { '': 'flat (plain)', gradient: 'gradient', glow: 'glow' };
  const BACKDROP_LABELS = { '': 'plain', dots: 'dots', mesh: 'mesh' };
  // Escape user-supplied text before dropping it into a value="" attribute.
  const escAttr = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  const themeOpts = ['emerald','coral','violet','sunshine','electric','ocean','tech','minimal','trust','rose','indigo','teal','slate','custom']
    .map(t => `<option value="${t}" ${t === cTheme ? 'selected' : ''}>${t}</option>`).join('');
  const densityOpts = TENANT_DENSITIES.map(d => `<option value="${d}" ${d === cDensity ? 'selected' : ''}>${d}</option>`).join('');
  const fontOpts = TENANT_FONTS.map(f => `<option value="${f}" ${f === cFont ? 'selected' : ''}>${f}</option>`).join('');
  const accentOpts = TENANT_ACCENTS.map(a => `<option value="${a}" ${a === cAccent ? 'selected' : ''}>${ACCENT_LABELS[a]}</option>`).join('');
  const backdropOpts = TENANT_BACKDROPS.map(b => `<option value="${b}" ${b === cBg ? 'selected' : ''}>${BACKDROP_LABELS[b]}</option>`).join('');
  const loginLayoutOpts = TENANT_LOGIN_LAYOUTS.map(l => `<option value="${l}" ${l === cLoginLayout ? 'selected' : ''}>${l}</option>`).join('');
  const loginStyleOpts = TENANT_LOGIN_STYLES.map(s => `<option value="${s}" ${s === cLoginStyle ? 'selected' : ''}>${s}</option>`).join('');

  // ── Company formats (bank payment + invoice layouts) ──────────────────
  // Which per-customer file/layout formats this install uses. Pre-filled from
  // the CURRENT settings and saved straight back to company_settings (so the
  // server-side exports honour them) — orthogonal to the visual preset bundle.
  let bankFmtOpts = '', salesTplOpts = '', purchaseTplOpts = '', agriTplOpts = '', commTplOpts = '', debitTplOpts = '';
  try {
    const { BANK_FORMATS } = require('./bank-formats');
    const curBank = cfg.bank_format || 'rtgs_neft';
    bankFmtOpts = Object.entries(BANK_FORMATS)
      .map(([k, p]) => `<option value="${k}" ${k === curBank ? 'selected' : ''}>${escAttr(p.label || k)}</option>`)
      .join('');
  } catch (_) { /* bank-formats unavailable — leave empty */ }
  try {
    const { listTemplates } = require('./pdf/invoice-templates');
    // Friendly labels for the layout dropdowns (raw ids like 'letterhead' read
    // poorly). Falls back to a title-cased id for any layout not listed here.
    const TPL_LABELS = { classic: 'Classic', letterhead: 'Letterhead', modern: 'Modern', pdfkit: 'Classic (Legacy)', rns: 'Letterhead' };
    const tplLabel = (id) => TPL_LABELS[id] || String(id).replace(/[-_]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
    const tplOpts = (docType, cur) => (listTemplates(docType) || ['classic'])
      .map(id => `<option value="${id}" ${id === cur ? 'selected' : ''}>${escAttr(tplLabel(id))}</option>`).join('');
    salesTplOpts    = tplOpts('sales-invoice',    cfg.sales_invoice_template    || 'classic');
    purchaseTplOpts = tplOpts('purchase-invoice', cfg.purchase_invoice_template || 'classic');
    agriTplOpts     = tplOpts('agri-bill',        cfg.agri_bill_template        || 'classic');
    commTplOpts     = tplOpts('commission-bill',  cfg.commission_bill_template  || 'classic');
    debitTplOpts    = tplOpts('debit-note',       cfg.debit_note_template       || 'letterhead');
  } catch (_) { /* invoice-templates unavailable — leave empty */ }

  const keyEsc = String(req.query.key).replace(/[<>'"&]/g, '');

  res.type('html').send(`<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>Tenant Branding — Admin</title>
<style>
  body { font-family: system-ui, -apple-system, sans-serif; max-width: 720px; margin: 40px auto; padding: 20px; color: #1f2937; background: #f9fafb; }
  h1 { font-size: 22px; margin: 0 0 4px; }
  h2 { font-size: 16px; margin: 24px 0 10px; color: #374151; }
  .sub { color: #6b7280; font-size: 13px; margin-bottom: 24px; }
  .card { background: #fff; border: 1px solid #e5e7eb; border-radius: 8px; padding: 20px; margin-bottom: 16px; }
  .current { background: #f0fdf4; border-color: #86efac; }
  label { display: block; font-size: 12px; font-weight: 600; color: #374151; margin: 12px 0 4px; text-transform: uppercase; letter-spacing: .3px; }
  select, input[type=text], input[type=color] { width: 100%; padding: 8px 10px; border: 1px solid #d1d5db; border-radius: 6px; font-size: 14px; box-sizing: border-box; }
  input[type=color] { height: 36px; padding: 2px; }
  input[type=checkbox] { margin-right: 6px; }
  button { background: #166534; color: #fff; border: 0; padding: 10px 18px; border-radius: 6px; font-size: 14px; font-weight: 600; cursor: pointer; }
  button.secondary { background: #6b7280; }
  button:hover { opacity: .9; }
  .row { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
  pre { background: #f3f4f6; padding: 10px; border-radius: 6px; font-size: 12px; overflow-x: auto; }
  .msg { display: none; padding: 10px; border-radius: 6px; margin-bottom: 16px; }
  .msg.ok { display: block; background: #dcfce7; color: #14532d; }
  .msg.err { display: block; background: #fee2e2; color: #991b1b; }
</style></head>
<body>
  <h1>Tenant branding</h1>
  <p class="sub">Hidden admin panel. Sets the white-label preset for this install. End users never see this URL or page.</p>
  <div id="msg" class="msg"></div>
  <div class="card current">
    <h2>Current setting</h2>
    <p><strong>Active preset:</strong> ${currentPreset || '<em>none (legacy mode — Appearance card visible to users)</em>'}</p>
    ${currentConfig ? `<pre>${JSON.stringify(currentConfig, null, 2)}</pre>` : ''}
  </div>
  <div class="card">
    <h2>Pick a pre-baked preset</h2>
    <label>Preset</label>
    <select id="preset-pick">
      <option value="" ${noneSel}>— none (show Appearance card to users) —</option>
      ${presetOptions}
      <option value="custom" ${customSel}>custom (use the form below)</option>
    </select>
    <p style="font-size: 12px; color: #6b7280; margin: 10px 0 0">Pick a named preset OR pick "custom" and fill in the form below.</p>
  </div>
  <div class="card">
    <h2>Custom preset (used only when preset = "custom")</h2>
    <div class="row">
      <div><label>Color theme</label><select id="custom-theme">${themeOpts}</select></div>
      <div><label>Custom hex (used when theme = "custom")</label><input type="color" id="custom-color" value="${cColor || '#166534'}"></div>
      <div><label>Density</label><select id="custom-density">${densityOpts}</select></div>
      <div><label>Font</label><select id="custom-font">${fontOpts}</select></div>
      <div><label>Accent (button / KPI style)</label><select id="custom-accent">${accentOpts}</select></div>
      <div><label>Backdrop (page texture)</label><select id="custom-bg">${backdropOpts}</select></div>
    </div>
    <label style="margin-top: 16px;"><input type="checkbox" id="custom-hide" ${cHide ? 'checked' : ''}> Hide Appearance card from users</label>
  </div>
  <div class="card">
    <h2>Login page (used only when preset = "custom")</h2>
    <p style="font-size: 12px; color: #6b7280; margin: 0 0 8px">Layout = page structure, palette = colour. Copy fields are optional — leave blank to keep the defaults.</p>
    <div class="row">
      <div><label>Login layout</label><select id="custom-login-layout">${loginLayoutOpts}</select></div>
      <div><label>Login palette</label><select id="custom-login-style">${loginStyleOpts}</select></div>
    </div>
    <label>Headline (optional)</label><input type="text" id="custom-login-title" value="${escAttr(cLoginTitle)}" placeholder="Run every e-Auction day with confidence.">
    <label>Sub-line (optional)</label><input type="text" id="custom-login-sub" value="${escAttr(cLoginSub)}" placeholder="From lot entry to ledger — all on one floor.">
    <label>Footer credit (optional)</label><input type="text" id="custom-login-credit" value="${escAttr(cLoginCredit)}" placeholder="Powered by KJ &amp; Co">
  </div>
  <div class="card">
    <h2>Company formats</h2>
    <p style="font-size: 12px; color: #6b7280; margin: 0 0 8px">The bank-payment file layout and invoice/bill PDF layouts this company uses. Saved straight to this install's settings — the app's exports honour them immediately. Independent of the visual preset above, so it has its own <strong>Save formats</strong> button (Apply preset does not touch these).</p>
    <div class="row">
      <div><label>Bank payment format</label><select id="fmt-bank">${bankFmtOpts}</select></div>
      <div><label>Sales invoice layout</label><select id="fmt-sales">${salesTplOpts}</select></div>
      <div><label>Purchase invoice layout</label><select id="fmt-purchase">${purchaseTplOpts}</select></div>
      <div><label>Bill of supply layout</label><select id="fmt-agri">${agriTplOpts}</select></div>
      <div><label>Commission bill layout</label><select id="fmt-comm">${commTplOpts}</select></div>
      <div><label>Debit note layout</label><select id="fmt-debit">${debitTplOpts}</select></div>
    </div>
    <div style="margin-top: 14px;"><button onclick="saveFormats()">Save formats</button></div>
  </div>
  <div style="display: flex; gap: 10px;">
    <button onclick="apply()">Apply preset</button>
    <button class="secondary" onclick="clearPreset()">Clear (revert to legacy mode)</button>
  </div>
  <script>
    const KEY = ${JSON.stringify(keyEsc)};
    function msg(text, ok) {
      const el = document.getElementById('msg');
      el.className = 'msg ' + (ok ? 'ok' : 'err');
      el.textContent = text;
    }
    async function apply() {
      const preset = document.getElementById('preset-pick').value;
      const body = { preset };
      if (preset === 'custom') {
        body.config = {
          theme: document.getElementById('custom-theme').value,
          customColor: document.getElementById('custom-color').value,
          density: document.getElementById('custom-density').value,
          font: document.getElementById('custom-font').value,
          accent: document.getElementById('custom-accent').value,
          bg: document.getElementById('custom-bg').value,
          hideAppearance: document.getElementById('custom-hide').checked,
          login: {
            layout: document.getElementById('custom-login-layout').value,
            style: document.getElementById('custom-login-style').value,
            title: document.getElementById('custom-login-title').value,
            sub: document.getElementById('custom-login-sub').value,
            credit: document.getElementById('custom-login-credit').value,
          },
        };
      }
      try {
        const r = await fetch('/api/admin/preset?key=' + encodeURIComponent(KEY), {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
        });
        const d = await r.json();
        if (!r.ok) return msg(d.error || 'Failed', false);
        msg('Applied. Reload your customer-facing app to see the change.', true);
        setTimeout(() => location.reload(), 800);
      } catch (e) { msg(e.message, false); }
    }
    async function clearPreset() {
      if (!confirm('Clear the active preset and show Appearance to users again?')) return;
      try {
        const r = await fetch('/api/admin/preset?key=' + encodeURIComponent(KEY), {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ preset: '' }),
        });
        if (!r.ok) return msg('Failed to clear', false);
        msg('Cleared.', true);
        setTimeout(() => location.reload(), 800);
      } catch (e) { msg(e.message, false); }
    }
    async function saveFormats() {
      const body = {
        bank_format:               document.getElementById('fmt-bank').value,
        sales_invoice_template:    document.getElementById('fmt-sales').value,
        purchase_invoice_template: document.getElementById('fmt-purchase').value,
        agri_bill_template:        document.getElementById('fmt-agri').value,
        commission_bill_template:  document.getElementById('fmt-comm').value,
        debit_note_template:       document.getElementById('fmt-debit').value,
      };
      try {
        const r = await fetch('/api/admin/formats?key=' + encodeURIComponent(KEY), {
          method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body),
        });
        const d = await r.json();
        if (!r.ok) return msg(d.error || 'Failed', false);
        msg('Formats saved: ' + (d.saved || []).join(', ') + '. Reload the app to see the change.', true);
        setTimeout(() => location.reload(), 900);
      } catch (e) { msg(e.message, false); }
    }
  </script>
</body></html>`);
});

// POST /api/admin/preset — receives the preset pick from the admin page.
// Key-gated like the GET. Writes tenant_preset (slug) + preset_config
// (full bundle as JSON) to company_settings so the frontend can pick
// it up via GET /api/branding without further auth.
app.post('/api/admin/preset', (req, res) => {
  if (!checkAdminKey(req)) return res.status(403).json({ error: 'Invalid admin key' });
  const db = getDb();
  const { preset, config } = req.body || {};
  const slug = String(preset || '').trim();

  let finalConfig = null;
  if (slug === '') {
    finalConfig = null;
  } else if (slug === 'custom') {
    if (!config || typeof config !== 'object') {
      return res.status(400).json({ error: 'custom preset requires a config object' });
    }
    finalConfig = {
      theme: String(config.theme || 'emerald'),
      customColor: /^#[0-9a-fA-F]{6}$/.test(config.customColor || '') ? config.customColor : '',
      density: TENANT_DENSITIES.includes(config.density) ? config.density : 'roomy',
      font: TENANT_FONTS.includes(config.font) ? config.font : 'jakarta',
      accent: TENANT_ACCENTS.includes(config.accent) ? config.accent : '',
      bg: TENANT_BACKDROPS.includes(config.bg) ? config.bg : '',
      hideAppearance: !!config.hideAppearance,
    };
    // Login page — validate layout/style against the allow-lists; carry
    // optional copy (trimmed + length-capped) only when non-empty.
    const loginIn = (config.login && typeof config.login === 'object') ? config.login : {};
    const login = {
      layout: TENANT_LOGIN_LAYOUTS.includes(loginIn.layout) ? loginIn.layout : 'split',
      style: TENANT_LOGIN_STYLES.includes(loginIn.style) ? loginIn.style : 'aurora',
    };
    const lTitle = String(loginIn.title || '').trim();
    const lSub = String(loginIn.sub || '').trim();
    const lCredit = String(loginIn.credit || '').trim();
    if (lTitle) login.title = lTitle.slice(0, 140);
    if (lSub) login.sub = lSub.slice(0, 220);
    if (lCredit) login.credit = lCredit.slice(0, 140);
    finalConfig.login = login;
  } else if (TENANT_PRESETS[slug]) {
    finalConfig = TENANT_PRESETS[slug];
  } else {
    return res.status(400).json({ error: `Unknown preset: ${slug}` });
  }

  const stmt = db.prepare(
    `INSERT INTO company_settings (key, value, category, label, field_type)
     VALUES (?, ?, 'branding', ?, 'text')
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`
  );
  stmt.run('tenant_preset', slug, 'Tenant preset');
  stmt.run('preset_config', finalConfig ? JSON.stringify(finalConfig) : '', 'Tenant preset config (JSON)');
  res.json({ success: true, preset: slug, config: finalConfig });
});

// POST /api/admin/formats — key-gated. Sets this company's per-customer file/
// layout formats (bank payment + the four invoice/bill PDF layouts) straight
// into company_settings, so the app's server-side exports honour them. Each
// value is validated against the registered options (BANK_FORMATS keys /
// on-disk .hbs template ids) — an unknown value is ignored, not saved.
app.post('/api/admin/formats', (req, res) => {
  if (!checkAdminKey(req)) return res.status(403).json({ error: 'Invalid admin key' });
  const db = getDb();
  const f = req.body || {};
  let BANK_FORMATS, listTemplates;
  try { ({ BANK_FORMATS } = require('./bank-formats')); } catch (_) { BANK_FORMATS = { rtgs_neft: 1 }; }
  try { ({ listTemplates } = require('./pdf/invoice-templates')); } catch (_) { listTemplates = () => ['classic']; }

  // key → { value, allowed[], category }. `allowed` guards against writing a
  // format that doesn't exist on this install.
  const specs = [
    { key: 'bank_format',               val: f.bank_format,               allowed: Object.keys(BANK_FORMATS),          cat: 'bank' },
    { key: 'sales_invoice_template',    val: f.sales_invoice_template,    allowed: listTemplates('sales-invoice'),     cat: 'invoice' },
    { key: 'purchase_invoice_template', val: f.purchase_invoice_template, allowed: listTemplates('purchase-invoice'),  cat: 'invoice' },
    { key: 'agri_bill_template',        val: f.agri_bill_template,        allowed: listTemplates('agri-bill'),         cat: 'invoice' },
    { key: 'commission_bill_template',  val: f.commission_bill_template,  allowed: listTemplates('commission-bill'),   cat: 'invoice' },
    { key: 'debit_note_template',       val: f.debit_note_template,       allowed: listTemplates('debit-note'),        cat: 'invoice' },
  ];

  const stmt = db.prepare(
    `INSERT INTO company_settings (key, value, category, label, field_type)
     VALUES (?, ?, ?, ?, 'select')
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`
  );
  const saved = [];
  for (const s of specs) {
    const v = String(s.val == null ? '' : s.val).trim();
    if (!v) continue;                              // field omitted → leave as-is
    if (!s.allowed.includes(v)) continue;          // unknown option → skip (don't clobber)
    stmt.run(s.key, v, s.cat, s.key);
    saved.push(s.key);
  }
  if (!saved.length) return res.status(400).json({ error: 'No valid format fields supplied' });
  res.json({ success: true, saved });
});

// Default-credential detection — used to force a password-change prompt
// on first login. We match on a small set of well-known seeded passwords:
//   - 'admin123' for the default admin user
//   - 'password' / 'changeme' / username==password for sloppy installs
// Anything else (even a custom-but-still-weak password) passes through;
// the user can always change it later via the Users tab.
const DEFAULT_PASSWORDS = ['admin123', 'password', 'changeme', '12345678'];
function isDefaultPassword(username, plaintext) {
  if (!plaintext) return false;
  const p = String(plaintext);
  if (DEFAULT_PASSWORDS.includes(p)) return true;
  if (p.toLowerCase() === String(username || '').toLowerCase()) return true;
  return false;
}

// ══════════════════════════════════════════════════════════════
// LICENSING — install ID, expiry probe, token apply
// ══════════════════════════════════════════════════════════════
//
// Both endpoints are deliberately auth-free: the renewal page lives
// outside the normal authenticated flow (the operator is locked out
// of /api/login while expired, so they need a way to apply a new
// token from a logged-out state). status is also used by the topbar
// countdown pill on the main UI.
app.get('/api/license/status', (req, res) => {
  res.set('Cache-Control', 'no-store');
  try {
    const status = license.getStatus(getDb());
    res.json(status);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});
app.post('/api/license/apply', (req, res) => {
  const token = (req.body && (req.body.token || req.body.license_token) || '').trim();
  if (!token) return res.status(400).json({ error: 'token required' });
  const result = license.applyToken(getDb(), token);
  if (!result.ok) return res.status(400).json(result);
  res.json(result);
});

// ─────────────────────────────────────────────────────────────
// Admin endpoint — back-channel for ops without shell access.
//
// Authenticated by the same LICENSE_SECRET used to sign tokens
// (only the developer knows it). When LICENSE_SECRET is unset on
// the server, this endpoint refuses ALL requests so the fallback
// development secret in license.js can never double as a remote
// admin backdoor on a misconfigured production deploy.
//
// Usage from anywhere (no shell required):
//
//   curl -X POST https://<app>/api/license/admin/set-expiry \
//     -H "content-type: application/json" \
//     -H "X-License-Secret: $LICENSE_SECRET" \
//     -d '{"expires_at":"2020-01-01"}'      # force expired (test)
//
//   curl -X POST https://<app>/api/license/admin/set-expiry \
//     -H "content-type: application/json" \
//     -H "X-License-Secret: $LICENSE_SECRET" \
//     -d '{"expires_at":"2026-07-02"}'      # restore
//
// Sets the row's active_token to NULL so the audit trail doesn't
// falsely attribute the new expiry to a previously-applied token.
// For token-driven history use POST /api/license/apply.
// ─────────────────────────────────────────────────────────────
function _requireLicenseAdmin(req) {
  const envSecret = String(process.env.LICENSE_SECRET || '').trim();
  if (!envSecret) {
    return { status: 403, error: 'admin disabled: LICENSE_SECRET env var is not set on this server' };
  }
  const provided = String(req.headers['x-license-secret'] || '').trim();
  if (!provided) {
    return { status: 403, error: 'X-License-Secret header required' };
  }
  // Constant-time compare on equal-length buffers. Bail before the
  // compare when lengths differ so we don't leak the secret length
  // (and so timingSafeEqual doesn't throw on a length mismatch).
  const a = Buffer.from(envSecret, 'utf8');
  const b = Buffer.from(provided, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return { status: 403, error: 'invalid X-License-Secret' };
  }
  return null;
}

app.post('/api/license/admin/set-expiry', (req, res) => {
  res.set('Cache-Control', 'no-store');
  const denied = _requireLicenseAdmin(req);
  if (denied) return res.status(denied.status).json({ error: denied.error });

  const body = req.body || {};
  const expires_at = String(body.expires_at || '').trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(expires_at)) {
    return res.status(400).json({ error: 'expires_at must be YYYY-MM-DD (e.g. 2026-07-31)' });
  }
  // Sanity bound — anything outside 2020-2099 is almost certainly a typo.
  // Tokens already issued past 2099 would also be unusable.
  const yr = Number(expires_at.slice(0, 4));
  if (yr < 2020 || yr > 2099) {
    return res.status(400).json({ error: 'expires_at year out of range (2020-2099)' });
  }

  try {
    const db = getDb();
    // Make sure the row exists — on a fresh install this endpoint may
    // be hit before any normal traffic has triggered the bootstrap.
    license.ensureState(db);
    db.run(
      'UPDATE license_state SET expires_at = ?, active_token = NULL WHERE id = 1',
      [expires_at]
    );
    res.json({ ok: true, status: license.getStatus(db) });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.post('/api/login', (req, res) => {
  // Hard licence gate before the credential check — when the install
  // is expired we don't even pretend to authenticate. The frontend
  // login script catches the 451 and redirects to /renew.html with
  // the install ID pre-filled.
  try {
    const lstatus = license.getStatus(getDb());
    if (lstatus.expired) {
      return res.status(451).json({
        error: 'license_expired',
        message: `Your access window ended on ${lstatus.expires_at}. Send the install ID below to your provider to receive a renewal token.`,
        install_id: lstatus.install_id,
        expires_at: lstatus.expires_at,
      });
    }
  } catch (_) { /* license check failed → let login through; fail-open is friendlier than a brick */ }
  const { username, password, device_label, prev_token } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing credentials' });
  const db = getDb();
  const user = db.get('SELECT * FROM users WHERE username = ?', [username]);
  if (!user || user.password_hash !== hash(password)) return res.status(401).json({ error: 'Invalid credentials' });
  // Locked account. Checked AFTER the credential check, like the duplicate
  // gate below, so a wrong password can't be used to enumerate which
  // usernames exist or which are locked.
  const locked = lockedAccountError(user);
  if (locked) return res.status(LOCKED_ACCOUNT_STATUS).json(locked);
  // One active sign-in per username. Runs AFTER the credential check so a
  // wrong password can't be used to probe who is currently online.
  const dup = checkDuplicateLogin(db, user, prev_token);
  if (dup) return res.status(409).json(dup);
  const token = crypto.randomBytes(32).toString('hex');
  // Create a new session row WITHOUT deleting any existing sessions —
  // this lets the same user stay logged in on multiple devices when the
  // single_session setting is off. When it's on, checkDuplicateLogin
  // above has already refused the second sign-in.
  db.run('INSERT INTO sessions (token, user_id, device_label) VALUES (?, ?, ?)',
    [token, user.id, device_label || (req.headers['user-agent'] || '').slice(0, 80)]);
  // Clean up very old sessions (> 30 days) so the table doesn't grow forever
  db.run(`DELETE FROM sessions WHERE last_used_at < datetime('now','-30 days')`);
  // Tell every other admin currently online, and collect the reciprocal
  // notice for this admin. Fires before the response so `notice` is
  // accurate; never throws.
  const notice = notifyConcurrentAdmins(db, user, req.headers['user-agent']);
  // Return the user's capabilities array so the client can hide buttons
  // they're not allowed to use. Server still validates every request.
  const permissions = Array.from(ROLE_PERMISSIONS[user.role] || ROLE_PERMISSIONS.viewer);
  // Flag a default-password login so the client can pop a "Change your
  // password" modal. We send the plaintext check result (not the hash)
  // so future password-strength rules can extend this without a
  // schema change.
  const mustChangePassword = isDefaultPassword(username, password);
  res.json({
    token, role: user.role, username: user.username, permissions, mustChangePassword,
    // Home branch — blank for admins and for anyone not assigned one.
    // The Lot Entry screen locks its branch dropdown to this value.
    branch: user.branch || '',
    notice,
  });
});
app.post('/api/logout', (req, res) => {
  const t = (req.headers.authorization||'').replace('Bearer ','');
  if (t) getDb().run('DELETE FROM sessions WHERE token = ?', [t]);
  res.json({ success: true });
});
app.get('/api/me', requireAnyPermission('view', 'lot_entry_view', 'self_password'), (req, res) => {
  const permissions = Array.from(ROLE_PERMISSIONS[req.user.role] || ROLE_PERMISSIONS.viewer);
  res.json({
    username: req.user.username, role: req.user.role, permissions,
    branch: req.user.branch || '',
  });
});

// ══════════════════════════════════════════════════════════════
// SESSION ALERTS — "another admin just signed in" inbox
// ══════════════════════════════════════════════════════════════
// Polled by the desktop UI (see pollSessionAlerts in index.html) on the
// same cadence as the grade-2 alert poll. Only ever returns the calling
// user's own unacked rows, so there's no permission tier beyond "signed
// in" — a lot_entry user has no `view` permission but still needs to see
// a notice addressed to them.
app.get('/api/session-alerts', requireAnyPermission('view', 'lot_entry_view', 'self_password'), (req, res) => {
  const db = getDb();
  const alerts = db.all(
    `SELECT id, kind, actor_username, actor_role, message, device, created_at
       FROM session_alerts
      WHERE user_id = ? AND acked = 0
      ORDER BY id DESC LIMIT 20`,
    [req.user.id]
  );
  res.json({ alerts });
});

app.post('/api/session-alerts/:id/ack', requireAnyPermission('view', 'lot_entry_view', 'self_password'), (req, res) => {
  const db = getDb();
  // Scoped to the caller — you can only dismiss your own notices.
  db.run('UPDATE session_alerts SET acked = 1 WHERE id = ? AND user_id = ?', [req.params.id, req.user.id]);
  res.json({ success: true });
});

// ══════════════════════════════════════════════════════════════
// USER MANAGEMENT (admin-only)
// ══════════════════════════════════════════════════════════════
// The branch values an admin may assign to a user — exactly the br1..br9
// entries configured under Settings → Branches & Contacts, uppercased and
// blank-filtered. Assigning anything else would produce a lock nobody can
// satisfy (lots.branch only ever holds one of these).
function configuredBranches(db) {
  const rows = db.all(
    `SELECT value FROM company_settings
      WHERE category = 'branches' AND key LIKE 'br_'
      ORDER BY key`
  );
  return rows.map(r => String(r.value || '').trim().toUpperCase()).filter(Boolean);
}

// ══════════════════════════════════════════════════════════════
// PER-USER SCREENS
// ══════════════════════════════════════════════════════════════
// The install-wide flag_* settings are the DEFAULT for every screen; a row in
// user_screen_flags overrides one of them for one user, in either direction.
// That is what lets one operator work from the Auction Manager while everyone
// else keeps the Auction Desk, without either screen having to be on for the
// whole site.
//
// NOT a permission — see the note on the table in db.js. Role capabilities
// still decide what a user may DO; this decides what is worth showing them.

// Every screen's raw override for one user: { flag_key: 'true' | 'false' }.
// A key that is absent means "inherit the install default".
function screenOverrides(db, userId) {
  const out = {};
  try {
    for (const r of db.all('SELECT flag_key, value FROM user_screen_flags WHERE user_id = ?', [userId])) {
      if (SCREEN_FLAG_KEYS.has(r.flag_key)) out[r.flag_key] = String(r.value);
    }
  } catch (_) { /* table missing on a very old DB — everyone inherits */ }
  return out;
}

// What this user should actually SEE: the install default for each screen,
// with their own overrides laid on top. Returned as 'true'/'false' strings so
// the client can overlay it straight onto the settings object it already
// reads, and every existing data-feat-* rule keeps working untouched.
function effectiveScreens(db, userId) {
  const cfg = getSettingsFlat(db);
  const over = screenOverrides(db, userId);
  const out = {};
  for (const f of SCREEN_FLAGS) {
    const on = Object.prototype.hasOwnProperty.call(over, f.key)
      ? over[f.key] === 'true'
      : screenFlagDefault(cfg, f.key);
    out[f.key] = on ? 'true' : 'false';
  }
  return out;
}

// One screen, for one user, as a boolean — the server-side gate. Routes that
// belong to an optional screen must ask THIS rather than reading the install
// flag, or a user who has been given a screen the install has off would be
// handed the UI and then refused its data.
function screenOnFor(db, userId, key) {
  return effectiveScreens(db, userId)[key] === 'true';
}

// The signed-in user's own effective screens. Same permission tier as
// /api/me: a lot_entry-only account has no `view` capability but still has a
// sidebar, so it still needs to know which screens it has.
app.get('/api/me/screens', requireAnyPermission('view', 'lot_entry_view', 'self_password'), (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.json(effectiveScreens(getDb(), req.user.id));
});

// Admin view of ONE user's screens: the install default, this user's override
// (or null for inherit), and the resulting effective value — so the panel can
// show "Inherit (on)" without the client re-deriving defaults.
app.get('/api/users/:id/screens', requireUserManage, (req, res) => {
  const db = getDb();
  const user = db.get('SELECT id, username, role FROM users WHERE id = ?', [req.params.id]);
  if (!user) return res.status(404).json({ error: 'User not found' });
  const cfg = getSettingsFlat(db);
  const over = screenOverrides(db, user.id);
  const eff = effectiveScreens(db, user.id);
  res.json({
    user: { id: user.id, username: user.username, role: user.role },
    flags: SCREEN_FLAGS.map(f => ({
      key: f.key,
      label: f.label,
      note: f.note || null,
      installDefault: screenFlagDefault(cfg, f.key),
      override: Object.prototype.hasOwnProperty.call(over, f.key) ? (over[f.key] === 'true') : null,
      effective: eff[f.key] === 'true',
      // The Auction Desk needs the auction_desk ROLE capability on top of the
      // screen being on. Saying so here stops an admin switching it on for a
      // clerk and being puzzled that nothing appears.
      requiresCapability: f.key === 'flag_auction_desk' ? 'auction_desk' : null,
    })),
  });
});

// Save one user's overrides. Body: { overrides: { flag_key: true|false|null } }
// — null (or a key simply omitted from the map) CLEARS the override, putting
// that screen back on the install default.
app.put('/api/users/:id/screens', requireUserManage, (req, res) => {
  const db = getDb();
  const user = db.get('SELECT id, username FROM users WHERE id = ?', [req.params.id]);
  if (!user) return res.status(404).json({ error: 'User not found' });
  const body = (req.body && req.body.overrides) || {};
  if (typeof body !== 'object' || Array.isArray(body)) {
    return res.status(400).json({ error: 'overrides must be an object of flag_key → true | false | null' });
  }
  const unknown = Object.keys(body).filter(k => !SCREEN_FLAG_KEYS.has(k));
  if (unknown.length) {
    return res.status(400).json({ error: `Not a per-user screen: ${unknown.join(', ')}` });
  }
  for (const [key, val] of Object.entries(body)) {
    if (val === null || val === undefined || val === '') {
      db.run('DELETE FROM user_screen_flags WHERE user_id = ? AND flag_key = ?', [user.id, key]);
      continue;
    }
    const on = (val === true || String(val).toLowerCase() === 'true') ? 'true' : 'false';
    db.run(
      `INSERT INTO user_screen_flags (user_id, flag_key, value, updated_at, updated_by)
            VALUES (?,?,?, datetime('now','localtime'), ?)
       ON CONFLICT(user_id, flag_key) DO UPDATE
            SET value = excluded.value,
                updated_at = excluded.updated_at,
                updated_by = excluded.updated_by`,
      [user.id, key, on, req.user.username || ''],
    );
  }
  res.json({ ok: true, screens: effectiveScreens(db, user.id) });
});

app.get('/api/users', requireUserManage, (req, res) => {
  const db = getDb();
  const users = db.all(`
    SELECT u.id, u.username, u.role, u.branch, u.created_at,
      u.locked_at, u.locked_by,
      (SELECT COUNT(*) FROM sessions s WHERE s.user_id = u.id) as active_sessions,
      (SELECT MAX(last_used_at) FROM sessions s WHERE s.user_id = u.id) as last_active
    FROM users u ORDER BY u.id ASC
  `);
  // Ship the branch list alongside so the Users screen can render the
  // assign-branch dropdown without a second round-trip to settings.
  res.json({ users, branches: configuredBranches(db) });
});

app.post('/api/users', requireUserManage, (req, res) => {
  const { username, password, role, branch } = req.body || {};
  if (!username || !password) return res.status(400).json({ error: 'username and password are required' });
  if (password.length < 4) return res.status(400).json({ error: 'Password must be at least 4 characters' });
  if (!/^[a-zA-Z0-9_.-]{3,30}$/.test(username)) return res.status(400).json({ error: 'Username: 3–30 chars, letters/digits/._- only' });
  // Validate role against the known set. Default to 'operator' (the most
  // common and least privileged write-capable role) if missing or invalid.
  // Legacy 'user' role is mapped to 'viewer' for backward compat.
  const VALID_ROLES = ['viewer', 'lot_entry', 'operator', 'manager', 'admin'];
  let finalRole = (role || '').toLowerCase();
  if (finalRole === 'user') finalRole = 'viewer';
  if (!VALID_ROLES.includes(finalRole)) finalRole = 'operator';
  const db = getDb();
  const existing = db.get('SELECT id FROM users WHERE username = ?', [username]);
  if (existing) return res.status(400).json({ error: 'Username already exists' });
  // Home branch. Admins are never branch-locked — they oversee every
  // depot — so any branch sent with an admin role is dropped rather than
  // rejected (the UI hides the field for admins anyway).
  let finalBranch = String(branch || '').trim().toUpperCase();
  if (finalRole === 'admin') finalBranch = '';
  if (finalBranch && !configuredBranches(db).includes(finalBranch)) {
    return res.status(400).json({ error: `"${finalBranch}" is not a configured branch — add it under Settings → Branches & Contacts first` });
  }
  db.run(
    'INSERT INTO users (username, password_hash, role, branch) VALUES (?, ?, ?, ?)',
    [username, hash(password), finalRole, finalBranch]
  );
  const created = db.get('SELECT id, username, role, branch FROM users WHERE username = ?', [username]);
  res.json({ success: true, id: created ? created.id : null, username, role: finalRole, branch: finalBranch });
});

// Assign / clear a user's home branch. Admin-only. Passing an empty
// branch removes the lock (the user can pick any branch again).
app.put('/api/users/:id/branch', requireUserManage, (req, res) => {
  const db = getDb();
  const target = db.get('SELECT id, username, role FROM users WHERE id = ?', [req.params.id]);
  if (!target) return res.status(404).json({ error: 'User not found' });
  if (String(target.role || '').toLowerCase() === 'admin') {
    return res.status(400).json({ error: 'Admins are not branch-locked — they need access to every branch' });
  }
  const wanted = String((req.body || {}).branch || '').trim().toUpperCase();
  if (wanted && !configuredBranches(db).includes(wanted)) {
    return res.status(400).json({ error: `"${wanted}" is not a configured branch — add it under Settings → Branches & Contacts first` });
  }
  db.run('UPDATE users SET branch = ? WHERE id = ?', [wanted, target.id]);
  res.json({ success: true, username: target.username, branch: wanted });
});

// ── Lock / unlock a user account ─────────────────────────────────
// Body { locked: true|false }. Locking is the reversible alternative to
// deleting an account: the password and everything the user ever entered
// stay put, but they cannot sign in on desktop OR mobile, and any session
// they still hold is revoked so the lock bites immediately.
//
// Two rails, both about not painting yourself into a corner:
//   • you cannot lock your OWN account — the next page load would throw
//     you out of the very screen that undoes it
//   • you cannot lock the LAST unlocked admin — nobody would be left who
//     could unlock anyone, and the install would need a DB edit to recover
app.put('/api/users/:id/lock', requireUserManage, (req, res) => {
  const db = getDb();
  const target = db.get('SELECT id, username, role, locked_at FROM users WHERE id = ?', [req.params.id]);
  if (!target) return res.status(404).json({ error: 'User not found' });
  const wantLocked = !!(req.body || {}).locked;

  if (wantLocked) {
    if (target.id === req.user.id) {
      return res.status(400).json({ error: 'You cannot lock your own account while signed in' });
    }
    if (String(target.role || '').toLowerCase() === 'admin' && !target.locked_at) {
      const otherAdmins = db.get(
        `SELECT COUNT(*) AS n FROM users
          WHERE LOWER(role) = 'admin' AND id != ? AND locked_at IS NULL`, [target.id]).n;
      if (otherAdmins < 1) {
        return res.status(400).json({ error: 'Cannot lock the last active admin — nobody would be left to unlock accounts' });
      }
    }
  }

  if (wantLocked) {
    db.run(`UPDATE users SET locked_at = datetime('now','localtime'), locked_by = ? WHERE id = ?`,
      [req.user.username, target.id]);
    // Revoke every session so the lock applies NOW. Without this the user
    // keeps working from an open tab until their token happens to expire,
    // which is not what "locked" means to the admin who just clicked it.
    db.run('DELETE FROM sessions WHERE user_id = ?', [target.id]);
  } else {
    db.run(`UPDATE users SET locked_at = NULL, locked_by = '' WHERE id = ?`, [target.id]);
  }
  const after = db.get('SELECT id, username, locked_at, locked_by FROM users WHERE id = ?', [target.id]);
  res.json({ success: true, username: after.username, locked: !!after.locked_at,
             locked_at: after.locked_at || '', locked_by: after.locked_by || '' });
});

// Force-sign-out every session of a user. The escape hatch for the
// single_session block: when someone's browser died mid-session and the
// idle window hasn't elapsed yet, an admin clears it here instead of
// making them wait it out.
app.post('/api/users/:id/revoke-sessions', requireUserManage, (req, res) => {
  const db = getDb();
  const target = db.get('SELECT id, username FROM users WHERE id = ?', [req.params.id]);
  if (!target) return res.status(404).json({ error: 'User not found' });
  const n = (db.get('SELECT COUNT(*) as c FROM sessions WHERE user_id = ?', [target.id]) || {}).c || 0;
  db.run('DELETE FROM sessions WHERE user_id = ?', [target.id]);
  res.json({ success: true, username: target.username, revoked: n });
});

// Update an existing user's role (for promoting/demoting users without
// recreating them). Admin-only — same gate as creating users.
app.put('/api/users/:id/role', requireUserManage, (req, res) => {
  const { role } = req.body || {};
  const VALID_ROLES = ['viewer', 'lot_entry', 'operator', 'manager', 'admin'];
  let finalRole = String(role || '').toLowerCase();
  if (finalRole === 'user') finalRole = 'viewer';
  if (!VALID_ROLES.includes(finalRole)) {
    return res.status(400).json({ error: `Role must be one of: ${VALID_ROLES.join(', ')}` });
  }
  const db = getDb();
  const target = db.get('SELECT id, username, role FROM users WHERE id = ?', [req.params.id]);
  if (!target) return res.status(404).json({ error: 'User not found' });
  // Safety: don't let admins demote the last remaining admin (would lock
  // everyone out of user management).
  if (target.role === 'admin' && finalRole !== 'admin') {
    const adminCount = db.get(`SELECT COUNT(*) as n FROM users WHERE role = 'admin'`).n;
    if (adminCount <= 1) {
      return res.status(400).json({ error: 'Cannot demote the last admin — promote someone else first' });
    }
  }
  db.run('UPDATE users SET role = ? WHERE id = ?', [finalRole, target.id]);
  // Promoting to admin drops any branch lock — admins oversee every depot,
  // and leaving a stale branch on the row would silently re-apply if they
  // were later demoted back to operator.
  if (finalRole === 'admin') db.run("UPDATE users SET branch = '' WHERE id = ?", [target.id]);
  res.json({ success: true, username: target.username, role: finalRole });
});

app.put('/api/users/:id/password', requireUserManage, (req, res) => {
  const { password } = req.body || {};
  if (!password || password.length < 4) return res.status(400).json({ error: 'Password must be at least 4 characters' });
  const db = getDb();
  const user = db.get('SELECT id, username FROM users WHERE id = ?', [req.params.id]);
  if (!user) return res.status(404).json({ error: 'User not found' });
  db.run('UPDATE users SET password_hash = ? WHERE id = ?', [hash(password), user.id]);
  // Invalidate all sessions of that user (force re-login after password change)
  db.run('DELETE FROM sessions WHERE user_id = ?', [user.id]);
  res.json({ success: true, username: user.username });
});

app.delete('/api/users/:id', requireUserManage, (req, res) => {
  const db = getDb();
  const target = db.get('SELECT id, username, role FROM users WHERE id = ?', [req.params.id]);
  if (!target) return res.status(404).json({ error: 'User not found' });
  // Safety: don't let admin delete themselves
  if (target.id === req.user.id) return res.status(400).json({ error: 'You cannot delete your own account while signed in' });
  // Safety: never allow deleting the last remaining user
  const total = db.get('SELECT COUNT(*) as c FROM users').c;
  if (total <= 1) return res.status(400).json({ error: 'Cannot delete the last remaining user' });
  db.run('DELETE FROM sessions WHERE user_id = ?', [target.id]);
  // Screen overrides are keyed by user id, which SQLite reuses on the next
  // AUTOINCREMENT-less insert — leaving them behind would silently hand a
  // deleted operator's screen set to whoever took their id.
  db.run('DELETE FROM user_screen_flags WHERE user_id = ?', [target.id]);
  db.run('DELETE FROM users WHERE id = ?', [target.id]);
  res.json({ success: true, username: target.username });
});

// Change own password — shortcut that doesn't require user id
app.put('/api/me/password', requirePermission('self_password'), (req, res) => {
  const { current_password, new_password } = req.body || {};
  if (!current_password || !new_password) return res.status(400).json({ error: 'Both current and new password required' });
  if (new_password.length < 4) return res.status(400).json({ error: 'New password must be at least 4 characters' });
  const db = getDb();
  const user = db.get('SELECT * FROM users WHERE id = ?', [req.user.id]);
  if (!user || user.password_hash !== hash(current_password)) return res.status(401).json({ error: 'Current password is incorrect' });
  db.run('UPDATE users SET password_hash = ? WHERE id = ?', [hash(new_password), user.id]);
  // Kill all OTHER sessions (keep current one)
  db.run('DELETE FROM sessions WHERE user_id = ? AND token != ?', [user.id, req.session.token]);
  res.json({ success: true });
});

// See my active sessions (all devices signed in as me)
app.get('/api/me/sessions', requireView, (req, res) => {
  const db = getDb();
  const sessions = db.all(
    `SELECT token, device_label, created_at, last_used_at,
            CASE WHEN token = ? THEN 1 ELSE 0 END as is_current
     FROM sessions WHERE user_id = ? ORDER BY last_used_at DESC`,
    [req.session.token, req.user.id]
  );
  // Mask tokens — only show last 8 chars
  res.json(sessions.map(s => ({ ...s, token: '…' + (s.token || '').slice(-8) })));
});

// Revoke (log out) another session I own
app.delete('/api/me/sessions/:tokenSuffix', requireView, (req, res) => {
  const suffix = req.params.tokenSuffix;
  const db = getDb();
  // Find session by matching suffix, for THIS user only
  const sessions = db.all('SELECT token FROM sessions WHERE user_id = ?', [req.user.id]);
  const match = sessions.find(s => (s.token || '').endsWith(suffix));
  if (!match) return res.status(404).json({ error: 'Session not found' });
  if (match.token === req.session.token) return res.status(400).json({ error: 'Use Logout to end your current session' });
  db.run('DELETE FROM sessions WHERE token = ?', [match.token]);
  res.json({ success: true });
});

