app.get('/api/buyers', requireView, (req, res) => {
  // Same pagination + full-table-search contract as /api/traders:
  //   • `?page=` + `?pageSize=` → { rows, total, page, pageSize }
  //   • `?all=1`                → bare array, every row (no LIMIT)
  //   • `?search=` (no page)    → bare array, search runs over ALL rows
  //   • no params               → bare array, top 500 (legacy)
  const { search, all } = req.query;
  const page     = Math.max(1, parseInt(req.query.page, 10) || 1);
  const pageSize = Math.min(500, Math.max(1, parseInt(req.query.pageSize, 10) || 50));
  const offset   = (page - 1) * pageSize;
  const wantPaged = req.query.page != null || req.query.pageSize != null;
  const db = getDb();

  let where = '', params = [];
  if (search) {
    const q = `%${search}%`;
    const ors = ['buyer LIKE ?', 'buyer1 LIKE ?', 'tel LIKE ?', 'gstin LIKE ?', 'pan LIKE ?', 'pla LIKE ?', 'ti LIKE ?', 'code LIKE ?'];
    params = [q, q, q, q, q, q, q, q];
    // Phone typed with spaces / dashes / +91 — digits-only comparison.
    const phone = smartPhoneDigits(search);
    if (phone) { ors.push(`${smartPhoneSql('tel')} LIKE ?`); params.push(`%${phone}%`); }
    where = 'WHERE ' + ors.join(' OR ');
  }

  if (wantPaged) {
    const total = db.get(`SELECT COUNT(*) AS c FROM buyers ${where}`, params).c;
    const rows = db.all(
      `SELECT * FROM buyers ${where} ORDER BY buyer1 LIMIT ? OFFSET ?`,
      [...params, pageSize, offset]
    );
    return res.json({ rows, total, page, pageSize });
  }

  if (search) {
    // Search now runs over the WHOLE table, not just the first 500.
    // Fixes the bug where codes alphabetically past the 500 boundary
    // (e.g. HRS0, HSR) were unreachable via typing in the lot edit.
    return res.json(db.all(
      `SELECT * FROM buyers ${where} ORDER BY buyer1 LIMIT ?`,
      [...params, pageSize]
    ));
  }
  // `?all=1` returns the unbounded master so the lot-edit autocomplete
  // can cache every code — the default 500-row cap was hiding codes
  // past that boundary (e.g. HRS0) from the dropdown AND from the
  // post-change lookup, surfacing as "No buyer found for code".
  if (all === '1' || all === 'true') {
    return res.json(db.all('SELECT * FROM buyers ORDER BY buyer1'));
  }
  res.json(db.all('SELECT * FROM buyers ORDER BY buyer1 LIMIT 500'));
});
app.post('/api/buyers', requireBuyerWrite, (req, res) => {
  const b = normalizeBuyer(req.body);
  const db = getDb();
  // Hard-block duplicate buyers by Buyer Code (`buyer`) and Short Alias
  // (`code`). Schema doesn't enforce uniqueness but the UIs expect both
  // to be unique; server check protects every code path.
  const _buyerChk = String(b.buyer || '').trim();
  if (_buyerChk) {
    const _exist = db.get('SELECT id, buyer1, buyer FROM buyers WHERE UPPER(TRIM(buyer)) = UPPER(?) LIMIT 1', [_buyerChk]);
    if (_exist) {
      return res.status(409).json({ error: `Buyer Code "${_buyerChk}" already on buyer "${_exist.buyer1 || _exist.buyer}"` });
    }
  }
  const _codeChk = String(b.code || '').trim();
  if (_codeChk) {
    const _exist = db.get('SELECT id, buyer1, buyer FROM buyers WHERE UPPER(TRIM(code)) = UPPER(?) LIMIT 1', [_codeChk]);
    if (_exist) {
      return res.status(409).json({ error: `Short alias "${_codeChk.toUpperCase()}" already on buyer "${_exist.buyer1 || _exist.buyer}"` });
    }
  }
  db.run(`INSERT INTO buyers (
      buyer, buyer1, code, sbl, add1, add2, pla, pin, state, st_code,
      gstin, pan, tan, tel, ti, sale, email, tdsq,
      cbuyer1, cadd1, cadd2, cpla, cpin, cstate, cst_code, cgstin
    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
    [b.buyer, b.buyer1||'', b.code||'', b.sbl||'', b.add1||'', b.add2||'', b.pla||'', b.pin||'', b.state||'', b.st_code||'',
     b.gstin||'', b.pan||'', b.tan||'', b.tel||'', b.ti||'', b.sale||'L', b.email||'', b.tdsq||'',
     b.cbuyer1||'', b.cadd1||'', b.cadd2||'', b.cpla||'', b.cpin||'', b.cstate||'', b.cst_code||'', b.cgstin||'']);
  res.json({ success: true });
});
app.put('/api/buyers/:id', requireBuyerWrite, (req, res) => {
  const b = normalizeBuyer(req.body);
  const db = getDb();
  // Same uniqueness guards as POST, with the row's own id excluded so
  // re-saving an unchanged buyer still works.
  const _buyerChk = String(b.buyer || '').trim();
  if (_buyerChk) {
    const _exist = db.get(
      'SELECT id, buyer1, buyer FROM buyers WHERE UPPER(TRIM(buyer)) = UPPER(?) AND id <> ? LIMIT 1',
      [_buyerChk, req.params.id]
    );
    if (_exist) {
      return res.status(409).json({ error: `Buyer Code "${_buyerChk}" already on buyer "${_exist.buyer1 || _exist.buyer}"` });
    }
  }
  const _codeChk = String(b.code || '').trim();
  if (_codeChk) {
    const _exist = db.get(
      'SELECT id, buyer1, buyer FROM buyers WHERE UPPER(TRIM(code)) = UPPER(?) AND id <> ? LIMIT 1',
      [_codeChk, req.params.id]
    );
    if (_exist) {
      return res.status(409).json({ error: `Short alias "${_codeChk.toUpperCase()}" already on buyer "${_exist.buyer1 || _exist.buyer}"` });
    }
  }
  db.run(`UPDATE buyers SET
      buyer=?, buyer1=?, code=?, sbl=?, add1=?, add2=?, pla=?, pin=?, state=?, st_code=?,
      gstin=?, pan=?, tan=?, tel=?, ti=?, sale=?, email=?, tdsq=?,
      cbuyer1=?, cadd1=?, cadd2=?, cpla=?, cpin=?, cstate=?, cst_code=?, cgstin=?
    WHERE id=?`,
    [b.buyer, b.buyer1||'', b.code||'', b.sbl||'', b.add1||'', b.add2||'', b.pla||'', b.pin||'', b.state||'', b.st_code||'',
     b.gstin||'', b.pan||'', b.tan||'', b.tel||'', b.ti||'', b.sale||'L', b.email||'', b.tdsq||'',
     b.cbuyer1||'', b.cadd1||'', b.cadd2||'', b.cpla||'', b.cpin||'', b.cstate||'', b.cst_code||'', b.cgstin||'',
     req.params.id]);
  res.json({ success: true });
});
