// ══════════════════════════════════════════════════════════════
// PURCHASES (GSTKBILT.PRG — registered dealer invoices)
// ══════════════════════════════════════════════════════════════
app.get('/api/purchases', requireView, (req, res) => {
  const { auction_id, ano, from, to, sale, search } = req.query;
  const db = getDb();
  let where = 'WHERE 1=1'; const p = [];
  if (auction_id) { where += ' AND auction_id = ?'; p.push(parseInt(auction_id)); }
  if (ano) { where += ' AND ano = ?'; p.push(ano); }
  if (from && to) { where += ' AND date BETWEEN ? AND ?'; p.push(from, to); }
  // Keyword search across the most-useful purchase columns.
  const qstr = String(search || '').trim();
  if (qstr) {
    const like = `%${qstr}%`;
    const ors = ['CAST(invo AS TEXT) LIKE ?', 'name LIKE ?', 'gstin LIKE ?', 'place LIKE ?', 'CAST(ano AS TEXT) LIKE ?'];
    p.push(like, like, like, like, like);
    // Lot spec ("10-20, 25"). Matches a LOT-WISE row directly on its own
    // purchases.lot_no, and a classic SELLER-WISE row (blank lot_no, one
    // invoice covering every lot that dealer sold) through its lots — the
    // same (auction_id, name) link the sale-type filter below uses.
    const lotNums = smartLotNumbers(qstr);
    const ownLot = smartLotSql('purchases.lot_no', lotNums);
    if (ownLot) {
      ors.push(`(TRIM(COALESCE(purchases.lot_no,'')) != '' AND ${ownLot.sql})`);
      p.push(...ownLot.params);
      const viaLots = smartLotSql('l.lot_no', lotNums);
      ors.push(`(TRIM(COALESCE(purchases.lot_no,'')) = '' AND EXISTS (
                   SELECT 1 FROM lots l
                    WHERE l.auction_id = purchases.auction_id
                      AND UPPER(TRIM(COALESCE(l.name,''))) = UPPER(TRIM(COALESCE(purchases.name,'')))
                      AND ${viaLots.sql}))`);
      p.push(...viaLots.params);
    }
    // Phone number → the seller master's number, digits-only.
    const phone = smartPhoneDigits(qstr);
    if (phone) {
      ors.push(`EXISTS (SELECT 1 FROM traders t
                         WHERE UPPER(TRIM(COALESCE(t.name,''))) = UPPER(TRIM(COALESCE(purchases.name,'')))
                           AND (${smartPhoneSql('t.tel')} LIKE ? OR ${smartPhoneSql('t.whatsapp')} LIKE ?))`);
      p.push(`%${phone}%`, `%${phone}%`);
    }
    where += ' AND (' + ors.join(' OR ') + ')';
  }
  // Sale-type filter (L / I / E). Purchases don't carry sale type, but
  // the GST split on each row is deterministic:
  //   • L (Local / intra-state)  → CGST + SGST > 0, IGST = 0
  //   • I (Inter-state)          → IGST > 0, CGST = SGST = 0
  //   • E (Export)               → IGST > 0 too; we disambiguate against
  //                                the dealer's lots (sale='E') when any
  //                                are tagged, else fall back to I.
  // Earlier attempt inferred sale from lots.sale (which is blank for
  // most installs) → L matched everything and I matched nothing.
  const saleNorm = String(sale || '').trim().toUpperCase();
  if (saleNorm === 'L') {
    // Intra-state purchase — CGST+SGST applied, IGST = 0.
    where += ' AND COALESCE(igst,0) = 0 AND (COALESCE(cgst,0) > 0 OR COALESCE(sgst,0) > 0)';
  } else if (saleNorm === 'I') {
    // Inter-state purchase — IGST applied. Excludes Export rows (which
    // also use IGST) when any of the dealer's lots is explicitly E.
    where += ' AND COALESCE(igst,0) > 0';
    where += ` AND NOT EXISTS (
            SELECT 1 FROM lots l
             WHERE l.auction_id = purchases.auction_id
               AND UPPER(TRIM(COALESCE(l.name,''))) = UPPER(TRIM(COALESCE(purchases.name,'')))
               AND UPPER(TRIM(COALESCE(l.sale,''))) = 'E'
          )`;
  } else if (saleNorm === 'E') {
    // Export — IGST applied AND dealer has at least one E-tagged lot.
    where += ' AND COALESCE(igst,0) > 0';
    where += ` AND EXISTS (
            SELECT 1 FROM lots l
             WHERE l.auction_id = purchases.auction_id
               AND UPPER(TRIM(COALESCE(l.name,''))) = UPPER(TRIM(COALESCE(purchases.name,'')))
               AND UPPER(TRIM(COALESCE(l.sale,''))) = 'E'
          )`;
  }
  // Pagination — same contract as invoices/auctions/etc.
  const page     = Math.max(1, parseInt(req.query.page, 10) || 1);
  const pageSize = Math.min(500, Math.max(1, parseInt(req.query.pageSize, 10) || 50));
  const offset   = (page - 1) * pageSize;
  const wantPaged = req.query.page != null || req.query.pageSize != null;
  // Default order: invoice number ascending. `invo` is TEXT holding a numeric
  // string, so it needs the CAST or "10" would sort before "2"; the bare
  // column then breaks ties for any non-numeric value, and date last keeps
  // the order stable when the same number appears under two auctions.
  const baseQuery = 'SELECT * FROM purchases ' + where + ' ORDER BY CAST(invo AS INTEGER), invo, date';
  if (wantPaged) {
    const total = db.get('SELECT COUNT(*) AS c FROM purchases ' + where, p).c;
    const rows = db.all(baseQuery + ' LIMIT ? OFFSET ?', [...p, pageSize, offset]);
    return res.json({ rows, total, page, pageSize });
  }
  res.json(db.all(baseQuery + ' LIMIT 500', p));
});

app.post('/api/purchases/generate/:auctionId',
  requireInvoiceWrite,
  requirePriceChecked(req => parseInt(req.params.auctionId, 10)),
  (req, res) => {
  const db = getDb(); const cfg = getSettingsFlat(db);
  // traderId / userId identify WHICH dealer when the name is shared.
  const { sellerName, invoiceNo, traderId, userId } = req.body;

  // ── Mode resolution (flag_lotwise_purchase) ──────────────────────────
  // A lot identifier in the body means "raise a LOT-WISE invoice for this one
  // lot". Absent means the classic seller-wise invoice. The two are validated
  // against the flag so a stale browser tab can never write a document in the
  // mode the site is not configured for — the operator would have no way to
  // tell from the list which rows came out which way.
  const reqLotNo = String(req.body.lotNo == null ? '' : req.body.lotNo).trim();
  const reqLotId = req.body.lotId;
  const wantsLotWise = reqLotNo !== '' || (reqLotId != null && String(reqLotId).trim() !== '');
  const lotWiseCfg = lotwisePurchaseOn(db);
  if (wantsLotWise && !lotWiseCfg) {
    return res.status(403).json({
      error: 'Lot-wise purchase invoices are disabled. Enable "Lot-wise Purchase Invoices" in Settings → Flags.',
      mode: 'seller',
    });
  }
  if (!wantsLotWise && lotWiseCfg) {
    return res.status(400).json({
      error: 'This site is set to LOT-WISE purchase invoices, but no lot was selected. Reload the page and pick a lot.',
      mode: 'lot',
    });
  }

  // Duplicate guard — lot-wise only. Seller-wise generation keeps its existing
  // behaviour (no guard) so nothing about the current flow changes. Lot-wise
  // needs one because the operator is now working through a list of many lots
  // and re-running is far easier to do by accident.
  if (wantsLotWise) {
    const dupe = db.get(
      `SELECT invo FROM purchases
        WHERE auction_id = ? AND UPPER(TRIM(name)) = UPPER(TRIM(?))
          AND TRIM(COALESCE(lot_no,'')) = ? LIMIT 1`,
      [req.params.auctionId, String(sellerName || ''), reqLotNo]
    );
    if (dupe) {
      return res.status(409).json({
        error: `Lot ${reqLotNo} already has purchase invoice #${dupe.invo} for ${sellerName} in this trade.`,
        existingInvoiceNo: dupe.invo,
      });
    }
  }

  const invoice = buildPurchaseInvoice(db, req.params.auctionId, sellerName, cfg, {
    traderId, userId,
    lotNo: reqLotNo, lotId: reqLotId, docNo: invoiceNo,
  });
  if (!invoice) {
    return res.status(404).json({
      error: wantsLotWise
        ? `No eligible data for lot ${reqLotNo} under ${sellerName}.`
        : 'No data for this seller',
    });
  }

  const auction = db.get('SELECT * FROM auctions WHERE id = ?', [req.params.auctionId]);
  const s = invoice.summary;
  db.run(`INSERT INTO purchases (auction_id,ano,date,state,br,name,add_line,place,gstin,invo,qty,amount,cgst,sgst,igst,rund,total,tds,trader_id,lot_no,lot_id)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
    [req.params.auctionId,auction.ano,auction.date,auction.state||'','',invoice.seller.name,invoice.seller.address||'',
     invoice.seller.place||'',invoice.seller.cr||'',String(invoiceNo),s.totalQty,s.totalPuramt,
     s.totalCgst,s.totalSgst,s.totalIgst,s.roundDiff,s.grandTotal,s.tdsAmount,
     invoice.seller.trader_id || null,
     // Empty lot_no is what marks this row seller-wise, for every future reader.
     invoice.lotNo || '', invoice.lotId]);
  res.json({ success: true, invoice: s, mode: wantsLotWise ? 'lot' : 'seller', lotNo: invoice.lotNo || '' });
});

// List eligible sellers for purchase invoices (with GSTIN, amount > 0)
app.get('/api/purchases/eligible-sellers/:auctionId', requireView, (req, res) => {
  // A lot is eligible for a Purchase Invoice when it has a GSTIN-bearing
  // seller. The `cr` column stores GSTINs in two known formats:
  //   1. "GSTIN.<15-char>" — legacy UI format
  //   2. "<15-char>"        — bare format from Excel imports / API
  // Earlier this endpoint only matched format #1 (UPPER(cr) LIKE 'GSTIN%')
  // and silently excluded every seller whose `cr` was the bare form,
  // producing the reported "No eligible dealer(s) found" empty state on
  // installs where dealers were imported via XLSX rather than typed in
  // through the UI.
  //
  // Fix: accept either form. The bare-GSTIN check uses GLOB '[0-9][0-9]*'
  // (cr starts with two digits — matches the state-code prefix of every
  // valid GSTIN) plus a length >= 15 guard. Both forms fall through the
  // same downstream `gstinStateCode` helper so intra/inter logic is
  // unaffected.
  // Grouped by the seller's identity, not the name: two dealers can be
  // registered under one name with different GSTINs, and grouping on the name
  // put both on a single purchase invoice under one GSTIN. trader_id is the
  // real key, user_id covers pre-FK lots, name is the last resort. The id
  // travels back so Generate can bill exactly this dealer.
  res.json(getDb().all(
    `SELECT name, MAX(trader_id) AS trader_id,
            CASE WHEN UPPER(TRIM(COALESCE(MAX(user_id),''))) IN ('','IMPORT')
                 THEN '' ELSE TRIM(MAX(user_id)) END AS user_id,
            COUNT(*) as lot_count, SUM(qty) as total_qty, SUM(amount) as total_amount, MAX(cr) as cr
     FROM lots
     WHERE auction_id = ? AND name IS NOT NULL AND name != ''
       AND amount > 0
       AND ${hasValidGstinSql('cr')}
     GROUP BY COALESCE(trader_id, -1), UPPER(TRIM(name))
     -- Case-insensitive alphabetical. A plain ORDER BY name uses SQLite's
     -- binary collation, which files every lowercase name after every
     -- uppercase one. Must match generate-all below so the list on screen
     -- reads in the same order the invoice numbers get handed out.
     ORDER BY UPPER(TRIM(name))`,
    [req.params.auctionId]
  ));
});

// ── LOT-WISE eligible list (flag_lotwise_purchase) ───────────────────────
// The lot-wise counterpart of /eligible-sellers: one row per LOT rather than
// one row per dealer. Same eligibility rule (GSTIN-bearing seller, amount > 0,
// not reserved) so the two lists always cover exactly the same lots — only
// the grouping differs. The client shows this list when the flag is on.
//
// `already_invoiced` is advisory, for the UI: it flags lots that already have
// a lot-wise purchase row in this trade so the operator can see at a glance
// what a re-run would duplicate. Generation enforces this properly.
//
// ORDER BY is the numbering scheme in lot-wise mode exactly as it is in
// seller-wise mode: invoice numbers are handed out in this order. Sorted by
// seller first, then lot, so one dealer's lots take consecutive numbers
// instead of being scattered through the trade's series.
app.get('/api/purchases/eligible-lots/:auctionId', requireView, (req, res) => {
  const db = getDb();
  const aid = req.params.auctionId;
  res.json(db.all(
    `SELECT l.id AS lot_id, l.lot_no, l.name, l.trader_id,
            CASE WHEN UPPER(TRIM(COALESCE(l.user_id,''))) IN ('','IMPORT')
                 THEN '' ELSE TRIM(l.user_id) END AS user_id,
            l.grade, l.bags, l.qty, l.price, l.amount, l.cr,
            (SELECT p.invo FROM purchases p
              WHERE p.auction_id = l.auction_id
                AND TRIM(COALESCE(p.lot_no,'')) = TRIM(l.lot_no)
                AND UPPER(TRIM(p.name)) = UPPER(TRIM(l.name))
              LIMIT 1) AS already_invoiced
       FROM lots l
      WHERE l.auction_id = ? AND l.name IS NOT NULL AND l.name != ''
        AND l.amount > 0
        AND (l.reserved IS NULL OR l.reserved = 0)
        -- Withdrawn / N-A lots are not purchaseable. The generation GATE
        -- already excludes them, so this list must too — otherwise the
        -- gate reports "done" while the picker still offers the lot.
        AND UPPER(TRIM(COALESCE(l.code,''))) NOT IN ('WD','NA')
        AND ${hasValidGstinSql('l.cr')}
      ORDER BY UPPER(TRIM(l.name)), CAST(l.lot_no AS INTEGER), l.lot_no`,
    [aid]
  ));
});

// Batch: generate purchase invoice for ALL registered dealers in an auction
app.post('/api/purchases/generate-all/:auctionId',
  requireInvoiceWrite,
  requirePriceChecked(req => parseInt(req.params.auctionId, 10)),
  (req, res) => {
  const db = getDb(); const cfg = getSettingsFlat(db);
  const { startInvoiceNo } = req.body;
  
  let nextNo = parseInt(startInvoiceNo);
  if (!nextNo || nextNo < 1) return res.status(400).json({ error: 'startInvoiceNo must be a positive integer' });
  
  // Auto-calculate
  const uncalc = db.all(`SELECT * FROM lots WHERE auction_id = ? AND amount > 0 AND (puramt IS NULL OR puramt = 0)`, [req.params.auctionId]);
  for (const lot of uncalc) {
    const c = calculateLot(lot, cfg);
    db.run(`UPDATE lots SET pqty=?,prate=?,puramt=?,com=?,sertax=?,cgst=?,sgst=?,igst=?,advance=?,balance=?,bilamt=?,refund=?,refud=?,isp_pqty=?,isp_prate=?,isp_puramt=?,asp_pqty=?,asp_prate=?,asp_puramt=? WHERE id=?`,
      [c.pqty,c.prate,c.puramt,c.com,c.sertax,c.cgst,c.sgst,c.igst,c.advance,c.balance,c.bilamt,c.refund||0,c.refud||0,c.isp_pqty||0,c.isp_prate||0,c.isp_puramt||0,c.asp_pqty||0,c.asp_prate||0,c.asp_puramt||0,lot.id]);
  }
  
  // Same dual-format GSTIN filter as the eligible-sellers endpoint —
  // ensures bare-GSTIN imports aren't silently skipped during batch
  // generation.
  // Invoice numbers are handed out in this loop's order, so the sort IS the
  // numbering scheme: dealers are invoiced alphabetically. Previously there
  // was no ORDER BY at all, leaving it to whatever order SQLite happened to
  // return rows in. UPPER(TRIM(..)) for the same case-insensitivity reason as
  // the eligible-sellers endpoint above, whose order this mirrors.
  // ── Mode resolution (flag_lotwise_purchase) ──────────────────────────
  // Seller-wise (flag off) walks one row per dealer, exactly as before.
  // Lot-wise (flag on) walks one row per LOT. Both use the same eligibility
  // rule and the same ORDER BY, so the two modes cover identical lots and
  // differ only in how many documents that becomes.
  const lotWise = lotwisePurchaseOn(db);

  const sellers = lotWise
    ? db.all(
        `SELECT l.id AS lot_id, l.lot_no, l.name, l.trader_id,
                CASE WHEN UPPER(TRIM(COALESCE(l.user_id,''))) IN ('','IMPORT')
                     THEN '' ELSE TRIM(l.user_id) END AS user_id
           FROM lots l
          WHERE l.auction_id = ?
            AND l.amount > 0
            AND l.name IS NOT NULL AND l.name != ''
            AND (l.reserved IS NULL OR l.reserved = 0)
            -- Same WD/NA exclusion as /eligible-lots and the gate, so the
            -- preview count, the batch run and the gate all agree.
            AND UPPER(TRIM(COALESCE(l.code,''))) NOT IN ('WD','NA')
            AND ${hasValidGstinSql('l.cr')}
          ORDER BY UPPER(TRIM(l.name)), CAST(l.lot_no AS INTEGER), l.lot_no`,
        [req.params.auctionId]
      )
    : db.all(
        `SELECT DISTINCT name FROM lots
         WHERE auction_id = ?
           AND amount > 0
           AND name IS NOT NULL AND name != ''
           AND ${hasValidGstinSql('cr')}
         ORDER BY UPPER(TRIM(name))`,
        [req.params.auctionId]
      );

  if (!sellers.length) return res.status(404).json({
    error: lotWise
      ? 'No eligible lots (GSTIN-bearing seller) in this auction'
      : 'No registered dealers (with GSTIN) in this auction'
  });

  const auction = db.get('SELECT * FROM auctions WHERE id = ?', [req.params.auctionId]);
  const results = [];
  const errors = [];
  const skipped = [];

  // Lots already carrying a lot-wise purchase invoice in this trade, so a
  // re-run tops up the missing ones instead of double-invoicing the lot.
  // Seller-wise runs skip this entirely and behave exactly as before.
  const alreadyDone = new Set();
  if (lotWise) {
    for (const r of db.all(
      `SELECT name, lot_no, invo FROM purchases
        WHERE auction_id = ? AND TRIM(COALESCE(lot_no,'')) <> ''`,
      [req.params.auctionId]
    )) alreadyDone.add(`${String(r.name || '').trim().toUpperCase()}|${String(r.lot_no || '').trim()}`);
  }

  for (const row of sellers) {
    const label = lotWise ? `${row.name} — lot ${row.lot_no}` : row.name;
    try {
      if (lotWise) {
        const key = `${String(row.name || '').trim().toUpperCase()}|${String(row.lot_no || '').trim()}`;
        if (alreadyDone.has(key)) {
          skipped.push({ seller: row.name, lotNo: row.lot_no, reason: 'Already invoiced' });
          continue;
        }
      }
      const invoNo = String(nextNo);
      const invoice = buildPurchaseInvoice(db, req.params.auctionId, row.name, cfg,
        { traderId: row.trader_id, userId: row.user_id,
          lotNo: lotWise ? row.lot_no : '', lotId: lotWise ? row.lot_id : null,
          docNo: invoNo });
      if (!invoice) { errors.push({ seller: label, error: 'Build failed' }); continue; }
      const s = invoice.summary;
      db.run(`INSERT INTO purchases (auction_id,ano,date,state,br,name,add_line,place,gstin,invo,qty,amount,cgst,sgst,igst,rund,total,tds,trader_id,lot_no,lot_id)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [req.params.auctionId,auction.ano,auction.date,auction.state||'','',invoice.seller.name,invoice.seller.address||'',
         invoice.seller.place||'',invoice.seller.cr||'',invoNo,s.totalQty,s.totalPuramt,
         s.totalCgst,s.totalSgst,s.totalIgst,s.roundDiff,s.grandTotal,s.tdsAmount,
     invoice.seller.trader_id || null,
     invoice.lotNo || '', invoice.lotId]);
      results.push({ seller: row.name, lotNo: lotWise ? row.lot_no : '', invoiceNo: invoNo, grandTotal: s.grandTotal });
      nextNo++;
    } catch (e) { errors.push({ seller: label, error: e.message }); }
  }

  res.json({ success: true, mode: lotWise ? 'lot' : 'seller',
             generated: results.length, results, errors, skipped });
});

// Update purchase (edit)
app.put('/api/purchases/:id', requireInvoiceWrite, (req, res) => {
  const p = req.body;
  const db = getDb();
  // Cascade lock — see invoice PUT for rationale.
  if (!isAdmin(req) && lotsLockedForPurchase(db, req.params.id)) {
    return res.status(423).json({ error: 'This purchase is locked because at least one of its lots is locked — only an admin can edit it.' });
  }
  const fields = ['ano','date','state','br','name','add_line','place','gstin','invo',
    'qty','amount','cgst','sgst','igst','rund','total','tds'];
  const sets = []; const vals = [];
  for (const f of fields) {
    if (p[f] !== undefined) { sets.push(`${f}=?`); vals.push(p[f]); }
  }
  if (!sets.length) return res.status(400).json({ error: 'No fields to update' });
  vals.push(req.params.id);
  db.run(`UPDATE purchases SET ${sets.join(',')} WHERE id=?`, vals);
  res.json({ success: true });
});

// Delete purchase
app.delete('/api/purchases/:id', requireDelete, (req, res) => {
  const db = getDb();
  if (!isAdmin(req) && lotsLockedForPurchase(db, req.params.id)) {
    return res.status(423).json({ error: 'This purchase is locked because at least one of its lots is locked — only an admin can delete it.' });
  }
  db.run('DELETE FROM purchases WHERE id=?', [req.params.id]);
  res.json({ success: true });
});

// ── Purchase Invoice PDF ─────────────────────────────────────
app.get('/api/purchases/pdf/:auctionId/:sellerName', requireView, async (req, res) => {
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const sellerName = decodeURIComponent(req.params.sellerName);
    const auctionId = req.params.auctionId;
    const invoiceNo = req.query.invoiceNo || '001';
    
    // Find the stored invoice FIRST — its trader_id says which of two
    // same-named dealers this document belongs to, and the live rebuild below
    // needs that to pull the right dealer's lots. (Try auction_id, then fall
    // back to name+invo for older records that predate the column.)
    let stored = db.get(
      `SELECT * FROM purchases WHERE auction_id = ? AND name = ? AND invo = ? LIMIT 1`,
      [auctionId, sellerName, String(invoiceNo)]
    ) || db.get(
      `SELECT * FROM purchases WHERE name = ? AND invo = ? LIMIT 1`,
      [sellerName, String(invoiceNo)]
    );

    // Try to build fresh invoice from lots. Scoped by purchaseRebuildOpts so a
    // lot-wise document rebuilds to its ONE lot rather than to every lot the
    // seller sold in the trade.
    let invoice = buildPurchaseInvoice(db, auctionId, sellerName, cfg,
      purchaseRebuildOpts(stored));

    // Fallback: if lots data missing, rebuild from stored purchase record
    if (!invoice) {
      if (!stored) {
        return res.status(404).json({ 
          error: `No purchase data found for seller "${sellerName}" with invoice ${invoiceNo}. Lots may have been deleted.` 
        });
      }
      // Reconstruct minimal invoice object from stored data. Imported
      // rows often arrive WITHOUT cgst/sgst/igst (the source XLSX rarely
      // breaks GST out as separate columns), so we recompute the tax
      // when stored GST is all-zero but a taxable amount is present.
      // The seller's GSTIN state-code vs cfg.business_state decides the
      // intra/inter split — same rule buildPurchaseInvoice applies.
      let scgst = Number(stored.cgst) || 0;
      let ssgst = Number(stored.sgst) || 0;
      let sigst = Number(stored.igst) || 0;
      const amtBase = Number(stored.amount) || 0;
      if (amtBase > 0 && scgst + ssgst + sigst === 0) {
        const gstGoods = Number(cfg.gst_goods) || 5;
        const companyState = String(cfg.business_state || '').toUpperCase() === 'KERALA' ? '32' : '33';
        const sellerState = (() => {
          let s = String(stored.gstin || '').trim().toUpperCase();
          if (s.startsWith('GSTIN.')) s = s.substring(6);
          else if (s.startsWith('GSTIN')) s = s.substring(5);
          return /^\d{2}/.test(s) ? s.substring(0, 2) : '';
        })();
        const isInter = sellerState && sellerState !== companyState;
        if (isInter) {
          sigst = Math.round(amtBase * gstGoods / 100 * 100) / 100;
        } else {
          scgst = Math.round(amtBase * (gstGoods / 2) / 100 * 100) / 100;
          ssgst = Math.round(amtBase * (gstGoods / 2) / 100 * 100) / 100;
        }
      }
      invoice = {
        seller: { name: stored.name, address: stored.add_line, place: stored.place, cr: stored.gstin, pan: '', state: stored.state },
        lineItems: [{ lot: '—', qty: stored.qty, pqty: stored.qty, price: 0, prate: 0, amount: amtBase, puramt: amtBase, com: 0, sertax: 0, cgst: scgst, sgst: ssgst, igst: sigst }],
        summary: {
          totalQty: stored.qty, totalPuramt: amtBase,
          totalCgst: scgst, totalSgst: ssgst, totalIgst: sigst,
          // If `total` is also blank in the import, recompute from base + GST.
          roundDiff: Number(stored.rund) || 0,
          grandTotal: (Number(stored.total) || (amtBase + scgst + ssgst + sigst)),
          tdsAmount: Number(stored.tds) || 0,
          invoiceAmount: ((Number(stored.total) || (amtBase + scgst + ssgst + sigst)) - (Number(stored.tds) || 0)),
          isInter: sigst > 0
        }
      };
    }
    
    const enriched = enrichPurchaseForPDF(invoice, cfg, db, auctionId);
    let pdf;
    const tplChoice = String(req.query.template || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'purchase_invoice_engine', templateKey: 'purchase_invoice_template', tplChoice });
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, purchase_invoice_template: tplChoice } : cfg;
      pdf = await require('./pdf/render-purchase-html').generatePurchaseInvoiceHtmlPDF(enriched, cfg2, invoiceNo);
    } else {
      pdf = await generatePurchaseInvoicePDF(enriched, cfg, invoiceNo);
    }
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="PurchaseInvoice_${sellerName.replace(/[^\w]/g, '_')}_${invoiceNo}.pdf"`);
    res.send(pdf);
  } catch (e) {
    console.error('PDF generation error:', e);
    res.status(500).json({ error: 'PDF generation failed: ' + e.message });
  }
});

// Attach buyer block + e-AUCTION No + invoice date to a purchase invoice
// object so the new renderer can show the full BILLED/SHIPPED TO + top
// grid correctly. The buyer is whichever identity is currently active in
// the app (ASP when Kerala+e-Auction, else ISP from company_settings).
function enrichPurchaseForPDF(invoice, cfg, db, auctionId) {
  if (!invoice) return invoice;
  // Stamp auction date + e-AUCTION no. Uses the operator's `date_format`
  // setting so the invoice's date string matches what they see on the
  // Sales list and every other document in the app.
  const dateFmt = (cfg && cfg.date_format) || 'dd/mm/yyyy';
  if (!invoice.invoiceDate && auctionId) {
    const auction = db.get('SELECT date FROM auctions WHERE id = ?', [auctionId]);
    if (auction && auction.date) {
      invoice.invoiceDate = formatDateForDisplay(auction.date, dateFmt);
    }
  }
  if (!invoice.invoiceDate) invoice.invoiceDate = formatDateForDisplay(new Date(), dateFmt);
  if (!invoice.eTradeNo) invoice.eTradeNo = String(auctionId || '');

  // Buyer block — populated from the central company identity (which
  // reads the user's CURRENT settings). Legacy `s_*` / `tn_*` fields are
  // only used as a fallback when identity is blank, NOT as the primary
  // source. Inverting the priority is critical: stale `s_company` left
  // over from the dual-company migration was overriding the user's
  // configured company name and producing "ASP address" on PDFs even
  // after the user updated Settings.
  //
  // The isASP branch is structurally retained so the BILLED/SHIPPED TO
  // address can still pick state-specific address lines (Kerala vs Tamil
  // Nadu) when both are populated.
  const isASP = cfg.business_mode === 'e-Trade' && String(cfg.business_state || '').toUpperCase() === 'KERALA';
  if (!invoice.buyer) {
    const _ident = getCompanyIdentity(cfg);
    invoice.buyer = isASP ? {
      name:    _ident.name    || cfg.s_company  || '',
      address: _ident.address1 || cfg.s_address1 || cfg.kl_address1 || '',
      place:   cfg.s_place || cfg.kl_place || '',
      pin:     cfg.s_pin   || cfg.kl_pin   || '',
      state:   _ident.state    || cfg.s_state || 'Kerala',
      st_code: _ident.stateCode || cfg.s_st_code || '32',
      gstin:   _ident.gstin    || cfg.s_gstin || '',
      pan:     _ident.pan      || cfg.s_pan || cfg.pan || '',
    } : {
      name:    _ident.name    || cfg.short_name || cfg.trade_name || '',
      address: _ident.address1 || cfg.tn_address1 || '',
      place:   cfg.tn_place || '',
      pin:     cfg.tn_pin   || '',
      state:   _ident.state    || cfg.tn_state || 'Tamil Nadu',
      st_code: _ident.stateCode || cfg.tn_st_code || '33',
      gstin:   _ident.gstin    || cfg.tn_gstin || '',
      pan:     _ident.pan      || cfg.pan || '',
    };
  }
  return invoice;
}

// Bulk Purchase Invoice PDF — merges N purchases into a single PDF
// Body: { ids: [1, 2, 3, ...] } — database row IDs from `purchases` table.
// Returns: one PDF with each purchase on its own page(s), in the order given.
// Same rebuild-from-lots OR fallback-to-stored pattern as the single route.
app.post('/api/purchases/pdf-bulk', requireView, async (req, res) => {
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const ids = Array.isArray(req.body?.ids) ? req.body.ids.filter(Boolean) : [];
    if (!ids.length) return res.status(400).json({ error: 'No purchase IDs provided' });

    const placeholders = ids.map(() => '?').join(',');
    const rows = db.all(`SELECT * FROM purchases WHERE id IN (${placeholders})`, ids);
    if (!rows.length) return res.status(404).json({ error: 'No matching purchases found' });

    // Preserve the order the user ticked them in by looking up each ID in
    // the returned set (the IN query doesn't preserve order).
    const byId = new Map(rows.map(r => [r.id, r]));
    const ordered = ids.map(id => byId.get(Number(id))).filter(Boolean);

    const payloads = [];
    for (const stored of ordered) {
      // Try fresh rebuild from lots first (richer line-item detail)
      // Rebuild for the seller the document was RAISED for, not merely for
      // its name — purchases.trader_id records which of two same-named
      // dealers this invoice belongs to.
      let invoice = stored.auction_id
        ? buildPurchaseInvoice(db, stored.auction_id, stored.name, cfg, purchaseRebuildOpts(stored))
        : null;
      if (!invoice) {
        // Fallback: stored summary only (one line item)
        invoice = {
          seller: {
            name: stored.name, address: stored.add_line, place: stored.place,
            cr: stored.gstin, pan: '', state: stored.state
          },
          lineItems: [{
            lot: '—', qty: stored.qty, pqty: stored.qty, price: 0, prate: 0,
            amount: stored.amount, puramt: stored.amount,
            com: 0, sertax: 0, cgst: stored.cgst, sgst: stored.sgst, igst: stored.igst
          }],
          summary: {
            totalQty: stored.qty, totalPuramt: stored.amount,
            totalCgst: stored.cgst, totalSgst: stored.sgst, totalIgst: stored.igst,
            roundDiff: stored.rund, grandTotal: stored.total,
            tdsAmount: stored.tds, invoiceAmount: stored.total - stored.tds,
            isInter: stored.igst > 0
          }
        };
      }
      payloads.push({ invoiceData: enrichPurchaseForPDF(invoice, cfg, db, stored.auction_id), invoiceNo: stored.invo });
    }

    let pdf;
    const tplChoice = String((req.body && req.body.template) || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'purchase_invoice_engine', templateKey: 'purchase_invoice_template', tplChoice });
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, purchase_invoice_template: tplChoice } : cfg;
      pdf = await require('./pdf/render-purchase-html').generatePurchaseInvoicesHtmlBatchPDF(payloads, cfg2);
    } else {
      pdf = await generatePurchaseInvoicesBatchPDF(payloads, cfg);
    }
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="PurchaseInvoices_Batch_${payloads.length}.pdf"`);
    res.send(pdf);
  } catch (e) {
    console.error('Bulk purchase PDF error:', e);
    res.status(500).json({ error: 'Bulk PDF generation failed: ' + e.message });
  }
});

// ── PAYMENT VOUCHER (Commission Memorandum) for purchase invoices ────────
// "PAYMENT VOUCHER — MEMORANDUM OF CARDAMOM SOLD THROUGH <company>": the
// dealer-side twin of /api/bills/commission-bos-bulk. One A4 page PER LOT,
// each showing that lot's cardamom cost, sample refund, trader sample,
// commission and GST-on-commission, and the net payable to the dealer.
//
// This is what makes SELLER-WISE purchases printable lot-wise. A seller-wise
// purchase invoice (the default — flag_lotwise_purchase off) covers every lot
// the dealer sold in the trade on ONE document; ticking it here prints one
// voucher page per lot without generating, numbering or storing anything new.
// A lot-wise purchase row (lot_no stamped) already covers a single lot, so it
// simply prints that one page.
//
// Numbering: the stored invoice number leads every page, with a per-page
// suffix (123/1, 123/2 …) when the invoice spans more than one lot — the same
// convention the multi-lot commission bill uses. A single-lot invoice keeps
// the plain number.
//
// Body: { ids: [purchase row ids], template?, invoiceNo? }
app.post('/api/purchases/commission-bulk', requireView, async (req, res) => {
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const ids = Array.isArray(req.body?.ids) ? req.body.ids.filter(Boolean) : [];
    if (!ids.length) return res.status(400).json({ error: 'No purchase IDs provided' });

    const invoOpts = commissionInvoiceNoOpts(db, cfg, req);

    const placeholders = ids.map(() => '?').join(',');
    const stored = db.all(`SELECT * FROM purchases WHERE id IN (${placeholders})`, ids);
    if (!stored.length) return res.status(404).json({ error: 'No matching purchase invoices found' });
    const byId = new Map(stored.map(r => [r.id, r]));
    const ordered = ids.map(id => byId.get(Number(id))).filter(Boolean);

    const dateFmt = (cfg && cfg.date_format) || 'dd/mm/yyyy';
    const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
    const payloads = [];

    for (const p of ordered) {
      // Lot scope mirrors buildPurchaseInvoice: the dealer's lots in this
      // trade, narrowed to the ONE lot when the row was raised lot-wise.
      const lotNo = String(p.lot_no == null ? '' : p.lot_no).trim();
      const lotsForAuction = (aid) => {
        const where = [
          'auction_id = ?',
          'UPPER(TRIM(name)) = UPPER(TRIM(?))',
          '(amount > 0 OR puramt > 0)',
          '(reserved IS NULL OR reserved = 0)',
          hasValidGstinSql('cr'),
        ];
        const args = [aid, p.name];
        // trader_id says WHICH dealer when two are registered under one name.
        if (p.trader_id != null) { where.push('trader_id = ?'); args.push(p.trader_id); }
        if (lotNo) {
          // lot_id is exact; lot_no survives a delete + re-import of the trade.
          where.push(`(${p.lot_id != null ? 'id = ? OR ' : ''}TRIM(CAST(lot_no AS TEXT)) = TRIM(CAST(? AS TEXT)))`);
          if (p.lot_id != null) args.push(p.lot_id);
          args.push(lotNo);
        }
        return db.all(
          `SELECT * FROM lots WHERE ${where.join(' AND ')}
            ORDER BY CAST(lot_no AS INTEGER), lot_no`, args);
      };
      // A stored auction_id goes stale when the trade is deleted and
      // re-imported under a new id, so fall back to every auction carrying
      // this trade number and keep the first that actually has lots.
      const auctionCands = [];
      if (p.auction_id) {
        const a = db.get('SELECT id, ano, date FROM auctions WHERE id = ?', [p.auction_id]);
        if (a) auctionCands.push(a);
      }
      if (p.ano != null && String(p.ano).trim() !== '') {
        for (const a of db.all(
          'SELECT id, ano, date FROM auctions WHERE CAST(ano AS TEXT) = CAST(? AS TEXT) ORDER BY id',
          [String(p.ano)]
        )) if (!auctionCands.some(c => c.id === a.id)) auctionCands.push(a);
      }
      let auction = auctionCands[0] || null;
      let lots = [];
      for (const a of auctionCands) {
        const ls = lotsForAuction(a.id);
        if (ls.length) { auction = a; lots = ls; break; }
      }

      const first = lots[0] || {};
      // The dealer's registration prints as GSTIN (the planter memorandum
      // prints AADHAR / CR instead) — strip any stored "GSTIN."/"CR." label so
      // the template doesn't double it.
      const gstinRaw = String(p.gstin || first.cr || '').trim();
      const gstin = gstinRaw.replace(/^\s*(GSTIN|CR)[.\s]+/i, '');
      const seller = {
        name:    p.name || first.name || '',
        address: p.add_line || first.padd || '',
        place:   p.place    || first.ppla || '',
        pin:     first.ppin || '',
        state:   p.state    || first.pstate || '',
        st_code: first.pst_code || gstin.slice(0, 2),
        // `cr` stays blank for a dealer: the GSTIN line carries the id.
        cr:      '',
        gstin,
        pan:     first.pan || '',
        aadhar:  '',
      };
      // Phone + bank account (shown when flag_commission_bank is on) — trader
      // master first, then the denormalised lot value; account prefers the
      // trader's default bank over the legacy single-account column.
      try {
        let t = null;
        if (p.trader_id) t = db.get('SELECT id, tel, acctnum, pan FROM traders WHERE id = ? LIMIT 1', [p.trader_id]);
        if (!t && first.trader_id) t = db.get('SELECT id, tel, acctnum, pan FROM traders WHERE id = ? LIMIT 1', [first.trader_id]);
        if (!t) t = db.get('SELECT id, tel, acctnum, pan FROM traders WHERE UPPER(TRIM(name)) = UPPER(TRIM(?)) LIMIT 1', [seller.name]);
        seller.phone = (t && t.tel) || first.tel || '';
        if (!seller.pan && t && t.pan) seller.pan = t.pan;
        let acct = (t && t.acctnum) || '';
        if (t && t.id) {
          const tb = db.get('SELECT acctnum FROM trader_banks WHERE trader_id = ? ORDER BY is_default DESC, id LIMIT 1', [t.id]);
          if (tb && tb.acctnum) acct = tb.acctnum;
        }
        seller.account = acct;
      } catch (_) { seller.phone = first.tel || ''; seller.account = ''; }

      const perLot = commissionPagesFromLots(db, cfg, lots, invoOpts);
      // No live lots (deleted after generation, or an imported row with no
      // lot lineage). Purchases carry no per-lot snapshot, so emit ONE
      // consolidated page from the stored totals rather than nothing —
      // commission/GST are unknown there and print as zero.
      if (!perLot.length) {
        perLot.push({
          line: { lot: '—', qty: p.qty, bags: 0, rate: 0, cardamomCost: p.amount,
                  refundQty: 0, refundRate: 0, refundAmount: 0 },
          purchaser: { ...EMPTY_COMMISSION_PURCHASER },
          commission: 0, cgst: 0, sgst: 0, igst: 0, interState: false,
          nett: round2(p.amount),
          crpt: '',
        });
      }

      let docDate = '';
      if (auction && auction.date) docDate = formatDateForDisplay(auction.date, dateFmt);
      if (!docDate && p.date) docDate = formatDateForDisplay(p.date, dateFmt);

      const invoNo = String(p.invo == null ? '' : p.invo).trim();
      perLot.forEach((pl, i) => {
        payloads.push({
          billNo: perLot.length > 1 ? `${invoNo}/${i + 1}` : invoNo,
          billData: {
            crpt: pl.crpt || first.crpt || '',
            auction: { ano: auction ? auction.ano : (p.ano || ''), date: docDate },
            seller,
            purchaser: pl.purchaser,
            lineItems: [pl.line],
            commission: pl.commission,
            cgst: pl.cgst, sgst: pl.sgst, igst: pl.igst,
            interState: pl.interState,
            gstRate: Number(cfg.commission_gst_rate) || 9.0,
            nett: pl.nett,
          },
        });
      });
    }

    // Same renderer as the Bill-of-Supply memorandum — the page is identical
    // for both seller kinds, so the operator's commission-bill layout choice
    // (saved default or per-print override) applies here too.
    const tplChoice = String((req.body && req.body.template) || (req.query && req.query.template) || '').trim();
    let pdf;
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'commission_bill_engine', templateKey: 'commission_bill_template', tplChoice });
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, commission_bill_template: tplChoice } : cfg;
      pdf = await require('./pdf/render-commission-html').generateCommissionBoSHtmlPDF(payloads, cfg2);
    } else {
      pdf = await generateCommissionBoSBatchPDF(payloads, cfg);
    }
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="PaymentVouchers_${payloads.length}.pdf"`);
    res.send(pdf);
  } catch (e) {
    console.error('Purchase payment voucher PDF error:', e);
    res.status(500).json({ error: 'Payment voucher PDF generation failed: ' + e.message });
  }
});

// ══════════════════════════════════════════════════════════════
// BILLS — Agriculturist Bills of Supply (GSTKBILP/GSTBILP)
// ══════════════════════════════════════════════════════════════
app.get('/api/bills', requireView, (req, res) => {
  const { auction_id, ano, from, to, branch, search } = req.query;
  const db = getDb();
  let where = 'WHERE 1=1'; const p = [];
  if (auction_id) { where += ' AND auction_id = ?'; p.push(parseInt(auction_id)); }
  if (ano) { where += ' AND ano = ?'; p.push(ano); }
  if (from && to) { where += ' AND date BETWEEN ? AND ?'; p.push(from, to); }
  // Branch filter — bills.br column may not be set for legacy rows, so
  // we also infer via the underlying lot's branch. lots has no `ano`
  // column; we join through bills.auction_id (or look up the auction id
  // from bills.ano) and match on seller name. Falls back to bills.br
  // when auction_id isn't populated either.
  const branchFilter = String(branch || '').trim();
  if (branchFilter) {
    where += ` AND (
            UPPER(TRIM(COALESCE(br,''))) = UPPER(TRIM(?))
            OR EXISTS (
              SELECT 1 FROM lots l
               WHERE l.auction_id = COALESCE(
                       bills.auction_id,
                       (SELECT a.id FROM auctions a WHERE a.ano = bills.ano LIMIT 1)
                     )
                 AND UPPER(TRIM(COALESCE(l.name,''))) = UPPER(TRIM(COALESCE(bills.name,'')))
                 AND UPPER(TRIM(COALESCE(l.branch,''))) = UPPER(TRIM(?))
            )
          )`;
    p.push(branchFilter, branchFilter);
  }
  const qstr = String(search || '').trim();
  if (qstr) {
    const like = `%${qstr}%`;
    const ors = ['CAST(bil AS TEXT) LIKE ?', 'name LIKE ?', 'pla LIKE ?', 'CAST(ano AS TEXT) LIKE ?', 'br LIKE ?'];
    p.push(like, like, like, like, like);
    // Lot spec ("10-20, 25") — a LOT-WISE bill carries its own bills.lot_no;
    // a classic SELLER-WISE bill resolves through the planter's lots on the
    // same trade (identical join to the branch filter above).
    const lotNums = smartLotNumbers(qstr);
    const ownLot = smartLotSql('bills.lot_no', lotNums);
    if (ownLot) {
      ors.push(`(TRIM(COALESCE(bills.lot_no,'')) != '' AND ${ownLot.sql})`);
      p.push(...ownLot.params);
      const viaLots = smartLotSql('l.lot_no', lotNums);
      ors.push(`(TRIM(COALESCE(bills.lot_no,'')) = '' AND EXISTS (
                   SELECT 1 FROM lots l
                    WHERE l.auction_id = COALESCE(
                            bills.auction_id,
                            (SELECT a.id FROM auctions a WHERE a.ano = bills.ano LIMIT 1))
                      AND UPPER(TRIM(COALESCE(l.name,''))) = UPPER(TRIM(COALESCE(bills.name,'')))
                      AND ${viaLots.sql}))`);
      p.push(...viaLots.params);
    }
    // Phone number → the planter's number on the seller master.
    const phone = smartPhoneDigits(qstr);
    if (phone) {
      ors.push(`EXISTS (SELECT 1 FROM traders t
                         WHERE UPPER(TRIM(COALESCE(t.name,''))) = UPPER(TRIM(COALESCE(bills.name,'')))
                           AND (${smartPhoneSql('t.tel')} LIKE ? OR ${smartPhoneSql('t.whatsapp')} LIKE ?))`);
      p.push(`%${phone}%`, `%${phone}%`);
    }
    where += ' AND (' + ors.join(' OR ') + ')';
  }
  const page     = Math.max(1, parseInt(req.query.page, 10) || 1);
  const pageSize = Math.min(500, Math.max(1, parseInt(req.query.pageSize, 10) || 50));
  const offset   = (page - 1) * pageSize;
  const wantPaged = req.query.page != null || req.query.pageSize != null;
  // Default order: bill number ascending. `bil` is a real INTEGER column, so
  // no CAST is needed here (unlike purchases.invo / debit_notes.note_no).
  const baseQuery = 'SELECT * FROM bills ' + where + ' ORDER BY bil, date';
  if (wantPaged) {
    const total = db.get('SELECT COUNT(*) AS c FROM bills ' + where, p).c;
    const rows = db.all(baseQuery + ' LIMIT ? OFFSET ?', [...p, pageSize, offset]);
    return res.json({ rows: withFmtDate(rows), total, page, pageSize });
  }
  res.json(withFmtDate(db.all(baseQuery + ' LIMIT 500', p)));
});

// Generate agri bill for a seller
app.post('/api/bills/generate/:auctionId',
  requireInvoiceWrite,
  requirePriceChecked(req => parseInt(req.params.auctionId, 10)),
  (req, res) => {
  const db = getDb(); const cfg = getSettingsFlat(db);
  const { sellerName, billNo } = req.body;
  
  if (!sellerName || !billNo) {
    return res.status(400).json({ error: 'sellerName and billNo are required' });
  }
  
  // Auto-calculate if needed
  const uncalc = db.all(`SELECT * FROM lots WHERE auction_id = ? AND amount > 0 AND (puramt IS NULL OR puramt = 0)`, [req.params.auctionId]);
  for (const lot of uncalc) {
    const c = calculateLot(lot, cfg);
    db.run(`UPDATE lots SET pqty=?,prate=?,puramt=?,com=?,sertax=?,cgst=?,sgst=?,igst=?,advance=?,balance=?,bilamt=?,refund=?,refud=?,isp_pqty=?,isp_prate=?,isp_puramt=?,asp_pqty=?,asp_prate=?,asp_puramt=? WHERE id=?`,
      [c.pqty,c.prate,c.puramt,c.com,c.sertax,c.cgst,c.sgst,c.igst,c.advance,c.balance,c.bilamt,c.refund||0,c.refud||0,c.isp_pqty||0,c.isp_prate||0,c.isp_puramt||0,c.asp_pqty||0,c.asp_prate||0,c.asp_puramt||0,lot.id]);
  }
  
  // ── Mode resolution (flag_lotwise_bills) ─────────────────────────────
  // Mirrors the purchase contract: a lot identifier in the body means a
  // LOT-WISE bill for that one lot; its absence means the classic
  // seller-wise bill. Both are validated against the flag so a stale tab
  // cannot write a document in the mode the site isn't configured for.
  const reqLotNo = String(req.body.lotNo == null ? '' : req.body.lotNo).trim();
  const reqLotId = req.body.lotId;
  const wantsLotWise = reqLotNo !== '' || (reqLotId != null && String(reqLotId).trim() !== '');
  const lotWiseCfg = lotwiseBillsOn(db);
  if (wantsLotWise && !lotWiseCfg) {
    return res.status(403).json({
      error: 'Lot-wise bills of supply are disabled. Enable "Lot-wise Bills of Supply" in Settings → Flags.',
      mode: 'seller',
    });
  }
  if (!wantsLotWise && lotWiseCfg) {
    return res.status(400).json({
      error: 'This site is set to LOT-WISE bills of supply, but no lot was selected. Reload the page and pick a lot.',
      mode: 'lot',
    });
  }

  const auction = db.get('SELECT * FROM auctions WHERE id = ?', [req.params.auctionId]);

  // Duplicate guard — lot-wise only, so seller-wise generation is unchanged.
  // Scoped by trade number because that is how bills are keyed.
  if (wantsLotWise) {
    const dupe = db.get(
      `SELECT bil FROM bills
        WHERE TRIM(ano) = TRIM(?) AND UPPER(TRIM(name)) = UPPER(TRIM(?))
          AND TRIM(COALESCE(lot_no,'')) = ? LIMIT 1`,
      [String(auction.ano), String(sellerName || ''), reqLotNo]
    );
    if (dupe) {
      return res.status(409).json({
        error: `Lot ${reqLotNo} already has bill of supply #${dupe.bil} for ${sellerName} in this trade.`,
        existingBillNo: dupe.bil,
      });
    }
  }

  // traderId / userId identify WHICH planter when the name is shared.
  const bill = buildAgriBill(db, req.params.auctionId, sellerName, cfg,
    { traderId: req.body.traderId, userId: req.body.userId,
      lotNo: reqLotNo, lotId: reqLotId });
  if (!bill || bill.error) {
    return res.status(404).json({ error: bill?.error || 'No eligible lots found' });
  }

  const s = bill.summary;
  db.run(`INSERT INTO bills (auction_id,ano,date,state,br,crpt,bil,name,add_line,pla,pstate,st_code,crr,pan,qty,cost,igst,net,line_items,trader_id,lot_no,lot_id)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
    [req.params.auctionId,auction.ano,auction.date,auction.state||'','',auction.crop_type||(getSetting(getDb(),'default_crop_type')||'VST'),
     parseInt(billNo),bill.seller.name,bill.seller.address||'',bill.seller.place||'',
     bill.seller.state||'',bill.seller.st_code||'',bill.seller.cr||'',bill.seller.pan||'',
     s.totalQty,s.totalPuramt,0,s.netAmount,JSON.stringify(bill.lineItems||[]),
         bill.seller.trader_id || null,
     // Empty lot_no is what marks this row seller-wise, for every future reader.
     bill.lotNo || '', bill.lotId]);

  res.json({ success: true, bill: s, mode: wantsLotWise ? 'lot' : 'seller', lotNo: bill.lotNo || '' });
});

// List eligible agri sellers for an auction (no GSTIN + amount > 0)
app.get('/api/bills/eligible-sellers/:auctionId', requireView, (req, res) => {
  res.json(listAgriSellers(getDb(), req.params.auctionId));
});

// ── LOT-WISE eligible list (flag_lotwise_bills) ──────────────────────────
// Lot-wise counterpart of /eligible-sellers: one row per LOT rather than one
// per planter. Same eligibility rule as listAgriSellers (NO valid GSTIN,
// amount > 0), so both lists cover exactly the same lots.
//
// `already_billed` is advisory for the UI — it surfaces lots that already
// carry a lot-wise bill in this trade. Bills are keyed by trade NUMBER (ano),
// not auction_id, so the existence check joins through the auction the same
// way the generation gate does.
app.get('/api/bills/eligible-lots/:auctionId', requireView, (req, res) => {
  const db = getDb();
  const aid = req.params.auctionId;
  const auction = db.get('SELECT ano FROM auctions WHERE id = ?', [aid]);
  if (!auction) return res.status(404).json({ error: 'Auction not found' });
  res.json(db.all(
    `SELECT l.id AS lot_id, l.lot_no, l.name, l.trader_id,
            CASE WHEN UPPER(TRIM(COALESCE(l.user_id,''))) IN ('','IMPORT')
                 THEN '' ELSE TRIM(l.user_id) END AS user_id,
            l.grade, l.bags, l.qty, l.price, l.amount, l.cr,
            (SELECT b.bil FROM bills b
              WHERE TRIM(b.ano) = TRIM(?)
                AND TRIM(COALESCE(b.lot_no,'')) = TRIM(l.lot_no)
                AND UPPER(TRIM(b.name)) = UPPER(TRIM(l.name))
              LIMIT 1) AS already_billed
       FROM lots l
      WHERE l.auction_id = ? AND l.name IS NOT NULL AND l.name != ''
        AND l.amount > 0
        AND (l.reserved IS NULL OR l.reserved = 0)
        AND UPPER(TRIM(COALESCE(l.code,''))) NOT IN ('WD','NA')
        AND NOT ${hasValidGstinSql('l.cr')}
      -- Lot-wise bills are numbered in LOT order, not seller order, so the
      -- picker lists lots the same way the batch run will bill them.
      ORDER BY CAST(l.lot_no AS INTEGER), l.lot_no`,
    [String(auction.ano), aid]
  ));
});

// Batch: generate bill of supply for ALL agriculturists (no GSTIN) in an auction
app.post('/api/bills/generate-all/:auctionId',
  requireInvoiceWrite,
  requirePriceChecked(req => parseInt(req.params.auctionId, 10)),
  (req, res) => {
  const db = getDb(); const cfg = getSettingsFlat(db);
  const { startBillNo } = req.body;
  
  let nextNo = parseInt(startBillNo);
  if (!nextNo || nextNo < 1) return res.status(400).json({ error: 'startBillNo must be a positive integer' });
  
  // Auto-calculate
  const uncalc = db.all(`SELECT * FROM lots WHERE auction_id = ? AND amount > 0 AND (puramt IS NULL OR puramt = 0)`, [req.params.auctionId]);
  for (const lot of uncalc) {
    const c = calculateLot(lot, cfg);
    db.run(`UPDATE lots SET pqty=?,prate=?,puramt=?,com=?,sertax=?,cgst=?,sgst=?,igst=?,advance=?,balance=?,bilamt=?,refund=?,refud=?,isp_pqty=?,isp_prate=?,isp_puramt=?,asp_pqty=?,asp_prate=?,asp_puramt=? WHERE id=?`,
      [c.pqty,c.prate,c.puramt,c.com,c.sertax,c.cgst,c.sgst,c.igst,c.advance,c.balance,c.bilamt,c.refund||0,c.refud||0,c.isp_pqty||0,c.isp_prate||0,c.isp_puramt||0,c.asp_pqty||0,c.asp_prate||0,c.asp_puramt||0,lot.id]);
  }
  
  // ── Mode resolution (flag_lotwise_bills) ─────────────────────────────
  // Seller-wise walks listAgriSellers exactly as before. Lot-wise walks one
  // row per LOT, using the same eligibility rule so both modes cover an
  // identical set of lots and differ only in document count.
  const lotWise = lotwiseBillsOn(db);
  const auction = db.get('SELECT * FROM auctions WHERE id = ?', [req.params.auctionId]);

  const sellers = lotWise
    ? db.all(
        `SELECT l.id AS lot_id, l.lot_no, l.name, l.trader_id,
                CASE WHEN UPPER(TRIM(COALESCE(l.user_id,''))) IN ('','IMPORT')
                     THEN '' ELSE TRIM(l.user_id) END AS user_id
           FROM lots l
          WHERE l.auction_id = ?
            AND l.amount > 0
            AND l.name IS NOT NULL AND l.name != ''
            AND (l.reserved IS NULL OR l.reserved = 0)
            AND UPPER(TRIM(COALESCE(l.code,''))) NOT IN ('WD','NA')
            AND NOT ${hasValidGstinSql('l.cr')}
          -- Bill numbers are handed out in the order this list is walked, so
          -- lot-wise runs number ASCENDING BY LOT NO (not grouped by seller).
          ORDER BY CAST(l.lot_no AS INTEGER), l.lot_no`,
        [req.params.auctionId]
      )
    : listAgriSellers(db, req.params.auctionId);

  if (!sellers.length) return res.status(404).json({
    error: lotWise
      ? 'No eligible lots (non-GSTIN planter) in this auction'
      : 'No agriculturist sellers (without GSTIN) with lots in this auction'
  });

  const results = [];
  const errors = [];
  const skipped = [];

  // Lots already carrying a lot-wise bill in this trade, so a re-run tops up
  // the missing ones instead of double-billing. Seller-wise runs skip this
  // entirely and behave exactly as before.
  const alreadyDone = new Set();
  if (lotWise) {
    for (const r of db.all(
      `SELECT name, lot_no FROM bills
        WHERE TRIM(ano) = TRIM(?) AND TRIM(COALESCE(lot_no,'')) <> ''`,
      [String(auction.ano)]
    )) alreadyDone.add(`${String(r.name || '').trim().toUpperCase()}|${String(r.lot_no || '').trim()}`);
  }

  for (const row of sellers) {
    const label = lotWise ? `${row.name} — lot ${row.lot_no}` : row.name;
    try {
      if (lotWise) {
        const key = `${String(row.name || '').trim().toUpperCase()}|${String(row.lot_no || '').trim()}`;
        if (alreadyDone.has(key)) {
          skipped.push({ seller: row.name, lotNo: row.lot_no, reason: 'Already billed' });
          continue;
        }
      }
      const bill = buildAgriBill(db, req.params.auctionId, row.name, cfg,
        { traderId: row.trader_id, userId: row.user_id,
          lotNo: lotWise ? row.lot_no : '', lotId: lotWise ? row.lot_id : null });
      if (!bill || bill.error) { errors.push({ seller: label, error: bill?.error || 'Build failed' }); continue; }
      const s = bill.summary;
      db.run(`INSERT INTO bills (auction_id,ano,date,state,br,crpt,bil,name,add_line,pla,pstate,st_code,crr,pan,qty,cost,igst,net,line_items,trader_id,lot_no,lot_id)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [req.params.auctionId,auction.ano,auction.date,auction.state||'','',auction.crop_type||(getSetting(getDb(),'default_crop_type')||'VST'),
         nextNo,bill.seller.name,bill.seller.address||'',bill.seller.place||'',
         bill.seller.state||'',bill.seller.st_code||'',bill.seller.cr||'',bill.seller.pan||'',
         s.totalQty,s.totalPuramt,0,s.netAmount,JSON.stringify(bill.lineItems||[]),
         bill.seller.trader_id || null,
         bill.lotNo || '', bill.lotId]);
      results.push({ seller: row.name, lotNo: lotWise ? row.lot_no : '', billNo: nextNo, netAmount: s.netAmount });
      nextNo++;
    } catch (e) { errors.push({ seller: label, error: e.message }); }
  }

  res.json({ success: true, mode: lotWise ? 'lot' : 'seller',
             generated: results.length, results, errors, skipped });
});

// Bill-of-Supply PDFs render per-lot rows from the live `lots` table via
// buildAgriBill(). A bill's stored `auction_id` can go stale when its trade
// is deleted + re-imported under a new id, which makes the primary lookup
// fail and the PDF fall back to the stored summary — dropping the LOT NO
// column. Recover by re-resolving the auction through the bill's trade
// number (`ano`). Because this is a tax document we only accept a recovered
// auction whose recomputed net matches the stored bill net (guards against
// `ano` collisions across trades); a unique-ano hit is trusted even if the
// net drifted slightly (e.g. a config change). Returns a built bill with
// lineItems, or null when nothing matches confidently.
function recoverAgriBillByAno(db, stored, cfg, triedAuctionId) {
  if (!stored || stored.ano == null || String(stored.ano).trim() === '') return null;
  const cands = db.all(
    'SELECT id FROM auctions WHERE CAST(ano AS TEXT) = CAST(? AS TEXT) ORDER BY id',
    [String(stored.ano)]
  );
  const storedNet = Number(stored.net) || 0;
  let firstHit = null;
  for (const a of cands) {
    if (triedAuctionId != null && String(a.id) === String(triedAuctionId)) continue;
    // Lot scope must travel into the recovery rebuild too. Rebuilding a
    // lot-wise bill for the whole seller would produce a net that cannot
    // match stored.net, so recovery would reject every candidate and the
    // PDF would silently fall back to the stored snapshot.
    const b = buildAgriBill(db, a.id, stored.name, cfg, billRebuildOpts(stored));
    if (b && !b.error) {
      if (!firstHit) firstHit = b;
      const net = Number(b.summary && b.summary.netAmount) || 0;
      if (storedNet <= 0 || Math.abs(net - storedNet) <= Math.max(2, storedNet * 0.005)) return b;
    }
  }
  // Single auction carries this ano → no collision risk, so a found-but-
  // net-mismatched candidate is still safe to use.
  if (firstHit && cands.length === 1) return firstHit;
  return null;
}

// Build a bill from the per-lot snapshot stored on the bill row at
// generation time (bills.line_items JSON). This is the authoritative source
// once lots may have changed. Returns null when no snapshot is present.
function billFromStoredSnapshot(stored) {
  if (!stored || !stored.line_items) return null;
  let li;
  try { li = JSON.parse(stored.line_items); } catch (_) { return null; }
  if (!Array.isArray(li) || !li.length) return null;
  return {
    seller: { name: stored.name, address: stored.add_line, place: stored.pla, state: stored.pstate, st_code: stored.st_code, cr: stored.crr, crno: stored.crr, pan: stored.pan },
    lineItems: li,
    summary: { totalQty: stored.qty, totalPuramt: stored.cost, roundDiff: 0, netAmount: stored.net, cgst: 0, sgst: 0, igst: 0, tax: 0 }
  };
}

// Last-resort fallback when no per-lot data is recoverable (older imported
// bills whose lots no longer exist anywhere). Renders ONE consolidated line
// so PRICE/VALUE reflect the bill's real money (derived from the stored
// totals) instead of 0. Lot is left blank — the per-lot detail is gone.
function consolidatedBillFromStored(stored) {
  const qty = Number(stored.qty) || 0;
  const cost = Number(stored.cost) || 0;
  const rate = qty > 0 ? cost / qty : 0;
  return {
    seller: { name: stored.name, address: stored.add_line, place: stored.pla, state: stored.pstate, st_code: stored.st_code, cr: stored.crr, crno: stored.crr, pan: stored.pan },
    lineItems: [{ lot: '', qty, pqty: qty, totalQty: qty, refundQty: 0, price: rate, prate: rate, amount: cost, puramt: cost }],
    summary: { totalQty: qty, totalPuramt: cost, roundDiff: 0, netAmount: Number(stored.net) || Math.round(cost), cgst: 0, sgst: 0, igst: 0, tax: 0 }
  };
}

// Cache a freshly-resolved per-lot snapshot back onto the bill row (only
// when it doesn't already have one) so future views survive lot edits or
// deletes. Best-effort — never blocks the PDF.
function cacheBillLineItems(db, billId, lineItems) {
  if (!billId || !Array.isArray(lineItems) || !lineItems.length) return;
  try {
    db.run("UPDATE bills SET line_items = ? WHERE id = ? AND (line_items IS NULL OR line_items = '')",
      [JSON.stringify(lineItems), billId]);
  } catch (_) { /* caching must not break the PDF */ }
}

// Agri bill PDF
app.get('/api/bills/pdf/:auctionId/:sellerName', requireView, async (req, res) => {
  try {
    const db = getDb(); const cfg = getSettingsFlat(db);
    const sellerName = decodeURIComponent(req.params.sellerName);
    const billNo = req.query.billNo || '001';

    const storedRow = db.get('SELECT * FROM bills WHERE name = ? AND bil = ? LIMIT 1', [sellerName, parseInt(billNo)]);
    // storedRow.trader_id pins which planter this bill was raised for; without
    // it a duplicated name rebuilds from BOTH planters' lots. billRebuildOpts
    // adds the lot scope for lot-wise rows, so a one-lot bill does not reprint
    // carrying the planter's entire lot list.
    let bill = buildAgriBill(db, req.params.auctionId, sellerName, cfg,
      billRebuildOpts(storedRow));
    let live = bill && !bill.error;
    if (!live) {
      if (!storedRow) return res.status(404).json({ error: bill?.error || `No bill data found for "${sellerName}"` });
      // Resolution order: live lots via the bill's trade number → the per-lot
      // snapshot stored at generation → a consolidated summary line (PRICE /
      // VALUE derived from the stored totals so they're never shown as 0).
      const recovered = recoverAgriBillByAno(db, storedRow, cfg, req.params.auctionId);
      if (recovered) { bill = recovered; live = true; }
      else { bill = billFromStoredSnapshot(storedRow) || consolidatedBillFromStored(storedRow); }
    }
    // Cache real per-lot data (live / ano-recovered) onto the bill row so it
    // keeps LOT NO / PRICE / VALUE even if the lots are later changed.
    if (live && storedRow) cacheBillLineItems(db, storedRow.id, bill.lineItems);
    // Enrich seller.crno so the new renderer can display "CR.<n>" in the
    // details block when CR/GSTIN-style id is available on the trader row
    if (bill.seller && !bill.seller.crno) bill.seller.crno = bill.seller.cr || '';
    // Stamp the bill date + e-TRADE number so the new layout can render them
    // in the top strip (Invoice No / e-TRADE No / Date). Format follows
    // the operator's `date_format` Setting.
    const dateFmt = (cfg && cfg.date_format) || 'dd/mm/yyyy';
    const auction = db.get('SELECT date FROM auctions WHERE id = ?', [req.params.auctionId]);
    if (auction && auction.date) {
      bill.billDate = formatDateForDisplay(auction.date, dateFmt);
    }
    if (!bill.billDate) bill.billDate = formatDateForDisplay(new Date(), dateFmt);
    bill.eTradeNo = req.query.eTradeNo || req.params.auctionId;

    let pdf;
    const tplChoice = String((req.query.template) || (req.body && req.body.template) || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'agri_bill_engine', templateKey: 'agri_bill_template', tplChoice });
    // The printed number carries the configured bill-of-supply prefix; the raw
    // `billNo` above stays untouched because the bills lookup and the download
    // filename both key off the stored integer.
    const printedBillNo = formatBillOfSupplyNo(cfg, billNo, { ano: storedRow ? storedRow.ano : '' });
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, agri_bill_template: tplChoice } : cfg;
      pdf = await require('./pdf/render-agri-html').generateAgriBillHtmlPDF(bill, cfg2, printedBillNo);
    } else {
      pdf = await generateAgriBillPDF(bill, cfg, printedBillNo);
    }
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="BillOfSupply_${sellerName.replace(/[^\w]/g,'_')}_${billNo}.pdf"`);
    res.send(pdf);
  } catch(e) {
    console.error('Agri Bill PDF error:', e);
    res.status(500).json({ error: 'PDF generation failed: ' + e.message });
  }
});

// Commission Bill (Format 2) — auction-wide commission/handling summary.
// Renders as PDF or XLSX. One row per seller; totals row at the bottom.
// Optional ?branch=<NAME> restricts to lots in that branch.
//
// PDF/XLSX is opened in a new tab via window.open(), so we accept the
// token as a query string (mirrors other windowed routes).
app.get('/api/bills/commission-bill-f2/:auctionId', (req, res, next) => {
  const hdr = (req.headers.authorization || '').replace('Bearer ', '');
  const tok = hdr || String(req.query.token || '');
  if (!tok) return res.status(401).json({ error: 'No token' });
  const db = getDb();
  const session = db.get('SELECT * FROM sessions WHERE token = ?', [tok]);
  if (!session) return res.status(403).json({ error: 'Session expired' });
  const user = db.get('SELECT * FROM users WHERE id = ?', [session.user_id]);
  if (!user) return res.status(403).json({ error: 'Unauthorized' });
  req.user = user;
  next();
}, async (req, res) => {
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const auctionId = parseInt(req.params.auctionId, 10);
    const auction = db.get('SELECT * FROM auctions WHERE id = ?', [auctionId]);
    if (!auction) return res.status(404).json({ error: 'Trade not found' });

    const branchFilter = String(req.query.branch || '').trim();
    const where = branchFilter ? ' AND l.branch = ?' : '';
    const params = branchFilter ? [auctionId, branchFilter] : [auctionId];

    // One row per seller — sum the per-lot commission/handling/refund/GST.
    const rows = db.all(
      `SELECT l.name, l.branch, l.cr,
              COUNT(*) AS lots,
              COALESCE(SUM(l.qty),0)     AS qty,
              COALESCE(SUM(l.amount),0)  AS puramt,
              COALESCE(SUM(l.refund),0)  AS refund,
              COALESCE(SUM(l.com),0)     AS commission,
              COALESCE(SUM(l.sertax),0)  AS handling,
              COALESCE(SUM(l.cgst),0)    AS cgst,
              COALESCE(SUM(l.sgst),0)    AS sgst,
              COALESCE(SUM(l.igst),0)    AS igst
         FROM lots l
        WHERE l.auction_id = ? AND l.amount > 0` + where +
       ` GROUP BY l.name
         ORDER BY l.name`,
      params
    );

    const totals = rows.reduce((acc, r) => {
      acc.lots       += Number(r.lots) || 0;
      acc.qty        += Number(r.qty) || 0;
      acc.puramt     += Number(r.puramt) || 0;
      acc.refund     += Number(r.refund) || 0;
      acc.commission += Number(r.commission) || 0;
      acc.handling   += Number(r.handling) || 0;
      acc.cgst       += Number(r.cgst) || 0;
      acc.sgst       += Number(r.sgst) || 0;
      acc.igst       += Number(r.igst) || 0;
      return acc;
    }, { lots:0, qty:0, puramt:0, refund:0, commission:0, handling:0, cgst:0, sgst:0, igst:0 });
    totals.gst = totals.cgst + totals.sgst + totals.igst;
    // Net due to the seller = amount + refund − commission − gst − handling.
    totals.netDue = totals.puramt + totals.refund - totals.commission - totals.gst - totals.handling;

    const fmtAmt = (n) => Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const fmtQty = (n) => Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
    const dateFmt = auction.date ? fmtDate(auction.date) : '';
    const format = String(req.query.format || 'pdf').toLowerCase();

    if (format === 'xlsx') {
      const ExcelJS = require('exceljs');
      const wb = new ExcelJS.Workbook();
      const ws = wb.addWorksheet('CommissionBillF2');
      ws.columns = [
        { width: 5 }, { width: 28 }, { width: 14 }, { width: 8 }, { width: 12 },
        { width: 14 }, { width: 12 }, { width: 14 }, { width: 12 }, { width: 12 }, { width: 14 },
      ];
      const headerStartRow = writeXlsxCompanyHeader(wb, ws, getCompanyHeader(db), {
        colCount: 11,
        title: 'COMMISSION BILL (FORMAT 2)',
        metaLines: [
          `e-AUCTION No: ${auction.ano}`,
          `DATE: ${dateFmt}`,
          branchFilter ? `BRANCH: ${branchFilter}` : 'BRANCH: ALL',
        ],
      });
      const head = ws.getRow(headerStartRow);
      ['SL', 'SELLER', 'BRANCH', 'LOTS', 'QTY (kg)', 'AMOUNT', 'REFUND',
       'COMMISSION', 'HANDLING', 'GST', 'NET DUE'].forEach((h, i) => head.getCell(i + 1).value = h);
      head.font = { bold: true };
      head.eachCell(c => {
        c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFE8E4DD' } };
        c.border = { top: { style: 'thin' }, bottom: { style: 'thin' } };
        c.alignment = { horizontal: 'center', vertical: 'middle' };
      });
      rows.forEach((r, idx) => {
        const gst = (Number(r.cgst)||0)+(Number(r.sgst)||0)+(Number(r.igst)||0);
        const netDue = (Number(r.puramt)||0)+(Number(r.refund)||0)-(Number(r.commission)||0)-gst-(Number(r.handling)||0);
        const row = ws.addRow([
          idx + 1, r.name || '', r.branch || '', Number(r.lots) || 0,
          Number(r.qty) || 0, Number(r.puramt) || 0, Number(r.refund) || 0,
          Number(r.commission) || 0, Number(r.handling) || 0, gst, netDue,
        ]);
        row.getCell(5).numFmt = '#,##0.000';
        for (const c of [6, 7, 8, 9, 10, 11]) row.getCell(c).numFmt = '#,##,##0.00';
      });
      const totalsRow = ws.addRow([
        '', 'TOTAL', '', totals.lots, totals.qty, totals.puramt, totals.refund,
        totals.commission, totals.handling, totals.gst, totals.netDue,
      ]);
      totalsRow.font = { bold: true };
      totalsRow.getCell(5).numFmt = '#,##0.000';
      for (const c of [6, 7, 8, 9, 10, 11]) totalsRow.getCell(c).numFmt = '#,##,##0.00';
      totalsRow.eachCell(c => {
        c.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFF3CD' } };
        c.border = { top: { style: 'thin' }, bottom: { style: 'double' } };
      });
      const buf = await wb.xlsx.writeBuffer();
      res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
      res.setHeader('Content-Disposition',
        `attachment; filename="CommissionBillF2_${auction.ano}${branchFilter ? '_' + branchFilter : ''}.xlsx"`);
      return res.send(Buffer.from(buf));
    }

    // PDF path (default).
    const PDFDocument = require('pdfkit');
    const doc = new PDFDocument({ size: 'A4', layout: 'landscape', margin: 24 });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition',
      `inline; filename="CommissionBillF2_${auction.ano}${branchFilter ? '_' + branchFilter : ''}.pdf"`);
    doc.pipe(res);

    const m = 24, w = doc.page.width - m * 2;
    doc.font('Helvetica-Bold').fontSize(14).text('COMMISSION BILL (FORMAT 2)', m, m, { width: w, align: 'center' });
    doc.font('Helvetica').fontSize(10).text(
      `Trade #${auction.ano}   |   ${dateFmt}   |   Branch: ${branchFilter || 'All'}`,
      m, m + 18, { width: w, align: 'center' }
    );

    // Column layout. Widths are scaled below to exactly fill the printable
    // width so the right-most column (Net Due) can't overflow the page edge
    // (previously the columns summed wider than the page and Net Due clipped).
    const colDefs = [
      { k: 'sl',    label: '#',           w: 22,  align: 'right' },
      { k: 'name',  label: 'Seller',      w: 150, align: 'left'  },
      { k: 'branch',label: 'Branch',      w: 80,  align: 'left'  },
      { k: 'lots',  label: 'Lots',        w: 32,  align: 'right' },
      { k: 'qty',   label: 'Qty (kg)',    w: 66,  align: 'right' },
      { k: 'puramt',label: 'Amount',      w: 82,  align: 'right' },
      { k: 'refund',label: 'Refund',      w: 70,  align: 'right' },
      { k: 'commission', label: 'Commission', w: 82, align: 'right' },
      { k: 'handling',   label: 'Handling',   w: 72, align: 'right' },
      { k: 'gst',   label: 'GST',         w: 66,  align: 'right' },
      { k: 'netDue',label: 'Net Due',     w: 92,  align: 'right' },
    ];
    // Scale every column proportionally so the row spans exactly `w`.
    const _colTot = colDefs.reduce((s, c) => s + c.w, 0);
    colDefs.forEach(c => { c.w = c.w * (w / _colTot); });
    let cx = m;
    const colX = colDefs.map(c => { const x = cx; cx += c.w; return x; });
    let y = m + 50;
    doc.font('Helvetica-Bold').fontSize(9);
    colDefs.forEach((c, i) => doc.text(c.label, colX[i] + 2, y, { width: c.w - 4, align: c.align, lineBreak: false, ellipsis: true }));
    y += 14;
    doc.moveTo(m, y - 2).lineTo(m + w, y - 2).stroke();

    doc.font('Helvetica').fontSize(9);
    rows.forEach((r, idx) => {
      if (y > doc.page.height - 60) { doc.addPage(); y = m + 20; }
      const gst = (Number(r.cgst)||0)+(Number(r.sgst)||0)+(Number(r.igst)||0);
      const netDue = (Number(r.puramt)||0)+(Number(r.refund)||0)-(Number(r.commission)||0)-gst-(Number(r.handling)||0);
      const cells = [
        String(idx + 1), r.name || '', r.branch || '', String(r.lots || 0),
        fmtQty(r.qty), fmtAmt(r.puramt), fmtAmt(r.refund),
        fmtAmt(r.commission), fmtAmt(r.handling), fmtAmt(gst), fmtAmt(netDue),
      ];
      colDefs.forEach((c, i) => doc.text(cells[i], colX[i] + 2, y, { width: c.w - 4, align: c.align, lineBreak: false, ellipsis: true }));
      y += 13;
    });

    doc.moveTo(m, y).lineTo(m + w, y).stroke();
    y += 4;
    doc.font('Helvetica-Bold').fontSize(9);
    const totCells = [
      '', 'TOTAL', '', String(totals.lots),
      fmtQty(totals.qty), fmtAmt(totals.puramt), fmtAmt(totals.refund),
      fmtAmt(totals.commission), fmtAmt(totals.handling), fmtAmt(totals.gst), fmtAmt(totals.netDue),
    ];
    colDefs.forEach((c, i) => doc.text(totCells[i], colX[i] + 2, y, { width: c.w - 4, align: c.align, lineBreak: false, ellipsis: true }));

    doc.end();
  } catch (e) {
    if (!res.headersSent) res.status(500).json({ error: 'Commission Bill F2 failed: ' + e.message });
  }
});

// Bulk Agri Bill PDF — merges N bills into a single PDF.
// Body: { ids: [1, 2, 3, ...] } — DB row IDs from the `bills` table.
app.post('/api/bills/pdf-bulk', requireView, async (req, res) => {
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const ids = Array.isArray(req.body?.ids) ? req.body.ids.filter(Boolean) : [];
    if (!ids.length) return res.status(400).json({ error: 'No bill IDs provided' });

    const placeholders = ids.map(() => '?').join(',');
    const rows = db.all(`SELECT * FROM bills WHERE id IN (${placeholders})`, ids);
    if (!rows.length) return res.status(404).json({ error: 'No matching bills found' });

    const byId = new Map(rows.map(r => [r.id, r]));
    const ordered = ids.map(id => byId.get(Number(id))).filter(Boolean);

    const payloads = [];
    for (const stored of ordered) {
      // See the purchase reprint above — bills.trader_id pins the planter,
      // and billRebuildOpts adds the lot scope for lot-wise rows.
      let bill = stored.auction_id
        ? buildAgriBill(db, stored.auction_id, stored.name, cfg, billRebuildOpts(stored))
        : null;
      let live = bill && !bill.error;
      if (!live) {
        // Same resolution chain as the single-bill route: live lots via the
        // trade number → stored per-lot snapshot → consolidated summary line
        // (so PRICE / VALUE are derived from totals, never shown as 0).
        const recovered = recoverAgriBillByAno(db, stored, cfg, stored.auction_id);
        if (recovered) { bill = recovered; live = true; }
        else { bill = billFromStoredSnapshot(stored) || consolidatedBillFromStored(stored); }
      }
      if (live) cacheBillLineItems(db, stored.id, bill.lineItems);
      // Enrich for new renderer layout (Invoice No / e-TRADE No / Date strip)
      if (bill.seller && !bill.seller.crno) bill.seller.crno = bill.seller.cr || '';
      const dateFmt2 = (cfg && cfg.date_format) || 'dd/mm/yyyy';
      if (stored.auction_id) {
        const auction = db.get('SELECT date FROM auctions WHERE id = ?', [stored.auction_id]);
        if (auction && auction.date) {
          bill.billDate = formatDateForDisplay(auction.date, dateFmt2);
        }
      }
      if (!bill.billDate) bill.billDate = formatDateForDisplay(new Date(), dateFmt2);
      bill.eTradeNo = stored.auction_id || '';
      payloads.push({ billData: bill, billNo: formatBillOfSupplyNo(cfg, stored.bil, { ano: stored.ano }) });
    }

    let pdf;
    const tplChoice = String((req.body && req.body.template) || (req.query && req.query.template) || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'agri_bill_engine', templateKey: 'agri_bill_template', tplChoice });
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, agri_bill_template: tplChoice } : cfg;
      pdf = await require('./pdf/render-agri-html').generateAgriBillsHtmlBatchPDF(payloads, cfg2);
    } else {
      pdf = await generateAgriBillsBatchPDF(payloads, cfg);
    }
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="BillsOfSupply_Batch_${payloads.length}.pdf"`);
    res.send(pdf);
  } catch (e) {
    console.error('Bulk bill PDF error:', e);
    res.status(500).json({ error: 'Bulk PDF generation failed: ' + e.message });
  }
});

// ── Commission Bill / Payment Voucher — shared per-lot builders ──────────
// The memorandum ("PAYMENT VOUCHER — MEMORANDUM OF CARDAMOM SOLD THROUGH …")
// is one A4 page PER LOT, and the page is identical whether the seller was
// billed on a Bill of Supply (agriculturist, no GSTIN) or on a Purchase
// Invoice (registered dealer): same cardamom / sample-refund / trader-sample
// / commission rows, same GST-on-commission split, same NETT. Only the source
// document row differs. Both routes therefore share these two builders —
// /api/bills/commission-bos-bulk and /api/purchases/commission-bulk.

// Resolve the purchaser block for a SINGLE lot. The `buyers` master carries
// the full address (add1/add2, place, pin, state, GSTIN, PAN, SBL) — join on
// buyer CODE first, then buyer1/buyer name.
const EMPTY_COMMISSION_PURCHASER = Object.freeze({
  name: '', invo: '', address: '', place: '', pin: '', state: '', st_code: '',
  sbl: '', gstin: '', pan: '',
});
function commissionPurchaserForLot(db, cfg, l, opts) {
  l = l || {}; opts = opts || {};
  let buyerRow = null;
  if (l.code) buyerRow = db.get('SELECT * FROM buyers WHERE code = ? LIMIT 1', [l.code]);
  if (!buyerRow && (l.buyer1 || l.buyer)) {
    buyerRow = db.get(
      'SELECT * FROM buyers WHERE UPPER(TRIM(buyer1)) = UPPER(TRIM(?)) OR UPPER(TRIM(buyer)) = UPPER(TRIM(?)) LIMIT 1',
      [l.buyer1 || l.buyer, l.buyer1 || l.buyer]
    );
  }
  // The lot carries both stamps: `invo` (original tax invoice) and
  // `proforma_invo` (the draft the buyer was shipped against). A lot with no
  // draft stamp falls back to the original rather than printing an empty INV —
  // a blank there reads as "not yet invoiced".
  const pfNo = String(l.proforma_invo || '').trim();
  const invoLabel = (opts.invoiceNoSrc === 'proforma' && pfNo)
    ? formatInvoiceNo(opts.pfPrefix, l.sale, pfNo)
    : (l.invo || '');
  return {
    name:    (buyerRow && (buyerRow.buyer1 || buyerRow.buyer)) || l.buyer1 || l.buyer || '',
    invo:    invoLabel,
    address: buyerRow ? [buyerRow.add1, buyerRow.add2].filter(Boolean).join(', ') : '',
    place:   buyerRow ? (buyerRow.pla || '') : '',
    pin:     buyerRow ? (buyerRow.pin || '') : '',
    state:   buyerRow ? (buyerRow.state || '') : (l.sale === 'L' ? (cfg.state || '') : ''),
    st_code: buyerRow ? (buyerRow.st_code || '') : '',
    sbl:     buyerRow ? (buyerRow.sbl || '') : '',
    gstin:   buyerRow ? (buyerRow.gstin || '') : '',
    pan:     buyerRow ? (buyerRow.pan || '') : '',
  };
}

// One page-spec per lot. Each carries a single line item, that lot's own
// commission/GST split, its purchaser, and its NETT (cardamom cost + refund −
// commission − GST, matching the renderer's own fallback so the printed
// deduction rows add up on every page).
//
// Sample refund quantity is the company-wide "SB Sample Refund (Kgs)" setting
// (Settings → Rates & Charges → `sb_refund`); the rupee value stored on the lot
// (`refund`) was already calculated as sb_refund × rate during lot entry.
//
// Trader sample (`sb_trader_sample`, Kgs) is DISPLAY-ONLY: it's folded into the
// SAMPLE REFUND line (+ts) and shown again as a TRADER SAMPLE deduction (−ts),
// so it nets to zero. It must NOT be subtracted from NETT — doing so
// double-counts it and drops the Grand Total below the sum of the printed rows.
//
// Lots from one seller can go to different buyers, so the purchaser is
// resolved per lot rather than once per document.
function commissionPagesFromLots(db, cfg, lots, opts) {
  opts = opts || {};
  const sbRefundKg      = Number(cfg.sb_refund) || 0;
  const sbTraderSampleKg = Number(cfg.sb_trader_sample) || 0;
  const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;
  return (lots || []).map(l => {
    const qty  = Number(l.pqty || l.qty || 0);
    const rate = Number(l.prate || l.price || 0);
    const cardamomCost = Number(l.puramt || l.amount || (qty * rate));
    const refundAmount = Number(l.refund || 0);
    const com = Number(l.com || 0), cg = Number(l.cgst || 0), sg = Number(l.sgst || 0), ig = Number(l.igst || 0);
    const traderSampleAmount = round2(sbTraderSampleKg * rate);
    return {
      line: { lot: l.lot_no, qty, bags: l.bags || 0, rate, cardamomCost,
              refundQty: sbRefundKg, refundRate: rate, refundAmount,
              traderSampleQty: sbTraderSampleKg, traderSampleAmount },
      purchaser: commissionPurchaserForLot(db, cfg, l, opts),
      commission: com, cgst: cg, sgst: sg, igst: ig,
      interState: !!(l.sale && l.sale !== 'L'),
      nett: round2(cardamomCost + refundAmount - com - cg - sg - ig),
      crpt: l.crpt || '',
    };
  });
}

// Which sales-invoice number the memorandum quotes in the PURCHASER block
// ("INV: …"). Only meaningful once flag_proforma_invoice is on: the buyer may
// have been shipped against a proforma draft and billed later under a
// different original number, so the print UI asks the operator which one to
// use. Every request from a build with the flag off stays on the original
// number.
//
// With the flag ON and no invoiceNo sent — the Auction Desk tile and the
// WhatsApp send both post bare { ids } — the default is 'proforma', matching
// what the Bills screen's picker offers as its only live option. Callers that
// genuinely want the original series say so explicitly.
function commissionInvoiceNoOpts(db, cfg, req) {
  const asked = String(req.body?.invoiceNo || '').trim().toLowerCase();
  const invoiceNoSrc = (proformaFeatureOn(db) && asked !== 'original')
    ? 'proforma' : 'original';
  // Draft numbers print in their document form ("PI/L-5"), the same prefix +
  // sale-letter shape Collection and the Buyer Statement use — a bare "5"
  // would be unreadable next to the original series.
  return { invoiceNoSrc, pfPrefix: String(cfg.proforma_invoice_prefix || '').trim() };
}

// Bulk Commission Bill (Bill of Supply variant) for selected bills.
// One A4 page per bill: layout modeled on the IMCPC commission-bill
// reference — seller + purchaser block, per-lot cardamom cost + sample
// refund rows, a final [-] COMMISSION row, NETT AMOUNT, amount in words.
// No CGST/SGST columns (Bill of Supply).
//
// Per-lot purchaser/refund/commission info is reconstructed from the
// `lots` table (same source `buildAgriBill` uses for per-lot detail).
app.post('/api/bills/commission-bos-bulk', requireView, async (req, res) => {
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const ids = Array.isArray(req.body?.ids) ? req.body.ids.filter(Boolean) : [];
    if (!ids.length) return res.status(400).json({ error: 'No bill IDs provided' });

    // Which sales-invoice number goes in the PURCHASER block ("INV: …").
    const invoOpts = commissionInvoiceNoOpts(db, cfg, req);

    const placeholders = ids.map(() => '?').join(',');
    const stored = db.all(`SELECT * FROM bills WHERE id IN (${placeholders})`, ids);
    if (!stored.length) return res.status(404).json({ error: 'No matching bills found' });

    const byId = new Map(stored.map(r => [r.id, r]));
    const ordered = ids.map(id => byId.get(Number(id))).filter(Boolean);

    const payloads = [];
    for (const b of ordered) {
      // Resolve the auction record (id + ano + date) so we can pull the
      // matching lots and format the eAuction strip.
      // A stored auction_id can go stale when the trade was deleted and
      // re-imported under a new id (same failure recoverAgriBillByAno
      // guards against on the single-bill route). The old `else if` meant
      // a non-null-but-dead auction_id blocked the `ano` fallback, leaving
      // lots empty — so the bill printed the em-dash placeholder line with
      // no LOT NO and no SAMPLE REFUND rows. Build a candidate list (stored
      // id first, then every auction carrying this trade number) and keep
      // the first that actually has lots for this seller. The cr-field /
      // amount filter mirrors buildAgriBill: skip GSTIN-registered sellers.
      //
      // A LOT-WISE bill (flag_lotwise_bills) covers exactly one lot, and the
      // row records which one. Narrow to it — the same contract billRebuildOpts
      // enforces for every other reprint path. Without the narrowing, a grower
      // with three lot-wise bills got all three lots on EACH of them: three
      // near-identical 3-page memoranda instead of one page apiece, with the
      // page count squaring on a "Commission Bill Selected" over a whole trade
      // (which is enough to OOM-kill the PDF renderer on a real auction).
      // A blank lot_no means the row was raised seller-wise, so it keeps
      // spanning every lot, exactly as before.
      const billLotNo = String(b.lot_no == null ? '' : b.lot_no).trim();
      const lotsForAuction = (aid) => (billLotNo
        ? db.all(
            `SELECT * FROM lots
               WHERE auction_id = ?
                 AND UPPER(TRIM(name)) = UPPER(TRIM(?))
                 AND (amount > 0 OR puramt > 0)
                 AND (${b.lot_id != null ? 'id = ? OR ' : ''}TRIM(CAST(lot_no AS TEXT)) = TRIM(CAST(? AS TEXT)))
             ORDER BY lot_no`,
            b.lot_id != null ? [aid, b.name, b.lot_id, billLotNo] : [aid, b.name, billLotNo]
          )
        : db.all(
            `SELECT * FROM lots
               WHERE auction_id = ?
                 AND UPPER(TRIM(name)) = UPPER(TRIM(?))
                 AND (amount > 0 OR puramt > 0)
             ORDER BY lot_no`,
            [aid, b.name]
          ));
      const auctionCands = [];
      if (b.auction_id) {
        const a = db.get('SELECT id, ano, date FROM auctions WHERE id = ?', [b.auction_id]);
        if (a) auctionCands.push(a);
      }
      if (b.ano != null && String(b.ano).trim() !== '') {
        const more = db.all(
          'SELECT id, ano, date FROM auctions WHERE CAST(ano AS TEXT) = CAST(? AS TEXT) ORDER BY id',
          [String(b.ano)]
        );
        for (const a of more) if (!auctionCands.some(c => c.id === a.id)) auctionCands.push(a);
      }
      let auction = auctionCands[0] || null;
      let lots = [];
      for (const a of auctionCands) {
        const ls = lotsForAuction(a.id);
        if (ls.length) { auction = a; lots = ls; break; }
      }

      // First lot supplies seller details (consistent with buildAgriBill).
      const first = lots[0] || {};
      const seller = {
        name: b.name || first.name || '',
        address: b.add_line || first.padd || '',
        place:   b.pla     || first.ppla || '',
        pin:     b.ppin    || first.ppin || '',
        state:   b.pstate  || first.pstate || '',
        st_code: b.st_code || first.pst_code || '',
        cr:      b.crr     || first.cr || '',
        pan:     b.pan     || first.pan || '',
        aadhar:  b.aadhar  || first.aadhar || '',
      };
      // Seller phone + bank account for the commission bill (shown only when
      // flag_commission_bank is on, Letterhead layout). Phone from the trader master
      // (fallback to the denormalised lot value); account prefers the trader's
      // default bank (trader_banks) then the legacy single-account column.
      try {
        // Resolve the trader by the lot's trader_id first (most reliable),
        // then by name — so phone/account populate even when the stored bill
        // name differs slightly from the trader master.
        let t = null;
        if (first.trader_id) t = db.get('SELECT id, tel, acctnum FROM traders WHERE id = ? LIMIT 1', [first.trader_id]);
        if (!t) t = db.get('SELECT id, tel, acctnum FROM traders WHERE UPPER(TRIM(name)) = UPPER(TRIM(?)) LIMIT 1', [seller.name]);
        seller.phone = (t && t.tel) || first.tel || '';
        let acct = (t && t.acctnum) || '';
        if (t && t.id) {
          const tb = db.get('SELECT acctnum FROM trader_banks WHERE trader_id = ? ORDER BY is_default DESC, id LIMIT 1', [t.id]);
          if (tb && tb.acctnum) acct = tb.acctnum;
        }
        seller.account = acct;
      } catch (_) { seller.phone = first.tel || ''; seller.account = ''; }

      // ── One Commission Bill page PER LOT ──────────────────────
      // A grower with two lots gets TWO commission bills, each showing
      // only that lot's cardamom cost / sample-refund / commission / GST
      // / NETT — and its OWN purchaser. See commissionPagesFromLots().
      const sbRefundKg = Number(cfg.sb_refund) || 0;
      const sbTraderSampleKg = Number(cfg.sb_trader_sample) || 0;
      const emptyPurchaser = { ...EMPTY_COMMISSION_PURCHASER };
      const round2 = (n) => Math.round((Number(n) || 0) * 100) / 100;

      const perLot = commissionPagesFromLots(db, cfg, lots, invoOpts);
      if (!lots.length) {
        // Live lots are gone (e.g. deleted after generation). Rebuild from
        // the per-lot snapshot stored on the bill row at generation time
        // (bills.line_items JSON, written by buildAgriBill). Snapshot amounts
        // fold the sample-refund kg into `puramt`, so split them back out:
        // cardamomCost = soldQty×rate, refundAmount = refundQty×rate. The
        // snapshot carries no buyer or per-line GST, so purchaser stays
        // minimal and GST is 0.
        let snap = [];
        try { snap = JSON.parse(b.line_items || '[]'); } catch (_) { snap = []; }
        if (!Array.isArray(snap)) snap = [];
        for (const li of snap) {
          const qty  = Number(li.pqty || li.qty || 0);
          const rate = Number(li.price || li.prate || 0);
          const rQty = Number(li.refundQty != null ? li.refundQty : sbRefundKg) || 0;
          const cardamomCost = round2(qty  * rate);
          const refundAmount = round2(rQty * rate);
          const com = Number(li.com || 0);
          const traderSampleAmount = round2(sbTraderSampleKg * rate);
          perLot.push({
            line: { lot: li.lot, qty, bags: li.bags || 0, rate, cardamomCost,
                    refundQty: rQty, refundRate: rate, refundAmount,
                    traderSampleQty: sbTraderSampleKg, traderSampleAmount },
            purchaser: emptyPurchaser,
            commission: com, cgst: 0, sgst: 0, igst: 0, interState: false,
            // Trader sample is display-only (folded into SAMPLE REFUND, shown
            // again as a deduction → nets to zero); never subtract it here.
            nett: round2(cardamomCost + refundAmount - com),
            crpt: '',
          });
        }
      }

      // Format the auction date once (shared by every page of this bill).
      const dateFmt3 = (cfg && cfg.date_format) || 'dd/mm/yyyy';
      let billDate = '';
      if (auction && auction.date) billDate = formatDateForDisplay(auction.date, dateFmt3);
      if (!billDate && b.date) billDate = formatDateForDisplay(b.date, dateFmt3);

      // Last-resort: no live lots and no snapshot (older imported bills whose
      // lots are gone everywhere). Emit a single consolidated page from the
      // stored bill totals so the memorandum still prints.
      if (!perLot.length) {
        perLot.push({
          line: { lot: '—', qty: b.qty, bags: 0, rate: 0, cardamomCost: b.cost,
                  refundQty: 0, refundRate: 0, refundAmount: 0 },
          purchaser: emptyPurchaser,
          commission: 0, cgst: 0, sgst: 0, igst: 0, interState: false,
          nett: Number(b.net != null ? b.net : b.cost) || 0,
          crpt: '',
        });
      }

      // One payload (→ one A4 page) per lot. When a bill spans more than one
      // lot, suffix the Bill No per page (billno/1, billno/2, …) so each lot's
      // page carries a distinct number; a single-lot bill keeps the plain number.
      // The configured bill-of-supply prefix leads the stored number, so the
      // memorandum quotes the same bill number the Bill of Supply PDF prints;
      // the per-page /1, /2 tail still trails it.
      const bosNo = formatBillOfSupplyNo(cfg, b.bil, { ano: b.ano });
      perLot.forEach((pl, _lotIdx) => {
        payloads.push({
          billNo: perLot.length > 1 ? `${bosNo}/${_lotIdx + 1}` : String(bosNo),
          billData: {
            // Crop Receipt No = the LOT's own crop-receipt number (lots.crpt —
            // the auto-incremented "crop receipt book" value, e.g. 1293), per
            // page. NOT bills.crpt, which was stamped with the crop TYPE at
            // generation (e.g. "RNS") and would otherwise shadow the real
            // receipt number. Matches the purchase-commission path above.
            crpt: pl.crpt || first.crpt || '',
            auction: { ano: auction ? auction.ano : (b.ano || ''), date: billDate },
            seller,
            purchaser: pl.purchaser,
            lineItems: [pl.line],
            commission: pl.commission,
            cgst: pl.cgst, sgst: pl.sgst, igst: pl.igst,
            interState: pl.interState,
            gstRate: Number(cfg.commission_gst_rate) || 9.0,
            nett: pl.nett,
          },
        });
      });
    }

    // Per-print format choice: the print UI can pass a `template` (e.g.
    // 'letterhead' or 'classic') so the operator picks the layout at print time. When
    // supplied, it forces the HTML engine and overrides the saved template
    // for THIS download only. Without it, fall back to the saved engine/layout.
    const tplChoice = String((req.body && req.body.template) || (req.query && req.query.template) || '').trim();
    let pdf;
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'commission_bill_engine', templateKey: 'commission_bill_template', tplChoice });
    if (useHtml) {
      // A named HTML template (e.g. 'letterhead') for this download, or the
      // saved commission layout when no per-print choice was passed.
      const cfg2 = tplChoice ? { ...cfg, commission_bill_template: tplChoice } : cfg;
      pdf = await require('./pdf/render-commission-html').generateCommissionBoSHtmlPDF(payloads, cfg2);
    } else {
      // 'pdfkit'/'classic' choice, or a saved Classic layout → legacy PDFKit.
      pdf = await generateCommissionBoSBatchPDF(payloads, cfg);
    }
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="CommissionBoS_Batch_${payloads.length}.pdf"`);
    res.send(pdf);
  } catch (e) {
    console.error('Commission BoS bulk PDF error:', e);
    res.status(500).json({ error: 'Commission BoS PDF generation failed: ' + e.message });
  }
});

app.delete('/api/bills/:id', requireDelete, (req, res) => {
  getDb().run('DELETE FROM bills WHERE id = ?', [req.params.id]);
  res.json({ success: true });
});

// Update bill (edit)
app.put('/api/bills/:id', requireInvoiceWrite, (req, res) => {
  const b = req.body;
  const fields = ['ano','date','state','br','crpt','bil','name','add_line','pla','pstate','st_code','crr','pan','qty','cost','igst','net'];
  const sets = []; const vals = [];
  for (const f of fields) {
    if (b[f] !== undefined) { sets.push(`${f}=?`); vals.push(b[f]); }
  }
  if (!sets.length) return res.status(400).json({ error: 'No fields to update' });
  vals.push(req.params.id);
  getDb().run(`UPDATE bills SET ${sets.join(',')} WHERE id=?`, vals);
  res.json({ success: true });
});

// ══════════════════════════════════════════════════════════════
// DEBIT NOTES (for discounts/adjustments)
// ══════════════════════════════════════════════════════════════
//
// Derive the dealer's effective sale type for a DN:
//   - Most-frequent `lots.sale` value across this dealer's lots in the
//     trade. 'I'/'E' → inter-state; 'L' or empty → local.
//   - Falls back to a GSTIN state-code vs company state-code comparison
//     when no lots in the trade carry a sale-type tag (e.g. legacy data
//     that pre-dates invoice generation).
// Returns one of 'I', 'E', 'L', or '' (no fallback was possible — caller
// should treat empty as local-by-default).

// Debit-note discount BASE for a seller, scoped to a single grade. The
// base is the sum of commission (`com`) + cash-handling (`sertax`) across
// the seller's lots of that grade in the auction. Debit Notes use grade
// '2' (registered dealers); Debit Notes — Planter use grade '1' (planter /
// agriculturist sellers). The seller is matched by name + auction_id (the
// same join buildRDPurchaseRows / buildURDPurchaseRows use), and grade is
// compared TRIM-insensitively since lot grades may carry stray whitespace.
function gradedServiceBase(db, auctionId, sellerName, grade) {
  if (!auctionId || !sellerName) return 0;
  const row = db.get(
    `SELECT COALESCE(SUM(COALESCE(com,0) + COALESCE(sertax,0)), 0) AS base
       FROM lots
      WHERE auction_id = ? AND name = ? AND TRIM(COALESCE(grade,'')) = ?`,
    [auctionId, sellerName, String(grade)]
  );
  return row ? Number(row.base) || 0 : 0;
}

// Sum of just the COMMISSION (lots.com) on a party's graded lots. This is
// the debit-note amount per the business rule "the debit note amount is the
// commission of the respective lots" — no handling (sertax), no discount
// multiplier. Kept separate from gradedServiceBase (com + sertax), which
// the planter debit-note flow still uses.
function gradedCommission(db, auctionId, sellerName, grade) {
  if (!auctionId || !sellerName) return 0;
  const row = db.get(
    `SELECT COALESCE(SUM(COALESCE(com,0)), 0) AS base
       FROM lots
      WHERE auction_id = ? AND name = ? AND TRIM(COALESCE(grade,'')) = ?`,
    [auctionId, sellerName, String(grade)]
  );
  return row ? Number(row.base) || 0 : 0;
}

function deriveDealerSaleType(db, auctionId, dealerName, dealerCr, cfg, purchase) {
  // For Debit Notes, inter/intra is determined by the DEALER'S state vs
  // the COMPANY'S state — NOT the buyer-facing sale type on lots
  // (lots.sale reflects the buyer's relationship to the company, which
  // is irrelevant when the company is issuing a credit back to the
  // dealer). Earlier code prioritised lots.sale and the company's
  // configured business_state, which gave the wrong answer when:
  //   - lots.sale was 'L' because the buyer happened to be in the
  //     company state, even though the seller (dealer) was elsewhere
  //   - tally_state_code was left at the default '33' for a company
  //     whose real GSTIN starts with '32' (Kerala)
  //
  // Resolution order — strictly GSTIN-based now:
  //   1. dealer GSTIN state code vs company GSTIN state code
  //   2. purchase row's own GST split (igst > 0 ⇒ inter), as a backup
  //      for legacy purchases whose dealer GSTIN was lost
  //   3. lots.sale dominant ('I'/'E'/'L'), last-resort
  function stateCodeFromCr(s) {
    let c = String(s || '').trim().toUpperCase();
    if (c.startsWith('GSTIN.')) c = c.slice(6);
    else if (c.startsWith('GSTIN')) c = c.slice(5);
    return /^\d{2}/.test(c) ? c.slice(0, 2) : '';
  }
  // Company state code — read from the actual configured GSTIN first
  // (canonical source), then fall back to tally_state_code, then to
  // business_state. Reading the GSTIN avoids the wrong-default problem
  // (tally_state_code defaults to 33 even on Kerala installs).
  const cfgObj = cfg || {};
  const bizState = String(cfgObj.business_state || '').toUpperCase();
  const companyGstinCandidates = bizState === 'KERALA'
    ? [cfgObj.kl_gstin, cfgObj.tn_gstin, cfgObj.gstin]
    : [cfgObj.tn_gstin, cfgObj.kl_gstin, cfgObj.gstin];
  let companyStateCode = '';
  for (const g of companyGstinCandidates) {
    const code = stateCodeFromCr(g);
    if (code) { companyStateCode = code; break; }
  }
  if (!companyStateCode) {
    companyStateCode = String(cfgObj.tally_state_code
      || (bizState === 'KERALA' ? '32' : '33'));
  }

  // 1) Dealer GSTIN vs company GSTIN — authoritative for DN.
  const dealerStateCode = stateCodeFromCr(dealerCr);
  if (dealerStateCode) {
    return dealerStateCode === companyStateCode ? 'L' : 'I';
  }

  // 2) Purchase row's GST split (covers the case where dealerCr is
  //    blank but the original purchase invoice was generated correctly).
  if (purchase) {
    if (Number(purchase.igst) > 0) return 'I';
    if (Number(purchase.cgst) > 0 || Number(purchase.sgst) > 0) return 'L';
  }

  // 3) Last resort — lots.sale dominant tag.
  if (auctionId && dealerName) {
    const rows = db.all(
      `SELECT UPPER(TRIM(COALESCE(sale,''))) AS s, COUNT(*) AS n
         FROM lots
        WHERE auction_id = ? AND name = ? AND amount > 0
        GROUP BY s
        ORDER BY n DESC, s
        LIMIT 1`,
      [auctionId, dealerName]
    );
    const dominant = rows.length ? String(rows[0].s || '').toUpperCase() : '';
    if (dominant === 'I' || dominant === 'E' || dominant === 'L') return dominant;
  }
  return '';
}

app.get('/api/debit-notes', requireView, (req, res) => {
  const { auction_id, ano, from, to, search } = req.query;
  const db = getDb();
  let where = 'WHERE 1=1'; const p = [];
  if (auction_id) { where += ' AND auction_id = ?'; p.push(parseInt(auction_id)); }
  if (ano) { where += ' AND ano = ?'; p.push(ano); }
  if (from && to) { where += ' AND date BETWEEN ? AND ?'; p.push(from, to); }
  const qstr = String(search || '').trim();
  if (qstr) {
    const like = `%${qstr}%`;
    const ors = ['CAST(note_no AS TEXT) LIKE ?', 'name LIKE ?', 'CAST(ano AS TEXT) LIKE ?'];
    p.push(like, like, like);
    // A dealer DN has no lot column of its own — it covers the dealer's whole
    // trade — so a lot spec resolves through that dealer's lots.
    const viaLots = smartLotSql('l.lot_no', smartLotNumbers(qstr));
    if (viaLots) {
      ors.push(`EXISTS (SELECT 1 FROM lots l
                         WHERE l.auction_id = COALESCE(
                                 debit_notes.auction_id,
                                 (SELECT a.id FROM auctions a WHERE a.ano = debit_notes.ano LIMIT 1))
                           AND UPPER(TRIM(COALESCE(l.name,''))) = UPPER(TRIM(COALESCE(debit_notes.name,'')))
                           AND ${viaLots.sql})`);
      p.push(...viaLots.params);
    }
    const phone = smartPhoneDigits(qstr);
    if (phone) {
      ors.push(`EXISTS (SELECT 1 FROM traders t
                         WHERE UPPER(TRIM(COALESCE(t.name,''))) = UPPER(TRIM(COALESCE(debit_notes.name,'')))
                           AND (${smartPhoneSql('t.tel')} LIKE ? OR ${smartPhoneSql('t.whatsapp')} LIKE ?))`);
      p.push(`%${phone}%`, `%${phone}%`);
    }
    where += ' AND (' + ors.join(' OR ') + ')';
  }
  const page     = Math.max(1, parseInt(req.query.page, 10) || 1);
  const pageSize = Math.min(500, Math.max(1, parseInt(req.query.pageSize, 10) || 50));
  const offset   = (page - 1) * pageSize;
  const wantPaged = req.query.page != null || req.query.pageSize != null;
  // Default order: note number ascending. `note_no` is TEXT holding a numeric
  // string (allocated via MAX(CAST(note_no AS INTEGER))), hence the CAST.
  const baseQuery = 'SELECT * FROM debit_notes ' + where + ' ORDER BY CAST(note_no AS INTEGER), note_no, date';
  if (wantPaged) {
    const total = db.get('SELECT COUNT(*) AS c FROM debit_notes ' + where, p).c;
    const rows = db.all(baseQuery + ' LIMIT ? OFFSET ?', [...p, pageSize, offset]);
    return res.json({ rows: withFmtDate(rows), total, page, pageSize });
  }
  res.json(withFmtDate(db.all(baseQuery + ' LIMIT 500', p)));
});

// Single-shot DN generation. Input: purchase invoice number + explicit
// discount + note number. Source is ALWAYS purchases — DNs against sales
// transactions are not allowed (they're a buyer-side instrument issued
// to suppliers). The legacy `saleType` parameter is accepted for
// compatibility with older clients but ignored — purchases don't carry
// sale type the way sales invoices do.
//
// Sibling endpoints:
//   /generate-bulk  — auto-derive discount from settings (one purchase)
//   /generate-all   — same logic over every purchase in the DB
// Generate a SINGLE debit note. Inputs (new contract):
//   - purchno : the purchase invoice number (lots up to one row in `purchases`)
//   - ano     : the trade number (REQUIRED — invoice must belong to it)
//
// Strict trade-membership check: the resolved purchase row's `ano` MUST
// equal the supplied `ano`. Cross-trade attempts get a clean 400 with
// the actual trade the invoice belongs to, so the user can self-correct
// without inspecting the DB.
//
// Discount + note number are server-derived (same rules as /generate-bulk):
//   discount = round( amount / 1000 × discount_days × discount_pct )
//              where amount = the purchase taxable value (Payable), and
//              discount_days / discount_pct come from Settings → Rates.
//              discount_days = 0 (or discount_pct = 0) → no discount.
//   note_no  = MAX(note_no) + 1
//
// Legacy callers still passing `{ discount, noteNo }` are accepted —
// explicit values override the derivation. `saleType` is accepted and
// ignored (kept for back-compat with very old API consumers).
//
// Feature flag: DN generation is gated by `flag_debit_note`. When OFF,
// every write path returns 403 (read paths stay open so existing rows
// remain visible if the flag is later toggled off).
function requireDebitNoteEnabled(req, res, next) {
  const cfg = getSettingsFlat(getDb());
  const on = String(cfg.flag_debit_note || '').toLowerCase() === 'true';
  if (!on) return res.status(403).json({ error: 'Debit Note feature is disabled — enable "flag_debit_note" in Settings → Flags' });
  next();
}
app.post('/api/debit-notes/generate', requireInvoiceWrite, requireDebitNoteEnabled, (req, res) => {
  const db = getDb();
  const cfg = getSettingsFlat(db);
  const purchno = String(req.body.purchno || req.body.invoiceNo || '').trim();
  const ano     = String(req.body.ano || '').trim();

  if (!purchno) return res.status(400).json({ error: 'purchno (purchase invoice number) is required' });
  if (!ano)     return res.status(400).json({ error: 'ano (trade number) is required' });

  // Price-check gate: resolve auction by ano (debit notes don't carry
  // the numeric id directly), then refuse if its lots haven't been
  // verified yet. Same 412 contract as the URL-bound gates so the
  // client can show a uniform "Run price check first" message.
  // Short-circuit when the feature flag is OFF — keeps debit notes
  // generation usable on installs that don't run price check.
  if (pcFlagOn(db)) {
    const gateAuction = db.get('SELECT id, price_checked_at FROM auctions WHERE ano = ? ORDER BY date DESC LIMIT 1', [ano]);
    if (gateAuction && !gateAuction.price_checked_at) {
      return res.status(412).json({
        error: 'Price check required',
        detail: 'Run Reports → Price Check against the auction (and apply any code fixes) before generating debit notes.',
        auctionId: gateAuction.id,
        gate: 'price_check',
      });
    }
  }

  // Look up the purchase. We find ALL rows with this purchno (in case of
  // legacy duplicates across trades) and pick the one that matches the
  // selected trade. Earlier code took the most-recent and silently
  // generated against whatever trade it landed on — that broke the
  // strict trade-scoping requirement.
  const candidates = db.all(
    `SELECT * FROM purchases WHERE invo = ? ORDER BY date DESC, id DESC`,
    [purchno]
  );
  if (!candidates.length) {
    // Distinguish "is a sales invoice" from "doesn't exist" for cleaner UX.
    const isSalesInv = db.get(
      `SELECT id FROM invoices WHERE invo = ? AND COALESCE(is_proforma,0) = 0 LIMIT 1`,
      [purchno]
    );
    if (isSalesInv) {
      return res.status(400).json({
        error: `${purchno} is a SALES invoice. Debit notes can only be generated against PURCHASE invoices.`
      });
    }
    return res.status(404).json({ error: `Purchase invoice ${purchno} not found` });
  }

  // Trade-membership filter — the invoice MUST belong to the requested
  // trade. If only mismatching candidates exist, surface the actual
  // ano(s) so the user knows which trade to switch to.
  const purchase = candidates.find(p => String(p.ano) === ano);
  if (!purchase) {
    const otherAnos = [...new Set(candidates.map(p => String(p.ano)))].join(', ');
    return res.status(400).json({
      error: `Purchase invoice ${purchno} does not belong to trade #${ano}. ` +
             `It belongs to trade #${otherAnos}.`
    });
  }

  // Idempotency: skip if a DN for (ano, dealer) already exists.
  const dealerName = purchase.name || '';
  const dupe = db.get(
    `SELECT id, note_no FROM debit_notes WHERE ano = ? AND name = ? LIMIT 1`,
    [ano, dealerName]
  );
  if (dupe) {
    return res.status(409).json({
      error: `Debit note #${dupe.note_no} already exists for ${dealerName} in trade #${ano}`,
      existingId: dupe.id,
      existingNoteNo: dupe.note_no,
    });
  }

  // ── DN amount (GRADE 2) ──────────────────────────────────
  //   Amount = the COMMISSION of the dealer's GRADE-2 lots in this trade
  //   (sum of lots.com). No handling, no discount multiplier — per the
  //   business rule "the debit note amount is the commission of the
  //   respective lots". A caller may still override via req.body.amount
  //   (legacy `discount` is also honoured). GST is added on top below.
  let discountAmt = req.body.amount != null ? parseFloat(req.body.amount)
                  : req.body.discount != null ? parseFloat(req.body.discount) : NaN;
  if (!Number.isFinite(discountAmt) || discountAmt <= 0) {
    discountAmt = gradedCommission(db, purchase.auction_id, dealerName, '2');
  }
  if (discountAmt <= 0) {
    return res.status(400).json({ error: `No commission found for ${dealerName} in trade #${ano} — nothing to debit` });
  }

  // GST split — driven by the dealer's SALE TYPE for this trade.
  //   'I' / 'E' (Inter-state / Export) → IGST
  //   'L' or empty (Local)             → CGST + SGST (50/50 split)
  // Resolution order:
  //   1. dealer's lot.sale (when tagged after invoice generation)
  //   2. purchase's GST split (igst > 0 ⇒ inter)
  //   3. dealer GSTIN state-code vs company state-code
  const dealerSaleType = deriveDealerSaleType(
    db, purchase.auction_id, dealerName, purchase.cr, cfg, purchase
  );
  const isInter = dealerSaleType === 'I' || dealerSaleType === 'E';

  const dnGstRate = Number(cfg.discount_gst) || Number(cfg.gst_service) || 18;
  // GST is always emitted on a registered DN — the DN is a service-type
  // credit and uses the configured discount GST rate regardless of the
  // source purchase's own split. Earlier code skipped GST when the
  // source purchase had no GST, which left DNs against URD purchases
  // with zero tax — but URDs don't get DNs in this build (they get
  // bills of supply), so the guard was a no-op that occasionally masked
  // GST on legitimate registered-dealer DNs.
  let cgst = 0, sgst = 0, igst = 0;
  if (isInter) {
    igst = Math.round(discountAmt * dnGstRate / 100 * 100) / 100;
  } else {
    const half = Math.round(discountAmt * (dnGstRate / 2) / 100 * 100) / 100;
    cgst = half; sgst = half;
  }
  const total = Math.round((discountAmt + cgst + sgst + igst) * 100) / 100;

  // DN date = trade.date (same day as the auction / bill of supply)
  const trade = db.get('SELECT date FROM auctions WHERE ano = ? LIMIT 1', [ano]);
  const dnDate = trade && trade.date
    ? normalizeDate(trade.date)
    : new Date().toISOString().slice(0, 10);

  // Note number: client-supplied `startNoteNo` (preferred) or legacy
  // `noteNo` (back-compat). When neither is provided, fall back to
  // MAX(note_no)+1. The user-supplied value is validated as a positive
  // integer and checked for uniqueness against debit_notes — a clean
  // 409 is returned if the number is already taken so the user can pick
  // a different start.
  //
  // TRADE-WISE numbering: every uniqueness/MAX check is scoped to the
  // current trade `ano`. Each trade has its own independent 1..N
  // sequence — DN #5 in trade 7 is unrelated to DN #5 in trade 8.
  const rawStart = req.body.startNoteNo != null ? req.body.startNoteNo : req.body.noteNo;
  let noteNo;
  if (rawStart != null && String(rawStart).trim() !== '') {
    const n = parseInt(String(rawStart).trim(), 10);
    if (!Number.isFinite(n) || n < 1) {
      return res.status(400).json({ error: 'Starting Number must be a positive integer' });
    }
    noteNo = String(n);
    // Uniqueness check — scoped to the SELECTED TRADE only. Note_no is
    // stored as TEXT but we compare as integer to handle rare cases
    // where one side has leading zeroes.
    const taken = db.get(
      `SELECT id FROM debit_notes WHERE ano = ? AND CAST(note_no AS INTEGER) = ? LIMIT 1`,
      [ano, n]
    );
    if (taken) {
      return res.status(409).json({
        error: `Debit note #${n} is already used in trade #${ano}. Choose a different number.`,
        suggested: (() => {
          const row = db.get(
            'SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes WHERE ano = ?',
            [ano]
          );
          const mx = parseInt(row && row.mx, 10);
          return Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
        })(),
      });
    }
  } else {
    // No explicit start → bump the trade's own MAX.
    const row = db.get(
      'SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes WHERE ano = ?',
      [ano]
    );
    const mx = parseInt(row && row.mx, 10);
    noteNo = String(Number.isFinite(mx) && mx > 0 ? mx + 1 : 1);
  }

  db.run(
    `INSERT INTO debit_notes (ano,date,state,name,note_no,amount,cgst,sgst,igst,total,trader_id)
     VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
    [ano, dnDate, purchase.state || '', dealerName,
     noteNo, discountAmt, cgst, sgst, igst, total,
     // Seller FK inherited from the purchase invoice this DN is raised against.
     purchase.trader_id || null]
  );

  res.json({
    success: true,
    created: 1,
    note_no: noteNo,
    purchno,
    ano,
    dealer: dealerName,
    amount: discountAmt,
    cgst, sgst, igst, total,
  });
});

// Bulk DN generation — single input: purchase invoice number. Finds the
// trade (`ano`) that purchase belongs to, then generates one DN per
// sales invoice in that trade. Idempotent: invoices that already have a
// DN matching their (ano, name) are skipped.
//
// Discount is auto-derived from settings:
//   discount_pct × invoice qty × purchase rate
// (mirrors the per-lot discount calculation in calculations.js — keeps
// the bulk DN consistent with what a user would have manually entered).
// Trade-wise DN generation. Input: a trade number (`ano`). The endpoint
// finds EVERY purchase invoice in that trade and creates one DN per
// purchase (one DN per registered dealer in that auction). Mirrors the
// natural data model:
//   - A trade is the unit of business activity (one auction day)
//   - Purchases roll up per-dealer for that trade
//   - Discount adjustments are negotiated trade-wide (per-day basis)
//   - DN date = trade.date (same day as the auction / bill of supply)
//
// Backwards compatibility: legacy callers passing `{ purchno }` (single
// purchase invoice number) still work — we look up the purchase, derive
// its trade `ano`, and treat it as a trade-wide generation. This way
// older UI builds aren't broken if they're still in browser caches.
//
// Per-DN math:
//   discount  = round( amount / 1000 × discount_days × discount_pct )
//               amount = the purchase taxable value (Payable); days/pct from
//               Settings → Rates. discount_days = 0 → no discount (skipped).
//   GST split = mirrors source purchase (intra → CGST+SGST, inter → IGST)
//   GST rate  = cfg.discount_gst (typically 18%) — DN is a service charge
//
// Idempotency: skip per (ano, dealer name) pair already DN'd. Returns
// { created, skipped, skippedDetails[], generated[] }.
app.post('/api/debit-notes/generate-bulk', requireInvoiceWrite, requireDebitNoteEnabled, (req, res) => {
  const db = getDb();
  const cfg = getSettingsFlat(db);

  // Resolve trade number (`ano`). Two input shapes:
  //   1. `{ ano }`     — preferred, trade-wise (new UI)
  //   2. `{ purchno }` — legacy, derive ano from the single purchase
  let ano = String(req.body.ano || '').trim();
  if (!ano) {
    const purchno = String(req.body.purchno || '').trim();
    if (!purchno) {
      return res.status(400).json({ error: 'Trade number (ano) is required' });
    }
    const p = db.get(
      `SELECT ano FROM purchases WHERE invo = ? ORDER BY date DESC, id DESC LIMIT 1`,
      [purchno]
    );
    if (!p) return res.status(404).json({ error: `Purchase invoice ${purchno} not found` });
    ano = String(p.ano || '').trim();
    if (!ano) return res.status(400).json({ error: 'Purchase row has no trade number' });
  }

  // Price-check gate — only when the feature is enabled.
  if (pcFlagOn(db)) {
    const ga = db.get('SELECT id, price_checked_at FROM auctions WHERE ano = ? ORDER BY date DESC LIMIT 1', [ano]);
    if (ga && !ga.price_checked_at) {
      return res.status(412).json({
        error: 'Price check required',
        detail: 'Run Reports → Price Check against the auction (and apply any code fixes) before generating debit notes.',
        auctionId: ga.id,
        gate: 'price_check',
      });
    }
  }

  // Pull every purchase row for this trade. Each becomes one DN unless
  // already DN'd. Ordered by party name (case-insensitively) rather than
  // insertion id, because note numbers are assigned in this order — so the
  // DN series runs alphabetically, matching the purchase invoices it derives
  // from. `id` only breaks ties between two rows sharing a name.
  const purchases = db.all(
    `SELECT * FROM purchases WHERE ano = ? ORDER BY UPPER(TRIM(COALESCE(name,''))), id`,
    [ano]
  );
  if (!purchases.length) {
    return res.json({
      success: true, created: 0, skipped: 0, generated: [], skippedDetails: [],
      note: `No purchase invoices in trade #${ano}`,
    });
  }

  // Pre-load existing DN keys for this trade (single query — cheap).
  const existingKeys = new Set(
    db.all(
      `SELECT name FROM debit_notes WHERE ano = ?`,
      [ano]
    ).map(r => r.name || '')
  );

  // Resolve DN date once per trade — saves a query per purchase.
  // DN date = trade.date (same day as the auction / bill of supply).
  const trade = db.get('SELECT date FROM auctions WHERE ano = ? LIMIT 1', [ano]);
  const dnDate = trade && trade.date
    ? normalizeDate(trade.date)
    : new Date().toISOString().slice(0, 10);

  // DN (discount) math — read once, applied per-purchase below:
  //   Base     = sum(commission + handling) on the dealer's GRADE-2 lots.
  //   Discount = round( Base / 1000 × discount_days × discount_pct ),
  //   days/pct from Settings → Rates. discount_days = 0 → 0 (skipped).
  //   GST on the DN uses cfg.discount_gst (typically 18%).
  const dnGstRate     = Number(cfg.discount_gst) || Number(cfg.gst_service) || 0;
  const discDays      = Number(cfg.discount_days) || 0;
  const discPct       = Number(cfg.discount_pct)  || 0;

  // Resolve next note number. The user can supply `startNoteNo` to
  // explicitly anchor the sequence (each generated DN gets startNoteNo,
  // startNoteNo+1, +2, ...). When omitted, fall back to MAX+1.
  //
  // Concurrency: SQLite (sql.js / better-sqlite3) serializes writes, so
  // there's no within-request race. The only real risk is two SEPARATE
  // bulk requests overlapping their ranges. We mitigate that by claiming
  // the range up-front: count eligible purchases, then verify no number
  // in [start, start+eligibleCount) is already in `debit_notes`. If a
  // collision exists → 409 with the next safe start so the user can
  // retry. The check + INSERTs all run inside the same JS turn (no
  // await), so a competing bulk can't slip in between.
  const eligibleCount = purchases.filter(
    p => !existingKeys.has(p.name || '') && gradedCommission(db, p.auction_id, p.name || '', '2') > 0
  ).length;

  let nextNoteNo;
  const rawStart = req.body.startNoteNo != null ? req.body.startNoteNo : req.body.startInvoiceNo;
  if (rawStart != null && String(rawStart).trim() !== '') {
    const n = parseInt(String(rawStart).trim(), 10);
    if (!Number.isFinite(n) || n < 1) {
      return res.status(400).json({ error: 'Starting Number must be a positive integer' });
    }
    nextNoteNo = n;
    if (eligibleCount > 0) {
      // Range claim — scoped to THIS TRADE only. Numbering is per-trade
      // (trade #1's #5 doesn't conflict with trade #2's #5), so collision
      // check has `WHERE ano = ?`. Without this filter, starting trade 2
      // at #1 would falsely fail when trade 1 already has #1..N.
      const upper = nextNoteNo + eligibleCount - 1;
      const collisions = db.all(
        `SELECT CAST(note_no AS INTEGER) AS n
           FROM debit_notes
          WHERE ano = ?
            AND CAST(note_no AS INTEGER) BETWEEN ? AND ?
          ORDER BY n`,
        [ano, nextNoteNo, upper]
      );
      if (collisions.length) {
        const safe = (() => {
          const row = db.get(
            'SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes WHERE ano = ?',
            [ano]
          );
          const mx = parseInt(row && row.mx, 10);
          return Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
        })();
        return res.status(409).json({
          error: `Starting Number ${nextNoteNo} would overlap existing debit note(s) in trade #${ano} ` +
                 `(${collisions.slice(0, 5).map(c => '#' + c.n).join(', ')}` +
                 `${collisions.length > 5 ? `, +${collisions.length - 5} more` : ''}). ` +
                 `Try ${safe} or higher.`,
          collisions: collisions.map(c => c.n),
          suggested: safe,
        });
      }
    }
  } else {
    // No explicit start → bump THIS TRADE's MAX. Each trade has its
    // own independent sequence.
    const row = db.get(
      'SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes WHERE ano = ?',
      [ano]
    );
    const mx = parseInt(row && row.mx, 10);
    nextNoteNo = Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
  }

  const generated = [];
  const skipped   = [];

  for (const p of purchases) {
    const dealerName = p.name || '';
    if (existingKeys.has(dealerName)) {
      skipped.push({
        invo: p.invo, ano, buyer: dealerName,
        reason: 'duplicate (DN already exists for this dealer in this trade)',
      });
      continue;
    }
    // Amount = the COMMISSION of the dealer's GRADE-2 lots (sum of lots.com).
    // No handling, no discount multiplier — per the business rule that the
    // debit note amount is the commission of the respective lots.
    const discountAmt = gradedCommission(db, p.auction_id, dealerName, '2');
    if (discountAmt <= 0) {
      skipped.push({ invo: p.invo, ano, buyer: dealerName, reason: 'no commission on grade-2 lots' });
      continue;
    }

    // Intra/inter classification — sale-type driven:
    //   'I' / 'E' (Inter-state / Export) → IGST
    //   'L' or empty (Local)             → CGST + SGST
    // Resolution order:
    //   1. dealer's lot.sale (when tagged after invoice generation)
    //   2. purchase's GST split (igst > 0 ⇒ inter)
    //   3. dealer GSTIN state-code vs company state-code
    const dealerSaleType = deriveDealerSaleType(db, p.auction_id, dealerName, p.cr, cfg, p);
    const isInter = dealerSaleType === 'I' || dealerSaleType === 'E';

    // GST is always emitted on a registered DN at the configured discount
    // rate (typically 18%); URD/agri sellers don't get DNs in this build,
    // they get Bills of Supply instead.
    let cgst = 0, sgst = 0, igst = 0;
    if (isInter) {
      igst = Math.round(discountAmt * dnGstRate / 100 * 100) / 100;
    } else {
      const half = Math.round(discountAmt * (dnGstRate / 2) / 100 * 100) / 100;
      cgst = half; sgst = half;
    }
    const total = Math.round((discountAmt + cgst + sgst + igst) * 100) / 100;

    db.run(
      `INSERT INTO debit_notes (ano,date,state,name,note_no,amount,cgst,sgst,igst,total,trader_id)
       VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
      [ano, dnDate, p.state || '', dealerName,
       String(nextNoteNo), discountAmt, cgst, sgst, igst, total,
       p.trader_id || null]
    );
    generated.push({ note_no: nextNoteNo, purchno: p.invo, dealer: dealerName, total });
    existingKeys.add(dealerName); // prevent same-loop duplicates
    nextNoteNo++;
  }

  res.json({
    success: true,
    created: generated.length,
    skipped: skipped.length,
    generated,
    skippedDetails: skipped,
    note: generated.length === 0 && skipped.length === 0
      ? `No eligible purchases in trade #${ano}`
      : undefined,
  });
});

// List purchases in a trade that don't yet have a DN. Used by the
// front-end preview in the Generate Debit Notes modal so the user can
// see exactly what will be created before they click Generate.
//
// Resolves `auctionId` (FK) → `ano` (trade number string) since DNs
// store ano, not the auction id.
app.get('/api/debit-notes/eligible-purchases/:auctionId', requireView, (req, res) => {
  const db = getDb();
  const auction = db.get('SELECT ano FROM auctions WHERE id = ?', [req.params.auctionId]);
  if (!auction) return res.status(404).json({ error: 'Auction not found' });

  const ano = auction.ano;
  // Anti-join: purchases in this trade where no DN exists for the same
  // (ano, dealer name) pair, AND the dealer has GRADE-2 commission to debit.
  // `amount` here is the DN AMOUNT = the COMMISSION (sum of lots.com) on the
  // dealer's grade-2 lots — same figure the generate endpoints now store, so
  // the modal preview matches what gets created (GST is added on top there).
  const rows = db.all(
    `SELECT p.id, p.invo, p.name,
            (SELECT COALESCE(SUM(COALESCE(l.com,0)), 0)
               FROM lots l
              WHERE l.auction_id = p.auction_id AND l.name = p.name
                AND TRIM(COALESCE(l.grade,'')) = '2') AS amount,
            p.cgst, p.sgst, p.igst, p.total, p.date, p.state
       FROM purchases p
      WHERE p.ano = ?
        AND EXISTS (
          SELECT 1 FROM lots l2
           WHERE l2.auction_id = p.auction_id AND l2.name = p.name
             AND TRIM(COALESCE(l2.grade,'')) = '2'
             AND COALESCE(l2.com,0) > 0
        )
        AND NOT EXISTS (
          SELECT 1 FROM debit_notes dn
           WHERE dn.ano = p.ano AND dn.name = p.name
        )
      ORDER BY p.id`,
    [ano]
  );
  res.json(rows);
});

// Return the next-available debit note number for a given trade.
// Numbering is TRADE-WISE: each trade has its own 1..N sequence.
// `ano` (trade number) is required — without it we can't know which
// trade's max to bump. The UI passes the currently-selected trade.
//
// Trade-wise reason: business reality + user expectation.
//   Trade 1 has DN #1..17 → starting trade 2 at #1 must work.
//   Earlier code did `MAX(note_no) FROM debit_notes` (global), so a
//   user entering #1 for trade 2 hit the "already in use" check
//   because trade 1 owned that number. The fix is to scope every
//   uniqueness check (single, range, MAX) to `WHERE ano = ?`.
app.get('/api/debit-notes/next-note-no', requireView, (req, res) => {
  const db = getDb();
  const ano = String(req.query.ano || '').trim();
  if (!ano) {
    return res.status(400).json({ error: 'ano (trade number) is required for trade-wise numbering' });
  }
  const row = db.get(
    'SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes WHERE ano = ?',
    [ano]
  );
  const mx = parseInt(row && row.mx, 10);
  const next = Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
  res.json({ next, ano });
});

// /api/debit-notes/generate-all — DEPRECATED.
//
// This endpoint previously generated DNs across EVERY trade in a single
// sweep. The new spec (Generate Debit Note + Generate All) explicitly
// forbids cross-trade or global generation: every action must be scoped
// to one trade selected via the dn-auction dropdown.
//
// Hard-disabled with 410 Gone so any orphan client (older browser tab,
// scripted consumer) gets a clear migration message instead of silently
// creating cross-trade data.
app.post('/api/debit-notes/generate-all', requireInvoiceWrite, requireDebitNoteEnabled, (req, res) => {
  res.status(410).json({
    error: 'Cross-trade DN generation is no longer supported. Use POST /api/debit-notes/generate-bulk with { ano } to generate DNs for a specific trade.',
  });
});

app.delete('/api/debit-notes/:id', requireDelete, (req, res) => {
  const db = getDb();
  if (!isAdmin(req) && lotsLockedForDebitNote(db, req.params.id)) {
    return res.status(423).json({ error: 'This debit note is locked because at least one of its lots is locked — only an admin can delete it.' });
  }
  db.run('DELETE FROM debit_notes WHERE id = ?', [req.params.id]);
  res.json({ success: true });
});

// Update debit note (edit)
app.put('/api/debit-notes/:id', requireInvoiceWrite, (req, res) => {
  const n = req.body;
  const db = getDb();
  if (!isAdmin(req) && lotsLockedForDebitNote(db, req.params.id)) {
    return res.status(423).json({ error: 'This debit note is locked because at least one of its lots is locked — only an admin can edit it.' });
  }
  const fields = ['ano','date','state','name','note_no','amount','cgst','sgst','igst','total'];
  const sets = []; const vals = [];
  for (const f of fields) {
    if (n[f] !== undefined) { sets.push(`${f}=?`); vals.push(n[f]); }
  }
  if (!sets.length) return res.status(400).json({ error: 'No fields to update' });
  vals.push(req.params.id);
  db.run(`UPDATE debit_notes SET ${sets.join(',')} WHERE id=?`, vals);
  res.json({ success: true });
});

// Render a Debit Note PDF for printing. Slim by design — DN is a single-
// row instrument (one note number, one amount block, one party). We keep
// the visual style consistent with the sales invoice (same header band,
// same value-table conventions) without pulling in the full multi-page
// invoice-pdf machinery.
// Render one debit note onto an existing PDFDocument page. Extracted from
// the single-DN endpoint so the bulk endpoint can render N debit notes
// into one merged document (page-break per DN).
// `opts.planter` marks a debit_notes_planter row — same layout, but the note
// number picks up the planter prefix/suffix settings instead of the dealer pair.
function _renderDebitNote(doc, dn, db, cfg, opts) {
    opts = opts || {};
    // The DN layout (per the reference PDF) is BUYER-LETTERHEAD style:
    // the BUYER (the party benefiting from the discount, who issues the
    // credit/debit note in their books) prints on top with their address
    // + GSTIN, then "CREDIT NOTE/DEBIT NOTE" banner, then ISP company
    // appears as the recipient block in the middle.
    //
    // IMPORTANT: a Debit Note is a PURCHASE-side instrument issued by US
    // (the buyer) TO our supplier (the dealer). So `dn.name` stores the
    // DEALER name (the seller from `purchases.name`), not a buyer code.
    // This was the source of the qty/rate/value=0 bug: an earlier query
    // joined to `lots` by buyer1/buyer (matching nobody, since the DN
    // owner is on the SELLER side), so every row fell through to the
    // synthetic zero-value placeholder.
    const dealerName = String(dn.name || '').trim();
    // Look up the dealer's record (used for letterhead address/GSTIN).
    // Dealers live in `traders`, not `buyers` — buyers are the trade-
    // winners (our customers), traders are our suppliers. Match by
    // exact name with a UPPER() guard for case differences.
    const buyer = dealerName
      ? db.get(`SELECT * FROM traders WHERE UPPER(name) = UPPER(?) LIMIT 1`, [dealerName])
      : null;

    // Pull the per-lot line items from this trade for THIS dealer. The
    // DN's discount is allocated proportionally to puramt across the
    // dealer's lots (so the per-lot Discount column sums back to the
    // DN total). Match on `lots.name` (seller) — same column the
    // purchase invoice uses.
    const auction = db.get('SELECT * FROM auctions WHERE ano = ? LIMIT 1', [dn.ano]);
    let lots = [];
    if (auction) {
      lots = db.all(
        `SELECT lot_no, qty, prate, puramt, pqty
           FROM lots
          WHERE auction_id = ?
            AND UPPER(COALESCE(name,'')) = UPPER(?)
            AND amount > 0
          ORDER BY CAST(lot_no AS INTEGER), lot_no`,
        [auction.id, dealerName]
      );
    }

    // Distribute the DN amount across lots proportionally to puramt so
    // the per-lot Discount column sums back to the DN total. If lots
    // is empty (rare — orphan DN), we render a single synthetic row.
    const totalPuramt = lots.reduce((s, l) => s + Number(l.puramt || 0), 0);
    const dnAmount    = Number(dn.amount || 0);
    if (lots.length && totalPuramt > 0) {
      let allocated = 0;
      lots = lots.map((l, idx) => {
        const isLast = idx === lots.length - 1;
        const share = isLast
          ? Math.round((dnAmount - allocated) * 100) / 100
          : Math.round((dnAmount * Number(l.puramt) / totalPuramt) * 100) / 100;
        allocated += share;
        return { ...l, discount: share, taxable: share };
      });
    } else {
      lots = [{ lot_no: '—', qty: 0, prate: 0, puramt: 0, discount: dnAmount, taxable: dnAmount }];
    }

    // Amount-in-words uses the shared paise-aware amountToWords() helper
    // (imported at the top of this file) so the GRAND TOTAL reads e.g.
    // "Rupees … and Seven Paise Only" exactly like the reference.

    const fmtAmt = (n) => Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const fmtQty = (n) => Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
    const fmtDate = (d) => {
      if (!d) return '';
      const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})/);
      return m ? `${m[3]}/${m[2]}/${m[1]}` : String(d);
    };

    // ── Render: Commission Tax Invoice (matches the reference PDF) ──
    // Issued on OUR company letterhead; the debit-note counterparty (the
    // dealer in `traders`) is the Receiver. Totals come from the stored
    // `debit_notes` record; the per-lot Commission column is the
    // proportional allocation of dn.amount computed above.
    const PAGE_L = 30, PAGE_R = 565, PAGE_W = PAGE_R - PAGE_L; // ≈535pt usable

    // Robust date formatter — handles ISO (yyyy-mm-dd) AND the stored
    // "16-Aug-25" style so both the receiver Date and the auction Dated
    // line read DD/MM/YYYY like the reference.
    const _MON = { jan:'01',feb:'02',mar:'03',apr:'04',may:'05',jun:'06',jul:'07',aug:'08',sep:'09',oct:'10',nov:'11',dec:'12' };
    const fmtDate2 = (d) => {
      if (!d) return '';
      const s = String(d);
      let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
      if (m) return `${m[3]}/${m[2]}/${m[1]}`;
      m = s.match(/^(\d{1,2})[-\/]([A-Za-z]{3})[A-Za-z]*[-\/](\d{2,4})/);
      if (m) {
        const mm = _MON[m[2].toLowerCase()] || m[2];
        const yyyy = m[3].length === 2 ? '20' + m[3] : m[3];
        return `${String(m[1]).padStart(2,'0')}/${mm}/${yyyy}`;
      }
      return s;
    };

    // Issuing company (OUR letterhead) — state-aware resolver shared with
    // the Commission BoS / Agri Bill generators (resolves the KL/TN
    // address, phone, email, GSTIN, SBL block correctly).
    const co = effectiveCompany(cfg);

    // Top-right ORIGINAL/DUPLICATE/TRIPLICATE strip
    doc.font('Helvetica').fontSize(8).fillColor('#000').text('ORIGINAL/DUPLICATE/TRIPLICATE', PAGE_L, 30, { width: PAGE_W, align: 'right' });

    // ── Company letterhead (centered) ──
    let y = 44;
    doc.font('Helvetica-Bold').fontSize(13).text((co.name || '').toUpperCase(), PAGE_L, y, { width: PAGE_W, align: 'center', lineBreak: false });
    y = doc.y + 1;
    doc.font('Helvetica').fontSize(8);
    // REGD OFFICE line: address1 + address2 + STATE CODE + Ph. Detect and
    // avoid double-printing a "REGD OFFICE:" prefix / "STATE CODE:" that
    // the user may already have baked into their address fields.
    const addrJoined = [co.address1 || '', co.address2 || ''].filter(p => p && String(p).trim()).join(' ');
    const stateCodeInAddr = co.stateName && new RegExp(co.stateName + '\\s*CODE\\s*:', 'i').test(addrJoined);
    const stateTail = (co.stateName && !stateCodeInAddr) ? (co.stateName + ' CODE:' + (co.stateCode || '')) : '';
    const phoneTail = co.phone ? 'Ph:' + co.phone : '';
    const regdBody = [addrJoined, stateTail, phoneTail].filter(Boolean).join(' ');
    if (regdBody) {
      const hasPrefix = /^\s*REGD\s+OFFICE\s*:/i.test(addrJoined);
      doc.text(hasPrefix ? regdBody : ('REGD OFFICE:' + regdBody), PAGE_L, y, { width: PAGE_W, align: 'center', lineBreak: false });
      y = doc.y;
    }
    const coIdLabel = co.idLabel || 'CIN';
    const coIdValue = (co.idValue != null && co.idValue !== '') ? co.idValue : (co.cin || cfg.cin || '');
    doc.text(`${coIdLabel}:${coIdValue || ''}   PAN:${co.pan || cfg.pan || ''}`, PAGE_L, y, { width: PAGE_W, align: 'center', lineBreak: false }); y = doc.y;
    // FSSAI | GSTIN | SBL on one line (FSSAI only when configured) — matches
    // the Letterhead reference debit-note format.
    const _fssai = String(co.fssai || cfg.fssai || '').trim();
    doc.text(`${_fssai ? 'FSSAI:' + _fssai + '   ' : ''}GSTIN:${co.gstin || ''}   SBL:${co.sbl || cfg.sbl || ''}`, PAGE_L, y, { width: PAGE_W, align: 'center', lineBreak: false }); y = doc.y;
    if (co.email) { doc.text('e-Mail ID:' + co.email, PAGE_L, y, { width: PAGE_W, align: 'center', lineBreak: false }); y = doc.y; }
    y += 5;

    // Outer frame starts here
    const FRAME_TOP = y;
    doc.lineWidth(0.7).moveTo(PAGE_L, FRAME_TOP).lineTo(PAGE_R, FRAME_TOP).stroke();
    doc.lineWidth(0.5);
    y += 4;

    // ── Title band: "Tax Invoice" ──
    doc.font('Helvetica-Bold').fontSize(11).text('Tax Invoice', PAGE_L, y, { width: PAGE_W, align: 'center' });
    y = doc.y + 4;
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke(); y += 5;

    // ── Receiver block (the debit-note counterparty / dealer) ──
    doc.font('Helvetica-Bold').fontSize(9).text('Name and Address of the Receiver', PAGE_L + 4, y);
    const recvTop = doc.y + 2;
    const rcv = buyer || {};
    const rcvGstinClean = String(rcv.cr || '').trim().replace(/^GSTIN\.?/i, '').trim();
    const rcvSbl    = String(rcv.aadhar || '').trim();   // SBL is stored in traders.aadhar
    const rcvState  = String(rcv.pstate || dn.state || '').trim();
    const rcvCode   = String(rcv.pst_code || '').trim();
    const natureOfService = cfg.commission_nature || 'Service of an Auctioneer/Commission Agent';
    const sac             = cfg.commission_sac    || '996111';
    const noteSeason = (cfg.season_short || cfg.tally_season || '26-27');

    const recvLines = [];
    recvLines.push('M/s.' + dealerName);
    if (rcv.padd) recvLines.push(String(rcv.padd));
    const placeLine = [rcv.ppla, rcv.pin].filter(s => s && String(s).trim()).join(' ');
    if (placeLine) recvLines.push(placeLine);
    if (rcvGstinClean) recvLines.push('GSTIN.' + rcvGstinClean + (rcvSbl ? '    SBL:' + rcvSbl : ''));
    else if (rcvSbl)   recvLines.push('SBL:' + rcvSbl);
    if (rcvState || rcvCode) recvLines.push('Place of Supply:' + (rcvCode ? rcvCode + ' ' : '') + rcvState.toUpperCase());
    recvLines.push('Nature of Service: ' + natureOfService);
    recvLines.push('Service Account Code: ' + sac);

    const RIGHT_X = PAGE_R - 200, RIGHT_W = 196, LEFT_W = PAGE_W - 200 - 12;
    doc.font('Helvetica').fontSize(9);
    let ry = recvTop;
    for (const line of recvLines) {
      doc.text(line, PAGE_L + 4, ry, { width: LEFT_W, lineBreak: false, ellipsis: true });
      ry += 11;
    }
    // Right column: No. + Date (aligned with the first two receiver lines)
    doc.font('Helvetica-Bold').fontSize(9);
    const _dnRawNo = dn.note_no ? String(dn.note_no).trim() : '';
    doc.text(`No.:${formatDebitNoteNo(cfg, _dnRawNo, {
      planter: !!opts.planter, ano: dn.ano, legacy: `${_dnRawNo}/${noteSeason}`,
    })}`, RIGHT_X, recvTop, { width: RIGHT_W, align: 'right' });
    doc.text(`Date :${fmtDate2(dn.date)}`, RIGHT_X, recvTop + 11, { width: RIGHT_W, align: 'right' });

    y = ry + 2;
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke(); y += 5;

    // ── Middle band: commission context ──
    doc.font('Helvetica-Bold').fontSize(10).text(
      `Commission on sale of cardamom in eAuction No: ${dn.ano || ''}    Dated:${fmtDate2(auction && auction.date)}`,
      PAGE_L, y, { width: PAGE_W, align: 'center' });
    y = doc.y + 4;
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke(); y += 4;

    // ── Line-item table (8 cols, incl. an empty spacer per the reference) ──
    const cols = [
      { key:'sl',      w: 30, label1:'Sl',        label2:'No',    align:'center' },
      { key:'lot',     w: 32, label1:'Lot',       label2:'No',    align:'center' },
      { key:'qty',     w: 72, label1:'Quantity',  label2:'(kgs)', align:'right'  },
      { key:'rate',    w: 66, label1:'Rate/kg',   label2:'(Rs)',  align:'right'  },
      { key:'value',   w: 96, label1:'Value',     label2:'(Rs)',  align:'right'  },
      { key:'comm',    w: 82, label1:'Commission',label2:'(Rs)',  align:'right'  },
      { key:'spacer',  w: 68, label1:'',          label2:'',      align:'center' },
      { key:'taxable', w: 89, label1:'Taxable',   label2:'Value', align:'right'  },
    ];
    const xs = [PAGE_L];
    cols.forEach(c => xs.push(xs[xs.length - 1] + c.w));
    const taxIdx = 7; // taxable column index

    // Header
    const HEAD_H = 26;
    const headTop = y;
    xs.forEach(x => doc.moveTo(x, headTop).lineTo(x, headTop + HEAD_H).stroke());
    doc.moveTo(PAGE_L, headTop).lineTo(PAGE_R, headTop).stroke();
    doc.moveTo(PAGE_L, headTop + HEAD_H).lineTo(PAGE_R, headTop + HEAD_H).stroke();
    doc.font('Helvetica-Bold').fontSize(9);
    // Header labels are always centred (data rows below still use c.align).
    cols.forEach((c, i) => {
      if (c.label1) doc.text(c.label1, xs[i] + 3, headTop + 4,  { width: c.w - 6, align: 'center' });
      if (c.label2) doc.text(c.label2, xs[i] + 3, headTop + 14, { width: c.w - 6, align: 'center' });
    });
    y = headTop + HEAD_H;

    // Data rows (padded to MAX_ROWS so the table is a clean ruled box)
    const ROW_H = 14;
    const MAX_ROWS = 14;
    doc.font('Helvetica').fontSize(9);
    let totalQty = 0, totalValue = 0, totalCommission = 0, totalTaxable = 0;
    for (let i = 0; i < Math.max(lots.length, MAX_ROWS); i++) {
      const lot = lots[i];
      xs.forEach(x => doc.moveTo(x, y).lineTo(x, y + ROW_H).stroke());
      if (lot) {
        const value      = Number(lot.qty || 0) * Number(lot.prate || 0);
        const commission = Number(lot.discount || 0);
        const taxable    = Number(lot.taxable != null ? lot.taxable : commission);
        totalQty        += Number(lot.qty || 0);
        totalValue      += value;
        totalCommission += commission;
        totalTaxable    += taxable;
        doc.text(String(i + 1),            xs[0] + 3, y + 3, { width: cols[0].w - 6, align: cols[0].align });
        doc.text(String(lot.lot_no || ''), xs[1] + 3, y + 3, { width: cols[1].w - 6, align: cols[1].align });
        doc.text(fmtQty(lot.qty),          xs[2] + 3, y + 3, { width: cols[2].w - 6, align: cols[2].align });
        doc.text(fmtAmt(lot.prate),        xs[3] + 3, y + 3, { width: cols[3].w - 6, align: cols[3].align });
        doc.text(fmtAmt(value),            xs[4] + 3, y + 3, { width: cols[4].w - 6, align: cols[4].align });
        doc.text(fmtAmt(commission),       xs[5] + 3, y + 3, { width: cols[5].w - 6, align: cols[5].align });
        // spacer column (index 6) intentionally blank
        doc.text(fmtAmt(taxable),          xs[taxIdx] + 3, y + 3, { width: cols[taxIdx].w - 6, align: cols[taxIdx].align });
      }
      y += ROW_H;
    }
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke();

    // ── TOTAL row ──
    const TOT_H = 16;
    doc.font('Helvetica-Bold').fontSize(9);
    doc.moveTo(PAGE_L, y).lineTo(PAGE_L, y + TOT_H).stroke();
    doc.moveTo(xs[2], y).lineTo(xs[2], y + TOT_H).stroke();   // after merged TOTAL (Sl+Lot)
    doc.text('TOTAL', PAGE_L + 3, y + 4, { width: cols[0].w + cols[1].w - 6, align: 'center' });
    doc.text(fmtQty(totalQty), xs[2] + 3, y + 4, { width: cols[2].w - 6, align: 'right' });
    doc.moveTo(xs[3], y).lineTo(xs[3], y + TOT_H).stroke();   // after qty
    doc.moveTo(xs[4], y).lineTo(xs[4], y + TOT_H).stroke();   // after rate (blank)
    doc.text(fmtAmt(totalValue), xs[4] + 3, y + 4, { width: cols[4].w - 6, align: 'right' });
    doc.moveTo(xs[5], y).lineTo(xs[5], y + TOT_H).stroke();   // after value
    doc.text(fmtAmt(totalCommission), xs[5] + 3, y + 4, { width: cols[5].w - 6, align: 'right' });
    doc.moveTo(xs[6], y).lineTo(xs[6], y + TOT_H).stroke();   // after commission
    doc.moveTo(xs[taxIdx], y).lineTo(xs[taxIdx], y + TOT_H).stroke(); // after spacer
    doc.moveTo(PAGE_R, y).lineTo(PAGE_R, y + TOT_H).stroke();
    doc.text(fmtAmt(totalTaxable), xs[taxIdx] + 3, y + 4, { width: cols[taxIdx].w - 6, align: 'right' });
    y += TOT_H;
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke();

    // ── Tax breakdown block (CGST/SGST/IGST on Commission & Handling) ──
    // Driven by the stored DN record. The left region is one tall empty
    // cell; the label sits in the middle span, the amount in the Taxable
    // column. CGST/SGST/IGST always render (0.00 where N/A), as in the ref.
    const rRate = Number(cfg.discount_gst) || Number(cfg.gst_service) || 18;
    const halfRate = rRate / 2;
    const roundOff = Math.round((Number(dn.total || 0)
      - (Number(dn.amount || 0) + Number(dn.cgst || 0) + Number(dn.sgst || 0) + Number(dn.igst || 0))) * 100) / 100;
    const taxRows = [
      { label: `C G S T @ ${halfRate}% on C&H`, amt: Number(dn.cgst || 0) },
      { label: `S G S T @ ${halfRate}% on C&H`, amt: Number(dn.sgst || 0) },
      { label: `I G S T @ ${rRate}% on C&H`,    amt: Number(dn.igst || 0) },
      { label: 'ROUND ON/OFF',                  amt: roundOff },
    ];
    const labelX = xs[4];       // tax-label span starts at the Value column
    const valueX = xs[taxIdx];  // amounts sit in the Taxable column
    const TAX_H = 14;
    doc.font('Helvetica').fontSize(9);
    for (const tr of taxRows) {
      doc.moveTo(PAGE_L, y).lineTo(PAGE_L, y + TAX_H).stroke();
      doc.moveTo(labelX, y).lineTo(labelX, y + TAX_H).stroke();
      doc.moveTo(valueX, y).lineTo(valueX, y + TAX_H).stroke();
      doc.moveTo(PAGE_R, y).lineTo(PAGE_R, y + TAX_H).stroke();
      doc.text(tr.label, labelX + 6, y + 3, { width: valueX - labelX - 12, align: 'left' });
      doc.text(fmtAmt(tr.amt), valueX + 3, y + 3, { width: cols[taxIdx].w - 6, align: 'right' });
      y += TAX_H;
    }
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke();   // divider above GRAND TOTAL

    // ── GRAND TOTAL row ──
    const GT_H = 18;
    doc.moveTo(PAGE_L, y).lineTo(PAGE_L, y + GT_H).stroke();
    doc.moveTo(labelX, y).lineTo(labelX, y + GT_H).stroke();
    doc.moveTo(valueX, y).lineTo(valueX, y + GT_H).stroke();
    doc.moveTo(PAGE_R, y).lineTo(PAGE_R, y + GT_H).stroke();
    doc.font('Helvetica-Bold').fontSize(10).text('GRAND TOTAL', labelX + 6, y + 5, { width: valueX - labelX - 12, align: 'left' });
    doc.text(fmtAmt(Number(dn.total || 0)), valueX + 3, y + 5, { width: cols[taxIdx].w - 6, align: 'right' });
    y += GT_H;
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke();
    y += 14;

    // ── Amount in words (paise-aware) ──
    doc.font('Helvetica').fontSize(10).text(
      `${amountToWords(Number(dn.total || 0))} Only`,
      PAGE_L + 4, y, { width: PAGE_W - 8 });
    y = doc.y + 18;

    // ── Footer: issuing company signatory ──
    doc.font('Helvetica-Bold').fontSize(10).text(`For ${(co.short || co.name || '').toUpperCase()}`, PAGE_L, y, { width: PAGE_W - 8, align: 'right' });
    y += 50;
    doc.font('Helvetica').fontSize(9).text('Authorised Signatory', PAGE_L, y, { width: PAGE_W - 8, align: 'right' });
    y += 14;

    // Bottom frame + left/right outer borders from FRAME_TOP to here
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).stroke();
    doc.moveTo(PAGE_L, FRAME_TOP).lineTo(PAGE_L, y).stroke();
    doc.moveTo(PAGE_R, FRAME_TOP).lineTo(PAGE_R, y).stroke();
}

app.get('/api/debit-notes/:id/pdf', requireView, async (req, res) => {
  try {
    const db  = getDb();
    const cfg = getSettingsFlat(db);
    const dn  = db.get('SELECT * FROM debit_notes WHERE id = ?', [req.params.id]);
    if (!dn) return res.status(404).json({ error: 'Debit note not found' });

    // Engine: 'html' → Letterhead template (pdf/render-debit-note-html), else legacy
    // PDFKit. ?template=<id> forces the HTML engine + that layout; 'pdfkit'
    // forces legacy — same convention as the sales/purchase routes.
    const tplChoice = String(req.query.template || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'debit_note_engine', templateKey: 'debit_note_template', tplChoice });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="DebitNote_${dn.note_no || dn.id}.pdf"`);
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, debit_note_template: tplChoice } : cfg;
      const pdf = await require('./pdf/render-debit-note-html').generateDebitNoteHtmlPDF(dn, db, cfg2);
      return res.send(pdf);
    }
    const PDFDocument = require('pdfkit');
    const doc = new PDFDocument({ size: 'A4', margin: 30 });
    doc.pipe(res);
    _renderDebitNote(doc, dn, db, cfg);
    doc.end();
  } catch (e) {
    console.error('[dn-pdf] failed:', e);
    if (!res.headersSent) res.status(500).json({ error: e.message });
  }
});

// Bulk: Body { ids: [...] } → one merged PDF, page-break per debit note.
// Used by the "Print Selected" button in the Debit Notes tab. Mirrors the
// payments pdf-bulk endpoint so the UX is consistent (single-click yields
// one downloadable PDF, no popup-blocker tab spam).
app.post('/api/debit-notes/pdf-bulk', requireView, async (req, res) => {
  let doc, piped = false;
  try {
    const db  = getDb();
    const cfg = getSettingsFlat(db);
    const ids = Array.isArray(req.body.ids)
      ? req.body.ids.map(n => parseInt(n, 10)).filter(Number.isFinite)
      : [];
    if (!ids.length) return res.status(400).json({ error: 'ids[] required' });

    // Fetch all DNs in the order the client sent them so the merged PDF
    // mirrors the user's selection order.
    const placeholders = ids.map(() => '?').join(',');
    const rows = db.all(
      `SELECT * FROM debit_notes WHERE id IN (${placeholders})`,
      ids
    );
    if (!rows.length) return res.status(404).json({ error: 'No debit notes found' });
    const byId = new Map(rows.map(r => [r.id, r]));
    const dns  = ids.map(id => byId.get(id)).filter(Boolean);

    const tplChoice = String(req.query.template || req.body.template || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'debit_note_engine', templateKey: 'debit_note_template', tplChoice });
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, debit_note_template: tplChoice } : cfg;
      const pdf = await require('./pdf/render-debit-note-html').generateDebitNotesHtmlBatchPDF(dns, db, cfg2);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="DebitNotes_Batch_${dns.length}.pdf"`);
      return res.send(pdf);
    }

    const PDFDocument = require('pdfkit');
    doc = new PDFDocument({ size: 'A4', margin: 30 });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="DebitNotes_Batch_${dns.length}.pdf"`);
    doc.pipe(res); piped = true;
    res.on('close', () => { try { doc.destroy(); } catch (_) {} });

    dns.forEach((dn, i) => {
      if (i > 0) doc.addPage();
      try { _renderDebitNote(doc, dn, db, cfg); }
      catch (e) {
        try { doc.font('Helvetica').fontSize(10).text(`Error rendering DN ${dn.note_no || dn.id}: ${e.message}`); } catch (_) {}
      }
    });
    doc.end();
  } catch (e) {
    console.error('[dn-pdf-bulk] failed:', e);
    if (piped && doc) { try { doc.end(); } catch (_) {} }
    else if (!res.headersSent) res.status(500).json({ error: e.message || 'PDF failed' });
  }
});

// ══════════════════════════════════════════════════════════════
// DEBIT NOTES — PLANTER
// ══════════════════════════════════════════════════════════════
// Parallel to the registered-dealer Debit Notes above, but scoped to
// PLANTER / agriculturist sellers. The source is the `bills` (bills of
// supply) table rather than `purchases`, and rows are stored in the
// `debit_notes_planter` table with its own trade-wise numbering. The
// discount math (Formula 5D — round(base/1000 × discount_days ×
// discount_pct)) and the GST treatment mirror the dealer flow exactly;
// only the data source and the inter/intra resolution differ (planters
// carry no GSTIN, so the split is keyed on the bill's state code).

// Feature flag — gates every write path (flag_debit_note_planter).
function requireDebitNotePlanterEnabled(req, res, next) {
  const cfg = getSettingsFlat(getDb());
  const on = String(cfg.flag_debit_note_planter || '').toLowerCase() === 'true';
  if (!on) return res.status(403).json({ error: 'Debit Note — Planter feature is disabled — enable "flag_debit_note_planter" in Settings → Flags' });
  next();
}

// Inter/intra classification for a planter DN. Planters have no GSTIN, so
// we compare the bill's GST state code (`bills.st_code`) against the
// company's own state code (read from the configured GSTIN, falling back
// to tally_state_code / business_state). No state code on the bill ⇒
// treat as local (agriculturists are local sellers by default).
function derivePlanterSaleType(bill, cfg) {
  const cfgObj = cfg || {};
  const code2 = (s) => {
    let c = String(s || '').trim().toUpperCase();
    if (c.startsWith('GSTIN.')) c = c.slice(6);
    else if (c.startsWith('GSTIN')) c = c.slice(5);
    return /^\d{2}/.test(c) ? c.slice(0, 2) : '';
  };
  const bizState = String(cfgObj.business_state || '').toUpperCase();
  const cands = bizState === 'KERALA'
    ? [cfgObj.kl_gstin, cfgObj.tn_gstin, cfgObj.gstin]
    : [cfgObj.tn_gstin, cfgObj.kl_gstin, cfgObj.gstin];
  let companyStateCode = '';
  for (const g of cands) { const c = code2(g); if (c) { companyStateCode = c; break; } }
  if (!companyStateCode) companyStateCode = String(cfgObj.tally_state_code || (bizState === 'KERALA' ? '32' : '33'));
  const raw = String((bill && bill.st_code) || '').trim();
  const planterCode = /^\d{2}/.test(raw) ? raw.slice(0, 2) : '';
  if (planterCode) return planterCode === companyStateCode ? 'L' : 'I';
  return 'L';
}

// List planter debit notes (paginated, trade- + search-filterable).
app.get('/api/debit-notes-planter', requireView, (req, res) => {
  const { ano, from, to, search } = req.query;
  const db = getDb();
  let where = 'WHERE 1=1'; const p = [];
  if (ano) { where += ' AND ano = ?'; p.push(ano); }
  if (from && to) { where += ' AND date BETWEEN ? AND ?'; p.push(from, to); }
  const qstr = String(search || '').trim();
  if (qstr) {
    const like = `%${qstr}%`;
    const ors = ['CAST(note_no AS TEXT) LIKE ?', 'name LIKE ?', 'CAST(ano AS TEXT) LIKE ?'];
    p.push(like, like, like);
    // Lot-wise planter DNs name their lot directly; seller-wise ones resolve
    // through the planter's lots on that trade.
    const lotNums = smartLotNumbers(qstr);
    const ownLot = smartLotSql('debit_notes_planter.lot_no', lotNums);
    if (ownLot) {
      ors.push(`(TRIM(COALESCE(debit_notes_planter.lot_no,'')) != '' AND ${ownLot.sql})`);
      p.push(...ownLot.params);
      const viaLots = smartLotSql('l.lot_no', lotNums);
      ors.push(`(TRIM(COALESCE(debit_notes_planter.lot_no,'')) = '' AND EXISTS (
                   SELECT 1 FROM lots l
                    WHERE l.auction_id = (SELECT a.id FROM auctions a WHERE a.ano = debit_notes_planter.ano LIMIT 1)
                      AND UPPER(TRIM(COALESCE(l.name,''))) = UPPER(TRIM(COALESCE(debit_notes_planter.name,'')))
                      AND ${viaLots.sql}))`);
      p.push(...viaLots.params);
    }
    const phone = smartPhoneDigits(qstr);
    if (phone) {
      ors.push(`EXISTS (SELECT 1 FROM traders t
                         WHERE UPPER(TRIM(COALESCE(t.name,''))) = UPPER(TRIM(COALESCE(debit_notes_planter.name,'')))
                           AND (${smartPhoneSql('t.tel')} LIKE ? OR ${smartPhoneSql('t.whatsapp')} LIKE ?))`);
      p.push(`%${phone}%`, `%${phone}%`);
    }
    where += ' AND (' + ors.join(' OR ') + ')';
  }
  const page     = Math.max(1, parseInt(req.query.page, 10) || 1);
  const pageSize = Math.min(500, Math.max(1, parseInt(req.query.pageSize, 10) || 50));
  const offset   = (page - 1) * pageSize;
  const wantPaged = req.query.page != null || req.query.pageSize != null;
  // Default order: note number ascending — same TEXT-numeric CAST as the
  // dealer debit notes above.
  const baseQuery = 'SELECT * FROM debit_notes_planter ' + where + ' ORDER BY CAST(note_no AS INTEGER), note_no, date';
  if (wantPaged) {
    const total = db.get('SELECT COUNT(*) AS c FROM debit_notes_planter ' + where, p).c;
    const rows = db.all(baseQuery + ' LIMIT ? OFFSET ?', [...p, pageSize, offset]);
    return res.json({ rows: withFmtDate(rows), total, page, pageSize });
  }
  res.json(withFmtDate(db.all(baseQuery + ' LIMIT 500', p)));
});

// Bills in a trade that don't yet have a planter DN. Drives the Generate
// All preview. Resolves auctionId → ano, then anti-joins bills against
// debit_notes_planter on (ano, name). bills.ano is space-padded for
// single-digit trades, so match on TRIM(ano).
app.get('/api/debit-notes-planter/eligible-bills/:auctionId', requireView, (req, res) => {
  const db = getDb();
  const auction = db.get('SELECT ano FROM auctions WHERE id = ?', [req.params.auctionId]);
  if (!auction) return res.status(404).json({ error: 'Auction not found' });
  const ano = auction.ano;
  // `amount` is the DN BASE (sum of com + sertax on the planter's grade-1
  // lots), not the bill value. Only planters who actually have grade-1
  // service charges are eligible.
  const rows = db.all(
    `SELECT b.id, b.bil, b.name,
            (SELECT COALESCE(SUM(COALESCE(l.com,0) + COALESCE(l.sertax,0)), 0)
               FROM lots l
              WHERE l.auction_id = b.auction_id AND l.name = b.name
                AND TRIM(COALESCE(l.grade,'')) = '1') AS amount,
            b.date, b.pstate AS state
       FROM bills b
      WHERE TRIM(b.ano) = ?
        AND EXISTS (
          SELECT 1 FROM lots l2
           WHERE l2.auction_id = b.auction_id AND l2.name = b.name
             AND TRIM(COALESCE(l2.grade,'')) = '1'
             AND (COALESCE(l2.com,0) + COALESCE(l2.sertax,0)) > 0
        )
        AND NOT EXISTS (
          SELECT 1 FROM debit_notes_planter dn
           WHERE dn.ano = ? AND dn.name = b.name
        )
      ORDER BY b.id`,
    [String(ano).trim(), ano]
  );
  res.json(rows);
});

// ── LOT-WISE eligible list (flag_lotwise_dn_planter) ─────────────────────
// The lot-wise counterpart of /eligible-bills: one row per grade-1 LOT that
// carries a service charge (com + sertax > 0) rather than one row per planter.
// A lot-wise planter DN's amount IS that lot's com + sertax, so summing the
// lot rows for a planter reproduces the seller-wise DN amount exactly.
//
// Ordered by lot number ASCENDING — that is the order Generate All hands out
// note numbers, per the requested numbering scheme.
//
// `already_dn` is advisory for the UI: it surfaces the note number of any lot
// that already has a lot-wise planter DN in this trade (matched on ano+lot_no).
app.get('/api/debit-notes-planter/eligible-lots/:auctionId', requireView, (req, res) => {
  const db = getDb();
  const auction = db.get('SELECT ano FROM auctions WHERE id = ?', [req.params.auctionId]);
  if (!auction) return res.status(404).json({ error: 'Auction not found' });
  const ano = auction.ano;
  const rows = db.all(
    `SELECT l.id AS lot_id, l.lot_no, l.name, l.trader_id, l.pst_code,
            (COALESCE(l.com,0) + COALESCE(l.sertax,0)) AS amount,
            (SELECT dn.note_no FROM debit_notes_planter dn
              WHERE TRIM(dn.ano) = TRIM(?)
                AND TRIM(COALESCE(dn.lot_no,'')) = TRIM(l.lot_no)
                AND UPPER(TRIM(dn.name)) = UPPER(TRIM(l.name))
              LIMIT 1) AS already_dn
       FROM lots l
      WHERE l.auction_id = ?
        AND l.name IS NOT NULL AND l.name != ''
        AND TRIM(COALESCE(l.grade,'')) = '1'
        AND (COALESCE(l.com,0) + COALESCE(l.sertax,0)) > 0
      ORDER BY CAST(l.lot_no AS INTEGER), l.lot_no`,
    [String(ano).trim(), req.params.auctionId]
  );
  res.json(rows);
});

// Next-available planter DN number for a trade (trade-wise sequence).
app.get('/api/debit-notes-planter/next-note-no', requireView, (req, res) => {
  const db = getDb();
  const ano = String(req.query.ano || '').trim();
  if (!ano) return res.status(400).json({ error: 'ano (trade number) is required for trade-wise numbering' });
  const row = db.get('SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes_planter WHERE ano = ?', [ano]);
  const mx = parseInt(row && row.mx, 10);
  res.json({ next: Number.isFinite(mx) && mx > 0 ? mx + 1 : 1, ano });
});

// Generate a SINGLE planter debit note. Inputs: bill number (`bilno`) +
// trade (`ano`). The bill must belong to the selected trade.
app.post('/api/debit-notes-planter/generate', requireInvoiceWrite, requireDebitNotePlanterEnabled, (req, res) => {
  const db = getDb();
  const cfg = getSettingsFlat(db);
  const ano   = String(req.body.ano || '').trim();
  if (!ano)   return res.status(400).json({ error: 'ano (trade number) is required' });

  // ── Mode resolution (flag_lotwise_dn_planter) ────────────────────────
  // A lot identifier in the body means a LOT-WISE planter DN for that one
  // grade-1 lot; its absence means the classic seller-wise DN driven from a
  // bill-of-supply number. Both are validated against the flag so a stale tab
  // cannot write a document in the mode the site isn't configured for.
  const reqLotNo = String(req.body.lotNo == null ? '' : req.body.lotNo).trim();
  const reqLotId = req.body.lotId;
  const wantsLotWise = reqLotNo !== '' || (reqLotId != null && String(reqLotId).trim() !== '');
  const lotWiseCfg = lotwiseDnPlanterOn(db);
  if (wantsLotWise && !lotWiseCfg) {
    return res.status(403).json({
      error: 'Lot-wise planter debit notes are disabled. Enable "Lot-wise Debit Notes — Planter" in Settings → Flags.',
      mode: 'seller',
    });
  }
  if (!wantsLotWise && lotWiseCfg) {
    return res.status(400).json({
      error: 'This site is set to LOT-WISE planter debit notes, but no lot was selected. Reload the page and pick a lot.',
      mode: 'lot',
    });
  }

  const bilno = String(req.body.bilno != null ? req.body.bilno : req.body.billNo || '').trim();
  if (!wantsLotWise && !bilno) return res.status(400).json({ error: 'bilno (bill of supply number) is required' });

  if (pcFlagOn(db)) {
    const gateAuction = db.get('SELECT id, price_checked_at FROM auctions WHERE ano = ? ORDER BY date DESC LIMIT 1', [ano]);
    if (gateAuction && !gateAuction.price_checked_at) {
      return res.status(412).json({
        error: 'Price check required',
        detail: 'Run Reports → Price Check against the auction before generating debit notes.',
        auctionId: gateAuction.id,
        gate: 'price_check',
      });
    }
  }

  // ── Resolve the DN's source, amount and inter/intra split, per mode ──
  // Both modes charge the company's service fee (commission + handling) back
  // to the planter. Seller-wise sums it across the planter's whole grade-1
  // holding for the trade; lot-wise takes it from the ONE lot — so the
  // lot-wise DNs for a planter sum to the seller-wise DN for that planter.
  let planterName, dnAmount, isInter, stateForRow, traderIdForRow;
  let stampLotNo = '', stampLotId = null, sourceInfo = {};
  if (wantsLotWise) {
    let lot = null;
    if (reqLotId != null && String(reqLotId).trim() !== '' && Number.isFinite(Number(reqLotId))) {
      lot = db.get('SELECT * FROM lots WHERE id = ?', [Number(reqLotId)]);
    }
    // Fall back to (trade, lot_no) when the id is absent or stale (re-import).
    if (!lot && reqLotNo) {
      lot = db.get(
        `SELECT l.* FROM lots l JOIN auctions a ON a.id = l.auction_id
          WHERE TRIM(a.ano) = TRIM(?) AND TRIM(l.lot_no) = ? ORDER BY l.id DESC LIMIT 1`,
        [ano, reqLotNo]);
    }
    if (!lot) return res.status(404).json({ error: `Lot ${reqLotNo || reqLotId} not found in trade #${ano}` });
    if (String(lot.grade || '').trim() !== '1') {
      return res.status(400).json({ error: `Lot ${lot.lot_no} is not a grade-1 (planter) lot — planter debit notes apply to grade-1 lots only.` });
    }
    const svc = Math.round(((Number(lot.com) || 0) + (Number(lot.sertax) || 0)) * 100) / 100;
    if (svc <= 0) return res.status(400).json({ error: `No grade-1 commission/handling on lot ${lot.lot_no} — nothing to debit` });
    // Duplicate guard — one lot-wise planter DN per (trade, lot).
    const dupe = db.get(
      `SELECT id, note_no FROM debit_notes_planter WHERE TRIM(ano) = TRIM(?) AND TRIM(COALESCE(lot_no,'')) = ? LIMIT 1`,
      [ano, lot.lot_no]);
    if (dupe) {
      return res.status(409).json({
        error: `Lot ${lot.lot_no} already has planter debit note #${dupe.note_no} in trade #${ano}.`,
        existingId: dupe.id, existingNoteNo: dupe.note_no,
      });
    }
    planterName    = lot.name || '';
    dnAmount       = svc;
    isInter        = derivePlanterSaleType({ st_code: lot.pst_code }, cfg) === 'I';
    stateForRow    = lot.pstate || lot.state || '';
    traderIdForRow = lot.trader_id || null;
    stampLotNo     = lot.lot_no || '';
    stampLotId     = lot.id != null ? lot.id : null;
    sourceInfo     = { lotNo: lot.lot_no };
  } else {
    const bill = db.get(
      `SELECT * FROM bills WHERE TRIM(ano) = ? AND CAST(bil AS TEXT) = ? ORDER BY id DESC LIMIT 1`,
      [String(ano).trim(), bilno]
    );
    if (!bill) return res.status(404).json({ error: `Bill of supply ${bilno} not found in trade #${ano}` });
    planterName = bill.name || '';
    const dupe = db.get(
      `SELECT id, note_no FROM debit_notes_planter WHERE ano = ? AND name = ? LIMIT 1`,
      [ano, planterName]
    );
    if (dupe) {
      return res.status(409).json({
        error: `Planter debit note #${dupe.note_no} already exists for ${planterName} in trade #${ano}`,
        existingId: dupe.id, existingNoteNo: dupe.note_no,
      });
    }
    // Base = sum(commission + handling) on the planter's GRADE-1 lots.
    const baseAmt = gradedServiceBase(db, bill.auction_id, planterName, '1');
    if (baseAmt <= 0) return res.status(400).json({ error: `No grade-1 commission/handling found for ${planterName} in trade #${ano} — nothing to debit` });
    dnAmount       = baseAmt;
    isInter        = derivePlanterSaleType(bill, cfg) === 'I';
    stateForRow    = bill.pstate || bill.state || '';
    traderIdForRow = bill.trader_id || null;
    sourceInfo     = { bilno };
  }

  const dnGstRate = Number(cfg.discount_gst) || Number(cfg.gst_service) || 18;
  let cgst = 0, sgst = 0, igst = 0;
  if (isInter) {
    igst = Math.round(dnAmount * dnGstRate / 100 * 100) / 100;
  } else {
    const half = Math.round(dnAmount * (dnGstRate / 2) / 100 * 100) / 100;
    cgst = half; sgst = half;
  }
  const total = Math.round((dnAmount + cgst + sgst + igst) * 100) / 100;

  // DN date = trade.date (same day as the auction / bill of supply).
  const trade = db.get('SELECT date FROM auctions WHERE ano = ? LIMIT 1', [ano]);
  const dnDate = trade && trade.date ? normalizeDate(trade.date) : new Date().toISOString().slice(0, 10);

  const rawStart = req.body.startNoteNo != null ? req.body.startNoteNo : req.body.noteNo;
  let noteNo;
  if (rawStart != null && String(rawStart).trim() !== '') {
    const n = parseInt(String(rawStart).trim(), 10);
    if (!Number.isFinite(n) || n < 1) return res.status(400).json({ error: 'Starting Number must be a positive integer' });
    noteNo = String(n);
    const taken = db.get(`SELECT id FROM debit_notes_planter WHERE ano = ? AND CAST(note_no AS INTEGER) = ? LIMIT 1`, [ano, n]);
    if (taken) {
      const row = db.get('SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes_planter WHERE ano = ?', [ano]);
      const mx = parseInt(row && row.mx, 10);
      return res.status(409).json({
        error: `Planter debit note #${n} is already used in trade #${ano}. Choose a different number.`,
        suggested: Number.isFinite(mx) && mx > 0 ? mx + 1 : 1,
      });
    }
  } else {
    const row = db.get('SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes_planter WHERE ano = ?', [ano]);
    const mx = parseInt(row && row.mx, 10);
    noteNo = String(Number.isFinite(mx) && mx > 0 ? mx + 1 : 1);
  }

  db.run(
    `INSERT INTO debit_notes_planter (ano,date,state,name,note_no,amount,cgst,sgst,igst,total,trader_id,lot_no,lot_id)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`,
    [ano, dnDate, stateForRow, planterName, noteNo, dnAmount, cgst, sgst, igst, total,
     // Seller FK inherited from the source (bill of supply, or lot in lot-wise).
     traderIdForRow,
     // Empty lot_no marks this row seller-wise for every future reader.
     stampLotNo, stampLotId]
  );
  res.json({ success: true, created: 1, note_no: noteNo, ano, planter: planterName,
             amount: dnAmount, cgst, sgst, igst, total,
             mode: wantsLotWise ? 'lot' : 'seller', ...sourceInfo });
});

// Trade-wide planter DN generation — one DN per eligible bill of supply.
app.post('/api/debit-notes-planter/generate-bulk', requireInvoiceWrite, requireDebitNotePlanterEnabled, (req, res) => {
  const db = getDb();
  const cfg = getSettingsFlat(db);
  const ano = String(req.body.ano || '').trim();
  if (!ano) return res.status(400).json({ error: 'Trade number (ano) is required' });

  if (pcFlagOn(db)) {
    const ga = db.get('SELECT id, price_checked_at FROM auctions WHERE ano = ? ORDER BY date DESC LIMIT 1', [ano]);
    if (ga && !ga.price_checked_at) {
      return res.status(412).json({
        error: 'Price check required',
        detail: 'Run Reports → Price Check against the auction before generating debit notes.',
        auctionId: ga.id, gate: 'price_check',
      });
    }
  }

  // ── LOT-WISE branch (flag_lotwise_dn_planter) ────────────────────────
  // One planter DN per grade-1 LOT that carries a service charge, numbered in
  // LOT-NUMBER ASCENDING order (the requested numbering scheme). Returns early
  // so the seller-wise path below stays exactly as it was.
  if (lotwiseDnPlanterOn(db)) {
    const lots = db.all(
      `SELECT l.id AS lot_id, l.lot_no, l.name, l.trader_id, l.pst_code, l.pstate, l.state,
              (COALESCE(l.com,0) + COALESCE(l.sertax,0)) AS svc
         FROM lots l JOIN auctions a ON a.id = l.auction_id
        WHERE TRIM(a.ano) = TRIM(?)
          AND l.name IS NOT NULL AND l.name != ''
          AND TRIM(COALESCE(l.grade,'')) = '1'
          AND (COALESCE(l.com,0) + COALESCE(l.sertax,0)) > 0
        ORDER BY CAST(l.lot_no AS INTEGER), l.lot_no`,
      [String(ano).trim()]);
    if (!lots.length) {
      return res.json({ success: true, mode: 'lot', created: 0, skipped: 0, generated: [], skippedDetails: [], note: `No eligible grade-1 lots in trade #${ano}` });
    }
    // Lots already carrying a lot-wise DN in this trade (matched on lot_no) —
    // a re-run tops up the rest instead of duplicating.
    const doneLots = new Set(
      db.all(`SELECT lot_no FROM debit_notes_planter WHERE TRIM(ano) = TRIM(?) AND TRIM(COALESCE(lot_no,'')) <> ''`, [String(ano).trim()])
        .map(r => String(r.lot_no || '').trim())
    );
    const tradeL = db.get('SELECT date FROM auctions WHERE ano = ? LIMIT 1', [ano]);
    const dnDateL = tradeL && tradeL.date ? normalizeDate(tradeL.date) : new Date().toISOString().slice(0, 10);
    const dnGstRateL = Number(cfg.discount_gst) || Number(cfg.gst_service) || 0;
    const pendingCount = lots.filter(l => !doneLots.has(String(l.lot_no || '').trim())).length;

    // Note numbering — same contract as the seller-wise path below.
    let nextNoteNo;
    const rawStartL = req.body.startNoteNo != null ? req.body.startNoteNo : req.body.startInvoiceNo;
    if (rawStartL != null && String(rawStartL).trim() !== '') {
      const n = parseInt(String(rawStartL).trim(), 10);
      if (!Number.isFinite(n) || n < 1) return res.status(400).json({ error: 'Starting Number must be a positive integer' });
      nextNoteNo = n;
      if (pendingCount > 0) {
        const upper = nextNoteNo + pendingCount - 1;
        const collisions = db.all(
          `SELECT CAST(note_no AS INTEGER) AS n FROM debit_notes_planter
            WHERE ano = ? AND CAST(note_no AS INTEGER) BETWEEN ? AND ? ORDER BY n`,
          [ano, nextNoteNo, upper]);
        if (collisions.length) {
          const row = db.get('SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes_planter WHERE ano = ?', [ano]);
          const mx = parseInt(row && row.mx, 10);
          const safe = Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
          return res.status(409).json({
            error: `Starting Number ${nextNoteNo} would overlap existing planter debit note(s) in trade #${ano}. Try ${safe} or higher.`,
            collisions: collisions.map(c => c.n), suggested: safe,
          });
        }
      }
    } else {
      const row = db.get('SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes_planter WHERE ano = ?', [ano]);
      const mx = parseInt(row && row.mx, 10);
      nextNoteNo = Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
    }

    const generatedL = [];
    const skippedL = [];
    for (const l of lots) {
      const key = String(l.lot_no || '').trim();
      if (doneLots.has(key)) {
        skippedL.push({ lotNo: l.lot_no, ano, buyer: l.name || '', reason: 'duplicate (lot already has a planter DN in this trade)' });
        continue;
      }
      const dnAmount = Math.round((Number(l.svc) || 0) * 100) / 100;
      const isInter = derivePlanterSaleType({ st_code: l.pst_code }, cfg) === 'I';
      let cgst = 0, sgst = 0, igst = 0;
      if (isInter) {
        igst = Math.round(dnAmount * dnGstRateL / 100 * 100) / 100;
      } else {
        const half = Math.round(dnAmount * (dnGstRateL / 2) / 100 * 100) / 100;
        cgst = half; sgst = half;
      }
      const total = Math.round((dnAmount + cgst + sgst + igst) * 100) / 100;
      db.run(
        `INSERT INTO debit_notes_planter (ano,date,state,name,note_no,amount,cgst,sgst,igst,total,trader_id,lot_no,lot_id)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)`,
        [ano, dnDateL, l.pstate || l.state || '', l.name || '', String(nextNoteNo), dnAmount, cgst, sgst, igst, total,
         l.trader_id || null, l.lot_no || '', l.lot_id != null ? l.lot_id : null]);
      generatedL.push({ note_no: nextNoteNo, lotNo: l.lot_no, planter: l.name || '', total });
      doneLots.add(key);
      nextNoteNo++;
    }
    return res.json({
      success: true, mode: 'lot',
      created: generatedL.length, skipped: skippedL.length,
      generated: generatedL, skippedDetails: skippedL,
      note: generatedL.length === 0 && skippedL.length === 0 ? `No eligible grade-1 lots in trade #${ano}` : undefined,
    });
  }

  // Ordered by planter name (case-insensitively) rather than insertion id —
  // note numbers are handed out in this order, so the planter DN series runs
  // alphabetically like the bills of supply it derives from. `id` only breaks
  // ties between two bills sharing a name.
  const bills = db.all(
    `SELECT * FROM bills WHERE TRIM(ano) = ? ORDER BY UPPER(TRIM(COALESCE(name,''))), id`,
    [String(ano).trim()]);
  if (!bills.length) {
    return res.json({ success: true, created: 0, skipped: 0, generated: [], skippedDetails: [], note: `No bills of supply in trade #${ano}` });
  }

  const existingKeys = new Set(
    db.all(`SELECT name FROM debit_notes_planter WHERE ano = ?`, [ano]).map(r => r.name || '')
  );
  // DN date = trade.date (same day as the auction / bill of supply).
  const trade = db.get('SELECT date FROM auctions WHERE ano = ? LIMIT 1', [ano]);
  const dnDate = trade && trade.date ? normalizeDate(trade.date) : new Date().toISOString().slice(0, 10);

  const dnGstRate = Number(cfg.discount_gst) || Number(cfg.gst_service) || 0;

  const eligibleCount = bills.filter(b => !existingKeys.has(b.name || '') && gradedServiceBase(db, b.auction_id, b.name || '', '1') > 0).length;

  let nextNoteNo;
  const rawStart = req.body.startNoteNo != null ? req.body.startNoteNo : req.body.startInvoiceNo;
  if (rawStart != null && String(rawStart).trim() !== '') {
    const n = parseInt(String(rawStart).trim(), 10);
    if (!Number.isFinite(n) || n < 1) return res.status(400).json({ error: 'Starting Number must be a positive integer' });
    nextNoteNo = n;
    if (eligibleCount > 0) {
      const upper = nextNoteNo + eligibleCount - 1;
      const collisions = db.all(
        `SELECT CAST(note_no AS INTEGER) AS n FROM debit_notes_planter
          WHERE ano = ? AND CAST(note_no AS INTEGER) BETWEEN ? AND ? ORDER BY n`,
        [ano, nextNoteNo, upper]
      );
      if (collisions.length) {
        const row = db.get('SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes_planter WHERE ano = ?', [ano]);
        const mx = parseInt(row && row.mx, 10);
        const safe = Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
        return res.status(409).json({
          error: `Starting Number ${nextNoteNo} would overlap existing planter debit note(s) in trade #${ano}. Try ${safe} or higher.`,
          collisions: collisions.map(c => c.n), suggested: safe,
        });
      }
    }
  } else {
    const row = db.get('SELECT MAX(CAST(note_no AS INTEGER)) AS mx FROM debit_notes_planter WHERE ano = ?', [ano]);
    const mx = parseInt(row && row.mx, 10);
    nextNoteNo = Number.isFinite(mx) && mx > 0 ? mx + 1 : 1;
  }

  const generated = [];
  const skipped   = [];
  for (const b of bills) {
    const planterName = b.name || '';
    if (existingKeys.has(planterName)) {
      skipped.push({ invo: b.bil, ano, buyer: planterName, reason: 'duplicate (DN already exists for this planter in this trade)' });
      continue;
    }
    // Base = sum(commission + handling) on the planter's GRADE-1 lots.
    const baseAmt = gradedServiceBase(db, b.auction_id, planterName, '1');
    if (baseAmt <= 0) { skipped.push({ invo: b.bil, ano, buyer: planterName, reason: 'no grade-1 commission/handling' }); continue; }
    // Taxable amount = commission + handling on the grade-1 lots; GST on
    // that, total = amount + GST. (Not a Formula-5D discount — dealer-only.)
    const dnAmount = baseAmt;

    const isInter = derivePlanterSaleType(b, cfg) === 'I';
    let cgst = 0, sgst = 0, igst = 0;
    if (isInter) {
      igst = Math.round(dnAmount * dnGstRate / 100 * 100) / 100;
    } else {
      const half = Math.round(dnAmount * (dnGstRate / 2) / 100 * 100) / 100;
      cgst = half; sgst = half;
    }
    const total = Math.round((dnAmount + cgst + sgst + igst) * 100) / 100;

    db.run(
      `INSERT INTO debit_notes_planter (ano,date,state,name,note_no,amount,cgst,sgst,igst,total,trader_id)
       VALUES (?,?,?,?,?,?,?,?,?,?,?)`,
      [ano, dnDate, b.pstate || b.state || '', planterName, String(nextNoteNo), dnAmount, cgst, sgst, igst, total,
       b.trader_id || null]
    );
    generated.push({ note_no: nextNoteNo, bilno: b.bil, planter: planterName, total });
    existingKeys.add(planterName);
    nextNoteNo++;
  }

  res.json({
    success: true,
    created: generated.length,
    skipped: skipped.length,
    generated,
    skippedDetails: skipped,
    note: generated.length === 0 && skipped.length === 0 ? `No eligible bills in trade #${ano}` : undefined,
  });
});

app.delete('/api/debit-notes-planter/:id', requireDelete, (req, res) => {
  const db = getDb();
  db.run('DELETE FROM debit_notes_planter WHERE id = ?', [req.params.id]);
  res.json({ success: true });
});

app.put('/api/debit-notes-planter/:id', requireInvoiceWrite, (req, res) => {
  const n = req.body;
  const db = getDb();
  const fields = ['ano','date','state','name','note_no','amount','cgst','sgst','igst','total'];
  const sets = []; const vals = [];
  for (const f of fields) { if (n[f] !== undefined) { sets.push(`${f}=?`); vals.push(n[f]); } }
  if (!sets.length) return res.status(400).json({ error: 'No fields to update' });
  vals.push(req.params.id);
  db.run(`UPDATE debit_notes_planter SET ${sets.join(',')} WHERE id=?`, vals);
  res.json({ success: true });
});

// Planter DN PDF — reuses the same single-row renderer as dealer DNs.
app.get('/api/debit-notes-planter/:id/pdf', requireView, async (req, res) => {
  try {
    const db  = getDb();
    const cfg = getSettingsFlat(db);
    const dn  = db.get('SELECT * FROM debit_notes_planter WHERE id = ?', [req.params.id]);
    if (!dn) return res.status(404).json({ error: 'Debit note not found' });
    const tplChoice = String(req.query.template || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'debit_note_engine', templateKey: 'debit_note_template', tplChoice });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="DebitNotePlanter_${dn.note_no || dn.id}.pdf"`);
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, debit_note_template: tplChoice } : cfg;
      const pdf = await require('./pdf/render-debit-note-html').generateDebitNoteHtmlPDF(dn, db, cfg2, { planter: true });
      return res.send(pdf);
    }
    const PDFDocument = require('pdfkit');
    const doc = new PDFDocument({ size: 'A4', margin: 30 });
    doc.pipe(res);
    _renderDebitNote(doc, dn, db, cfg, { planter: true });
    doc.end();
  } catch (e) {
    console.error('[dnp-pdf] failed:', e);
    if (!res.headersSent) res.status(500).json({ error: e.message });
  }
});

app.post('/api/debit-notes-planter/pdf-bulk', requireView, async (req, res) => {
  let doc, piped = false;
  try {
    const db  = getDb();
    const cfg = getSettingsFlat(db);
    const ids = Array.isArray(req.body.ids) ? req.body.ids.map(n => parseInt(n, 10)).filter(Number.isFinite) : [];
    if (!ids.length) return res.status(400).json({ error: 'ids[] required' });
    const placeholders = ids.map(() => '?').join(',');
    const rows = db.all(`SELECT * FROM debit_notes_planter WHERE id IN (${placeholders})`, ids);
    if (!rows.length) return res.status(404).json({ error: 'No debit notes found' });
    const byId = new Map(rows.map(r => [r.id, r]));
    const dns  = ids.map(id => byId.get(id)).filter(Boolean);
    const tplChoice = String(req.query.template || req.body.template || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'debit_note_engine', templateKey: 'debit_note_template', tplChoice });
    if (useHtml) {
      const cfg2 = tplChoice ? { ...cfg, debit_note_template: tplChoice } : cfg;
      const pdf = await require('./pdf/render-debit-note-html').generateDebitNotesHtmlBatchPDF(dns, db, cfg2, { planter: true });
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="DebitNotesPlanter_Batch_${dns.length}.pdf"`);
      return res.send(pdf);
    }
    const PDFDocument = require('pdfkit');
    doc = new PDFDocument({ size: 'A4', margin: 30 });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="DebitNotesPlanter_Batch_${dns.length}.pdf"`);
    doc.pipe(res); piped = true;
    res.on('close', () => { try { doc.destroy(); } catch (_) {} });
    dns.forEach((dn, i) => {
      if (i > 0) doc.addPage();
      try { _renderDebitNote(doc, dn, db, cfg, { planter: true }); }
      catch (e) { try { doc.font('Helvetica').fontSize(10).text(`Error rendering DN ${dn.note_no || dn.id}: ${e.message}`); } catch (_) {} }
    });
    doc.end();
  } catch (e) {
    console.error('[dnp-pdf-bulk] failed:', e);
    if (piped && doc) { try { doc.end(); } catch (_) {} }
    else if (!res.headersSent) res.status(500).json({ error: e.message || 'PDF failed' });
  }
});

// ══════════════════════════════════════════════════════════════
// JOURNALS (JOUR.PRG, PUJOUR.PRG, PPUJOUR.PRG)
// ══════════════════════════════════════════════════════════════
// e-Auction-only build: journals filter by trade (auction_id), not by
// date range. Dates rendered dd/mm/yyyy by the calculations layer.
app.get('/api/journals/sales', requireView, (req, res) => {
  const { auctionId, saleType } = req.query;
  if (!auctionId) return res.status(400).json({ error: 'auctionId required' });
  const db = getDb();
  res.json(getSalesJournal(db, auctionId, saleType, getSettingsFlat(db)));
});

// Sale-type ledger summary printed under the Sales journal / PDF (Cardamom &
// Gunny by Export/Inter-State/Local, GST, charges, sample⇄discount, state total).
app.get('/api/journals/sales-summary', requireView, (req, res) => {
  const { auctionId, saleType } = req.query;
  if (!auctionId) return res.status(400).json({ error: 'auctionId required' });
  const db = getDb();
  res.json(getSalesJournalSummary(db, parseInt(auctionId, 10), saleType, getSettingsFlat(db))
    || { lines: [], stateLabel: '', stateTotal: 0 });
});

app.get('/api/journals/purchase', requireView, (req, res) => {
  const { auctionId, type } = req.query;
  if (!auctionId) return res.status(400).json({ error: 'auctionId required' });
  res.json(getPurchaseJournal(getDb(), auctionId, type || 'dealer'));
});

// Journal exports (XLSX only). Trade-based — dates dd/mm/yyyy.
app.get('/api/exports/sales-journal', requireExport, async (req, res) => {
  const { auctionId, saleType } = req.query;
  if (!auctionId) return res.status(400).json({ error: 'auctionId required' });
  const { exportSalesJournal } = require('./exports');
  // ?format=pdf — the printed register. Added 2026-09-01: the Auction
  // Downloads screen carried a "Journal" tile under PDF Downloads that served
  // the spreadsheet, because this route had no PDF branch at all.
  if (String(req.query.format || '').toLowerCase() === 'pdf') {
    const db = getDb();
    const pdf = await exportAnyPdf(db, 'sales_journal', auctionId, getSettingsFlat(db), { saleType });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', 'attachment; filename="SalesJournal.pdf"');
    res.setHeader('Access-Control-Expose-Headers', 'Content-Disposition');
    return res.send(pdf);
  }
  const buffer = await exportSalesJournal(getDb(), auctionId, saleType);
  // ?format=csv serves the Auction Downloads screen's "Sales CSV" tile; the
  // default stays XLSX so every existing caller is untouched.
  if (String(req.query.format || '').toLowerCase() === 'csv') {
    const csv = await xlsxToCsvBuffer(Buffer.from(buffer));
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="SalesJournal.csv"');
    res.setHeader('Access-Control-Expose-Headers', 'Content-Disposition');
    return res.send(Buffer.from(csv));
  }
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', 'attachment; filename="SalesJournal.xlsx"');
  res.send(Buffer.from(buffer));
});

app.get('/api/exports/purchase-journal', requireExport, async (req, res) => {
  const { auctionId, type } = req.query;
  if (!auctionId) return res.status(400).json({ error: 'auctionId required' });
  const baseName = type === 'agri' ? 'AgriBillJournal' : 'PurchaseJournal';
  // Was uncaught: this handler is async, so a throw inside it rejected with no
  // response written and the request hung until the client timed out. Now that
  // the Auction Downloads screen serves it as a tile, a builder error has to
  // come back as a readable 500 like every other export.
  try {
    const db = getDb();
    // ?format=pdf — the printed register, for the Journals screen's Export PDF
    // and the Auction Desk / Auction Manager PDF tiles. Same arrangement the
    // Sales Journal got above: one document per journal, served from here, so
    // the three surfaces cannot drift into printing variants of each other.
    if (String(req.query.format || '').toLowerCase() === 'pdf') {
      const kind = type === 'agri' ? 'agri' : 'dealer';
      const pdf = await exportAnyPdf(db, `purchase_journal_${kind}`, auctionId, getSettingsFlat(db), {});
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition',
        `attachment; filename="${baseName}_${anoForFilename(db, auctionId)}.pdf"`);
      res.setHeader('Access-Control-Expose-Headers', 'Content-Disposition');
      return res.send(pdf);
    }
    const { exportPurchaseJournal } = require('./exports');
    const buffer = await exportPurchaseJournal(db, auctionId, type || 'dealer');
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    // Trade number in the name — the tile is per-trade, and without it every
    // trade's download lands as the same "PurchaseJournal.xlsx". The Reports
    // screen is unaffected: exportJournal() names its own blob client-side and
    // never reads this header.
    res.setHeader('Content-Disposition',
      `attachment; filename="${baseName}_${anoForFilename(db, auctionId)}.xlsx"`);
    res.setHeader('Access-Control-Expose-Headers', 'Content-Disposition');
    res.send(Buffer.from(buffer));
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

