// Export the ticked (filtered) sales invoices as a compact list — Excel or
// PDF — with headers: Sale type, Inv no, Trade name, GSTIN, Bags, Qty, Bill
// amount. Body: { ids:[...], format:'xlsx'|'pdf' }.
app.post('/api/invoices/export-selected', requireExport, async (req, res) => {
  try {
    const db = getDb();
    const ids = (Array.isArray(req.body && req.body.ids) ? req.body.ids : [])
      .map(n => Number(n)).filter(Number.isFinite);
    if (!ids.length) return res.status(400).json({ error: 'No invoices selected' });
    const format = String(req.body.format || 'xlsx').toLowerCase();

    const placeholders = ids.map(() => '?').join(',');
    const rows = db.all(
      `SELECT sale, invo, buyer1, gstin, bag, qty, tot, lorry_no
         FROM invoices WHERE id IN (${placeholders})
        ORDER BY sale, invo`, ids);
    if (!rows.length) return res.status(404).json({ error: 'No matching invoices found' });

    const sum = (k) => rows.reduce((a, r) => a + (Number(r[k]) || 0), 0);

    // Group the selected invoices by their lorry number so each export shows
    // a "Lorry: <no>" sub-header above that lorry's invoices. Invoices with no
    // lorry set fall into a final "(not set)" group. Groups are ordered by
    // lorry number; the original ORDER BY sale, invo is preserved within each.
    const NO_LORRY = '(not set)';
    const groupsMap = new Map();
    for (const r of rows) {
      const key = String(r.lorry_no || '').trim() || NO_LORRY;
      if (!groupsMap.has(key)) groupsMap.set(key, []);
      groupsMap.get(key).push(r);
    }
    const groups = [...groupsMap.entries()]
      .sort(([a], [b]) => {
        if (a === NO_LORRY) return 1;              // "(not set)" always last
        if (b === NO_LORRY) return -1;
        return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
      })
      .map(([no, grpRows]) => ({ no, rows: grpRows }));

    if (format === 'pdf') {
      const columns = [
        { header: 'SALE',        key: 'sale',   width: 8  },
        { header: 'INVO',        key: 'invo',   width: 10 },
        { header: 'TRADE NAME',  key: 'buyer1', width: 30 },
        { header: 'GSTIN',       key: 'gstin',  width: 18 },
        { header: 'BAGS',        key: 'bag',    width: 8  },
        { header: 'QTY',         key: 'qty',    width: 12 },
        { header: 'BILL AMOUNT', key: 'tot',    width: 16 },
      ];
      // Flatten into section-banner rows + data rows. renderTablePdf draws a
      // full-width banner for any row shaped { _isSection:true, label }.
      const pdfRows = [];
      for (const g of groups) {
        pdfRows.push({ _isSection: true, label: `Lorry: ${g.no}` });
        for (const r of g.rows) pdfRows.push(r);
      }
      const totals = { sale: 'TOTAL', bag: sum('bag'), qty: sum('qty'), tot: sum('tot') };
      const buffer = await renderTablePdf({
        title: 'Sales Invoices',
        subtitle: `${rows.length} invoice(s)`,
        columns, rows: pdfRows, totals,
        companyHeader: getCompanyHeader(db),
      });
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', 'attachment; filename="SalesInvoices.pdf"');
      return res.send(buffer);
    }

    const cols = [
      { header: 'SALE TYPE',   key: 'sale',   width: 10 },
      { header: 'INV NO',      key: 'invo',   width: 12 },
      { header: 'TRADE NAME',  key: 'buyer1', width: 32 },
      { header: 'GSTIN',       key: 'gstin',  width: 20 },
      { header: 'BAGS',        key: 'bag',    width: 8  },
      { header: 'QTY',         key: 'qty',    width: 12, numFmt: '#,##0.000' },
      { header: 'BILL AMOUNT', key: 'tot',    width: 16, numFmt: '#,##0.00'  },
    ];
    // createExcelBuffer renders opts.sections as a titled group band then its
    // rows. Pass one section per lorry.
    const sections = groups.map(g => ({ title: `Lorry: ${g.no}`, rows: g.rows }));
    const buffer = await createExcelBuffer('SalesInvoices', cols, rows, {
      db, title: 'Sales Invoices', sections,
      grandTotal: { label: 'TOTAL', values: { bag: sum('bag'), qty: sum('qty'), tot: sum('tot') } },
    });
    res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
    res.setHeader('Content-Disposition', 'attachment; filename="SalesInvoices.xlsx"');
    res.send(Buffer.from(buffer));
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// ══════════════════════════════════════════════════════════════
// INVOICE PREVIEW (PREINVO.PRG) — dry-run, no save
// ══════════════════════════════════════════════════════════════
app.post('/api/invoices/preview/:auctionId', requireView, (req, res) => {
  const db = getDb(); const cfg = getSettingsFlat(db);
  const { saleType, buyerCode, type } = req.body;
  const noTI = (req.body.noTI === true || String(req.body.noTI || '').toLowerCase() === 'true' || Number(req.body.noTI) === 1) ? 1 : 0;
  // Optional lot subset — lets the Generate modal's Quick Preview show a
  // single split group (the active invoice) rather than the whole buyer.
  const lotNos = Array.isArray(req.body.lotNos)
    ? req.body.lotNos.map(x => String(x)).filter(x => x.trim() !== '')
    : null;

  // Auto-calculate any uncalculated lots first (read-only would be better but we need the data)
  const uncalc = db.all(`SELECT * FROM lots WHERE auction_id = ? AND amount > 0 AND (puramt IS NULL OR puramt = 0)`, [req.params.auctionId]);
  for (const lot of uncalc) {
    const c = calculateLot(lot, cfg);
    db.run(`UPDATE lots SET pqty=?,prate=?,puramt=?,com=?,sertax=?,cgst=?,sgst=?,igst=?,advance=?,balance=?,bilamt=?,refund=?,refud=?,isp_pqty=?,isp_prate=?,isp_puramt=?,asp_pqty=?,asp_prate=?,asp_puramt=? WHERE id=?`,
      [c.pqty,c.prate,c.puramt,c.com,c.sertax,c.cgst,c.sgst,c.igst,c.advance,c.balance,c.bilamt,c.refund||0,c.refud||0,c.isp_pqty||0,c.isp_prate||0,c.isp_puramt||0,c.asp_pqty||0,c.asp_prate||0,c.asp_puramt||0,lot.id]);
  }
  
  let invoice;
  if (type === 'purchase') {
    // buyerCode = sellerName for purchase. In lot-wise mode the modal sends the
    // single lot it is previewing, so the preview shows the document that will
    // actually be raised rather than the whole seller.
    invoice = buildPurchaseInvoice(db, req.params.auctionId, buyerCode, cfg, {
      lotNo: req.body.lotNo || (lotNos && lotNos.length === 1 ? lotNos[0] : ''),
      lotId: req.body.lotId,
      docNo: req.body.invoiceNo,
    });
  } else if (type === 'agri') {
    // In lot-wise mode the modal previews the single lot it is about to bill,
    // so the preview matches the document that will actually be raised.
    invoice = buildAgriBill(db, req.params.auctionId, buyerCode, cfg, {
      lotNo: req.body.lotNo || (lotNos && lotNos.length === 1 ? lotNos[0] : ''),
      lotId: req.body.lotId,
    });
    if (invoice && invoice.error) return res.status(404).json({ error: invoice.error });
  } else {
    // "All sale types" reaches here as a blank saleType. A single-buyer
    // preview needs one concrete type (it drives the lot filter + transport),
    // so derive the buyer's effective sale: an explicit stored value, else
    // L/I from the GSTIN — the same rule the buyer picker uses.
    let effSale = String(saleType || '').trim();
    if (!effSale) {
      const b = db.get('SELECT gstin, sale FROM buyers WHERE buyer = ?', [buyerCode]);
      effSale = (b && b.sale) ? String(b.sale).trim().toUpperCase() : '';
      if (!effSale) effSale = deriveSaleType(b ? b.gstin : '', cfg);
    }
    invoice = buildSalesInvoice(db, req.params.auctionId, buyerCode, effSale, cfg, { noTI, lotNos });
  }

  if (!invoice) return res.status(404).json({ error: 'No data found' });
  res.json({ preview: true, invoice });
});

// PRE-INVOICE PDF — renders the EXACT sales-invoice PDF (same builder + same
// renderer as the real Generate flow) for visual verification, WITHOUT
// persisting anything: no invoices INSERT, no lots.invo/sale UPDATE, and no
// invoice number consumed (a "PREVIEW" placeholder is stamped on the doc).
// Body: { saleType, buyerCode, noTI }.
app.post('/api/invoices/preview-pdf/:auctionId', requireView, async (req, res) => {
  try {
    const db = getDb(); const cfg = getSettingsFlat(db);
    const { saleType, buyerCode } = req.body;
    const noTI = (req.body.noTI === true || String(req.body.noTI || '').toLowerCase() === 'true' || Number(req.body.noTI) === 1) ? 1 : 0;
    // Optional split-group lot subset (Pre-Invoice screen).
    const pdfLotNos = Array.isArray(req.body.lotNos) ? req.body.lotNos.map(x => String(x)).filter(x => x.trim() !== '') : null;
    if (!saleType || !buyerCode) return res.status(400).json({ error: 'saleType and buyerCode are required' });

    // Same uncalculated-lot top-up the JSON preview + Generate flows do, so the
    // previewed figures match exactly what Generate would produce. This only
    // fills derived calc fields on already-priced lots; it never touches
    // invoice numbers or the invoices table.
    const uncalc = db.all(`SELECT * FROM lots WHERE auction_id = ? AND amount > 0 AND (puramt IS NULL OR puramt = 0)`, [req.params.auctionId]);
    for (const lot of uncalc) {
      const c = calculateLot(lot, cfg);
      db.run(`UPDATE lots SET pqty=?,prate=?,puramt=?,com=?,sertax=?,cgst=?,sgst=?,igst=?,advance=?,balance=?,bilamt=?,refund=?,refud=?,isp_pqty=?,isp_prate=?,isp_puramt=?,asp_pqty=?,asp_prate=?,asp_puramt=? WHERE id=?`,
        [c.pqty,c.prate,c.puramt,c.com,c.sertax,c.cgst,c.sgst,c.igst,c.advance,c.balance,c.bilamt,c.refund||0,c.refud||0,c.isp_pqty||0,c.isp_prate||0,c.isp_puramt||0,c.asp_pqty||0,c.asp_prate||0,c.asp_puramt||0,lot.id]);
    }

    const invoice = buildSalesInvoice(db, req.params.auctionId, buyerCode, saleType, cfg, { noTI, lotNos: (pdfLotNos && pdfLotNos.length) ? pdfLotNos : undefined });
    if (!invoice) return res.status(404).json({ error: `No lots found for buyer "${buyerCode}" in this auction.` });
    const auction = db.get('SELECT * FROM auctions WHERE id = ?', [req.params.auctionId]);
    const invoiceDate = (auction && auction.date) || new Date().toISOString().slice(0, 10);

    // Placeholder invoice number — nothing is reserved or stored.
    // Honour the layout selected in Settings (letterhead/modern → HTML engine,
    // classic/pdfkit → legacy PDFKit) so the pre-invoice PDF matches the real
    // Generate/print output and the inline HTML preview. ?template=<id>
    // overrides for this one download.
    const tplChoice = String(req.query.template || req.body.template || '').trim();
    const useHtml = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'sales_invoice_engine', templateKey: 'sales_invoice_template', tplChoice });
    let pdf;
    if (useHtml) {
      const { generateSalesInvoiceHtmlPDF } = require('./pdf/render-html-invoice');
      const cfg2 = tplChoice ? { ...cfg, sales_invoice_template: tplChoice } : cfg;
      pdf = await generateSalesInvoiceHtmlPDF(invoice, cfg2, saleType, 'PREVIEW', invoiceDate);
    } else {
      pdf = await generateSalesInvoicePDF(invoice, cfg, saleType, 'PREVIEW', invoiceDate);
    }
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="PreInvoice_${saleType}_${String(buyerCode).replace(/[^A-Za-z0-9]/g,'')}.pdf"`);
    res.send(pdf);
  } catch (e) {
    console.error('Pre-invoice PDF error:', e);
    res.status(500).json({ error: 'Pre-invoice generation failed: ' + e.message });
  }
});

// Lots in a trade that will NOT appear on any sales invoice, so the
// Pre-Invoice screen can account for the whole trade before anything is
// generated. State lives in `lots.code` — the same marker the invoice
// gate (`notWD`) and the carry-forward flow already read:
//
//   'WD'          → WITHDRAWN, pulled before the sale
//   'NA' or blank → NOT AUCTIONED (booked but never went under the hammer)
//
// `code` is checked BEFORE `amount`: a withdrawn lot can still carry its
// pre-withdrawal amount (real trades hold both shapes), so an amount-based
// test would file those under "sold". Equally, "not auctioned" is decided
// by the code and NOT by amount <= 0 — before a price import every lot has
// amount 0, and calling the whole trade "not auctioned" would be nonsense.
function excludedLots(db, auctionId) {
  const rows = db.all(
    `SELECT lot_no,
            COALESCE(name,'')   AS seller,
            COALESCE(branch,'') AS branch,
            COALESCE(bags,0)    AS bags,
            COALESCE(qty,0)     AS qty,
            COALESCE(amount,0)  AS amount,
            COALESCE(reserved,0) AS reserved,
            UPPER(TRIM(COALESCE(code,''))) AS code
       FROM lots
      WHERE auction_id = ?
        AND (UPPER(TRIM(COALESCE(code,''))) IN ('WD','NA')
             OR TRIM(COALESCE(code,'')) = '')
      ORDER BY CAST(lot_no AS INTEGER), lot_no`,
    [auctionId]
  ) || [];
  const withdrawn = [], notAuctioned = [];
  for (const l of rows) (l.code === 'WD' ? withdrawn : notAuctioned).push(l);
  const sum = (arr, k) => arr.reduce((s, r) => s + (Number(r[k]) || 0), 0);
  return {
    withdrawn,
    notAuctioned,
    totals: {
      withdrawnLots:    withdrawn.length,
      withdrawnBags:    sum(withdrawn, 'bags'),
      withdrawnQty:     sum(withdrawn, 'qty'),
      notAuctionedLots: notAuctioned.length,
      notAuctionedBags: sum(notAuctioned, 'bags'),
      notAuctionedQty:  sum(notAuctioned, 'qty'),
    },
  };
}

// PRE-INVOICE — powers the Pre-Invoice screen. Always returns the lightweight
// `buyers` list (one entry per party, with its effective sale type) so the
// screen can offer a party selector. `previews` (the full bill-to/ship-to/
// amounts) is built ONLY for the selected buyer (?buyer=CODE) or for the whole
// list on explicit ?all=1 — so viewing one party doesn't build every invoice.
// Nothing is generated, numbered, or persisted. Query: ?sale=L&noTI=0&buyer=X.
app.get('/api/invoices/preview-all/:auctionId', requireView, (req, res) => {
  try {
    const db = getDb(); const cfg = getSettingsFlat(db);
    const aid = req.params.auctionId;
    const saleFilter = String(req.query.sale || '').trim().toUpperCase();
    const noTI = (req.query.noTI === '1' || String(req.query.noTI || '').toLowerCase() === 'true') ? 1 : 0;
    const buyerParam = String(req.query.buyer || '').trim();
    const wantAll = req.query.all === '1' || String(req.query.all || '').toLowerCase() === 'true';

    // Every buyer with priced, non-reserved lots — resolve each one's effective
    // sale type (a sale stamped on the lots wins, else the buyer default, else
    // Local; mirrors eligible-buyers' COALESCE) and apply the sale-type filter.
    const buyerCodes = db.all(
      `SELECT DISTINCT l.buyer FROM lots l
        WHERE l.auction_id = ? AND l.buyer IS NOT NULL AND l.buyer != ''
          AND l.amount > 0 AND (l.reserved IS NULL OR l.reserved = 0)
        ORDER BY l.buyer`, [aid]).map(r => r.buyer);

    const buyers = [];
    for (const code of buyerCodes) {
      const lotSale = db.get(`SELECT sale FROM lots WHERE auction_id = ? AND buyer = ? AND amount > 0 AND sale IS NOT NULL AND sale != '' LIMIT 1`, [aid, code]);
      const bRow = db.get('SELECT buyer1, code FROM buyers WHERE buyer = ? LIMIT 1', [code]);
      const eff = String((lotSale && lotSale.sale) || (bRow && bRow.sale) || 'L').toUpperCase();
      if (saleFilter && eff !== saleFilter) continue;
      buyers.push({ code, name: (bRow && bRow.buyer1) || code, buyerCode: (bRow && bRow.code) || '', saleType: eff });
    }
    // Show buyers ordered by sale type (I before L, then others), buyer code
    // within each — mirrors the generation picker (eligible-buyers).
    buyers.sort(_bySaleThenBuyer);

    // Decide which buyers to fully build a preview for.
    const toBuild = buyerParam
      ? buyers.filter(b => b.code === buyerParam)
      : (wantAll ? buyers : []);

    const previews = [];
    if (toBuild.length) {
      // Only top up uncalculated priced lots when we're actually building a
      // preview — keeps the buyers-list call side-effect-free.
      const uncalc = db.all(`SELECT * FROM lots WHERE auction_id = ? AND amount > 0 AND (puramt IS NULL OR puramt = 0)`, [aid]);
      for (const lot of uncalc) {
        const c = calculateLot(lot, cfg);
        db.run(`UPDATE lots SET pqty=?,prate=?,puramt=?,com=?,sertax=?,cgst=?,sgst=?,igst=?,advance=?,balance=?,bilamt=?,refund=?,refud=?,isp_pqty=?,isp_prate=?,isp_puramt=?,asp_pqty=?,asp_prate=?,asp_puramt=? WHERE id=?`,
          [c.pqty,c.prate,c.puramt,c.com,c.sertax,c.cgst,c.sgst,c.igst,c.advance,c.balance,c.bilamt,c.refund||0,c.refud||0,c.isp_pqty||0,c.isp_prate||0,c.isp_puramt||0,c.asp_pqty||0,c.asp_prate||0,c.asp_puramt||0,lot.id]);
      }
      for (const b of toBuild) {
        // Split by invoice_group (set in Price Entry) → one preview per group,
        // exactly like generate-all produces. buildSalesInvoice's own lot
        // filter is mirrored here so the grouping lines up.
        const groupRows = db.all(
          `SELECT COALESCE(invoice_group,0) AS g, lot_no
             FROM lots
            WHERE auction_id = ? AND buyer = ? AND amount > 0
              AND (reserved IS NULL OR reserved = 0)
              AND (sale IS NULL OR sale = '' OR sale = ?)
            ORDER BY CAST(lot_no AS INTEGER), lot_no`,
          [aid, b.code, b.saleType]
        );
        const gmap = new Map();
        for (const gr of groupRows) { const g = Number(gr.g) || 0; if (!gmap.has(g)) gmap.set(g, []); gmap.get(g).push(String(gr.lot_no)); }
        const gkeys = Array.from(gmap.keys()).sort((x, y) => x - y);
        const isMulti = gkeys.length > 1;
        for (const gk of gkeys) {
          const lotNos = gmap.get(gk);
          const inv = buildSalesInvoice(db, aid, b.code, b.saleType, cfg, { noTI, lotNos });
          if (!inv) continue;
          previews.push({ buyerCode: b.code, saleType: b.saleType, buyer: inv.buyer,
            summary: inv.summary, lineItems: inv.lineItems,
            splitGroup: isMulti ? gk : null, lotNos });
        }
      }
    }
    // Which engine the selected sales-invoice layout resolves to. The inline
    // preview uses this to stay consistent with "Open PDF": 'html' layouts
    // (letterhead/modern) render via the fast HTML preview; 'pdfkit'
    // (classic) embeds the actual PDF so both show the identical layout.
    const salesEngine = require('./pdf/engine-toggle').resolveWantHtml(cfg, {
      engineKey: 'sales_invoice_engine', templateKey: 'sales_invoice_template' }) ? 'html' : 'pdfkit';
    res.json({ buyers, previews, salesEngine, excluded: excludedLots(db, aid) });
  } catch (e) {
    console.error('Pre-invoice preview-all error:', e);
    res.status(500).json({ error: e.message });
  }
});

// ══════════════════════════════════════════════════════════════
// PAYMENTS (PAYCHECK.PRG)
// ══════════════════════════════════════════════════════════════
app.get('/api/payments/:auctionId', requireView, (req, res) => {
  const db = getDb();
  const cfg = getSettingsFlat(db);
  // `includeUnpriced=1` lists sellers whose lots aren't priced yet so the
  // operator can pre-enter advances before price import. Also auto-fall back
  // to it when the normal (priced-only) roll-up is empty — that's the
  // pre-import state, where the screen would otherwise show nothing to act on.
  const wantUnpriced = req.query.includeUnpriced === '1' || req.query.includeUnpriced === 'true';
  let summary = getPaymentSummary(db, req.params.auctionId, req.query.state, cfg, wantUnpriced);
  if (!wantUnpriced && (!Array.isArray(summary) || summary.length === 0)) {
    summary = getPaymentSummary(db, req.params.auctionId, req.query.state, cfg, true);
  }
  res.json(summary);
});

// ══════════════════════════════════════════════════════════════
// LOT-WISE PAYMENTS (Settings → Flags → "Lot-wise Payments Screen")
// ══════════════════════════════════════════════════════════════
// Why isn't the lot I typed in the results?
//
// An empty table after typing "001" is a dead end — the operator can't tell
// a withdrawn lot from a typo. For every lot number asked for that did NOT
// come back, look it up in the trade ignoring the search's own filters and
// name the actual reason. Only runs when lot numbers were typed.
//
// Reasons, in the order they're tested (first match wins, because they can
// overlap — a withdrawn lot is also unpriced):
//   missing        no lot with that number in this trade at all
//   withdrawn      lots.code = 'WD' — pulled before the sale
//   not_auctioned  lots.code = 'NA' or blank — never went under the hammer
//   unpriced       sold but amount is still 0 (price import not run)
//   paid           already marked paid, so out of the payable set
//   seller_filter  payable, but the Seller name box excluded it
//   link_filter    payable, but the Show-unlinked toggle excluded it
// Parse the lot-search box into match tokens. Accepts a comma/whitespace list
// mixing single lots and ranges — e.g. "010-020, 021,022" → lots 10..20 plus
// 21 and 22. Ranges are numeric and inclusive; "020-010" is normalised. A very
// wide range is capped so a typo like "1-999999" can't blow up the query.
//   • tokens   — every lot to match (ranges expanded), for the WHERE clause.
//   • explicit — only the individually-typed lots, for the "why isn't lot X
//     here?" report. Range-expanded numbers are left out so a gap inside a
//     range isn't flagged as a missing lot.
function parseLotSearch(raw) {
  const RANGE_CAP = 10000;
  const tokens = new Set();
  const explicit = new Set();
  for (const piece of String(raw || '').split(/[,\s]+/).map(s => s.trim()).filter(Boolean)) {
    const m = /^(\d+)\s*-\s*(\d+)$/.exec(piece);
    if (m) {
      let lo = parseInt(m[1], 10), hi = parseInt(m[2], 10);
      if (lo > hi) { const t = lo; lo = hi; hi = t; }
      if (hi - lo > RANGE_CAP) hi = lo + RANGE_CAP;       // guard against typos
      for (let n = lo; n <= hi; n++) tokens.add(String(n));
    } else {
      tokens.add(piece);
      explicit.add(piece);
    }
  }
  return { tokens: [...tokens], explicit: [...explicit] };
}

function explainMissingLots(db, auctionId, lotTokens, ctx) {
  if (!lotTokens || !lotTokens.length) return [];
  const { seller, link, status, finalIds } = ctx;
  // Which status bucket a lot that did NOT come back falls in — the same rule
  // the search itself applies, asked directly because these lots are not in
  // the caller's result set to read it off. Only consulted when the status
  // filter is narrowed, so the ordinary search pays nothing for it.
  const lotStatus = (l) => {
    if (l.paid_at) return 'paid';
    let adv = 0;
    try {
      const a = db.get('SELECT advance FROM lot_advances WHERE lot_id = ?', [l.id]);
      adv = a ? Number(a.advance) || 0 : 0;
    } catch (_) { /* table missing on an old DB — no advances */ }
    return adv > 0 ? 'advance' : 'unpaid';
  };
  // Does an account resolve for this lot? Asked directly rather than through
  // the caller's prebuilt bank map — that map only covers sellers who made it
  // into the results, and the lots being explained here did not.
  const lotIsLinked = (l) => {
    // A pin only counts when it resolves to an account this lot's seller
    // owns — a dead or inherited bank_id routes nowhere, so reporting the lot
    // as "has an account" would explain away a genuinely unpayable lot.
    if (bankBelongsToTrader(db, l.bank_id, l.trader_id)) return true;
    if (l.trader_id == null) return false;
    const has = db.get('SELECT 1 AS x FROM trader_banks WHERE trader_id = ? LIMIT 1', [l.trader_id]);
    if (has) return true;
    const t = db.get('SELECT acctnum, ifsc FROM traders WHERE id = ?', [l.trader_id]);
    return !!(t && (String(t.acctnum || '').trim() || String(t.ifsc || '').trim()));
  };
  const out = [];
  for (const token of lotTokens) {
    // Same verbatim-or-numeric match the main query uses, so a token can't
    // be reported missing merely because of leading-zero spelling.
    const isNum = /^\d+$/.test(token);
    const rows = db.all(
      `SELECT id, lot_no, name, code, amount, paid, paid_at, bank_id, trader_id
         FROM lots
        WHERE auction_id = ?
          AND (TRIM(lot_no) = ?${isNum ? ' OR CAST(lot_no AS INTEGER) = ?' : ''})
        ORDER BY CAST(lot_no AS INTEGER), lot_no`,
      isNum ? [auctionId, token, parseInt(token, 10)] : [auctionId, token]
    ) || [];
    if (!rows.length) { out.push({ lot: token, reason: 'missing' }); continue; }
    // A lot number is unique within a trade, but stay tolerant: if ANY row
    // for this token made it into the results, the token is answered.
    if (rows.some(r => finalIds.has(r.id))) continue;
    const l = rows[0];
    const code = String(l.code || '').trim().toUpperCase();
    let reason;
    if (code === 'WD') reason = 'withdrawn';
    else if (code === 'NA' || code === '') reason = 'not_auctioned';
    else if (!(Number(l.amount) > 0)) reason = 'unpriced';
    else if (String(l.paid || '').trim() !== '') reason = 'paid';
    else if (seller && !String(l.name || '').toUpperCase().includes(seller.toUpperCase())) reason = 'seller_filter';
    // Checked BEFORE the link fallback: with a status filter on, that fallback
    // would blame the bank-account toggle for an exclusion it had no part in.
    else if (status && status !== 'all' && lotStatus(l) !== status) reason = 'status_filter';
    else reason = 'link_filter';
    const entry = { lot: String(l.lot_no || token).trim(), reason, seller: l.name || '' };
    // For either toggle, say which side the lot is on so the fix is obvious.
    if (reason === 'link_filter') {
      entry.linked = lotIsLinked(l);
      entry.wanted = link;
    }
    if (reason === 'status_filter') {
      entry.status = lotStatus(l);
      entry.wanted = status;
    }
    out.push(entry);
  }
  return out;
}

// Lot-level counterpart to /api/payments/:auctionId. The classic screen
// rolls a trade up per seller; this one answers "these specific lots —
// where does each one get paid, and how much?".
//
// Deliberately search-driven: the client only calls this when the
// operator presses Search, so nothing is listed until they say which
// lots they want. An EMPTY search (no seller, no lot numbers) is still
// allowed and returns the whole trade — that's what makes
// `link=unlinked` useful as a "every lot I cannot pay yet" worklist.
//
// Query params
//   seller  partial, case-insensitive match on lots.name
//   lots    comma-separated lot numbers. Matched both verbatim and
//           numerically, so "24" finds lot "024" and vice versa.
//   link    all (default) | linked | unlinked — see routeOfLot below.
//   status  all (default) | paid | advance | unpaid — where the lot stands in
//           the payment run. The three buckets PARTITION the result: a lot is
//           `paid` once it carries a paid stamp (whether or not an advance was
//           taken against it first — the advance came off that payment, so the
//           lot is done either way), `advance` when it is still owed but part
//           of it has already gone out, and `unpaid` when nothing has moved.
//           Counted that way too, so the three counts always add up to the
//           number of matching lots.
//
// The lot set matches the bank-payment export's (amount > 0, not marked
// paid) so what is listed here is exactly what an export of it would pay.
app.get('/api/payments/lots/:auctionId', requireView, (req, res) => {
  try {
    const db = getDb();
    const auctionId = Number(req.params.auctionId);
    if (!auctionId) return res.status(400).json({ error: 'auctionId is required' });

    const seller = String(req.query.seller || '').trim();
    const link = String(req.query.link || 'all').trim().toLowerCase();
    if (!['all', 'linked', 'unlinked'].includes(link)) {
      return res.status(400).json({ error: 'link must be one of: all, linked, unlinked' });
    }
    const status = String(req.query.status || 'all').trim().toLowerCase();
    if (!['all', 'paid', 'advance', 'unpaid'].includes(status)) {
      return res.status(400).json({ error: 'status must be one of: all, paid, advance, unpaid' });
    }
    // Lot tokens: a comma/whitespace list that may mix single lots and ranges,
    // e.g. "010-020, 021,022". Ranges are expanded for matching; only the
    // individually-typed lots feed the missing-lot report.
    const { tokens: lotTokens, explicit: explicitTokens } = parseLotSearch(req.query.lots);

    const where = [`l.auction_id = ?`, `l.amount > 0`, `(l.paid IS NULL OR l.paid = '')`];
    const params = [auctionId];
    if (seller) {
      // Name substring, or — when the text reads as a phone number — the
      // seller's number, digits-only (so "+91 97907 44444", "97907-44444" and
      // "9790744444" are one query). Same rule as every other seller search on
      // the app; see smartPhoneDigits.
      //
      // Both the lot's own copy AND the seller master are matched: lots.tel is
      // a booking-time snapshot that trader-lot-sync refuses to refresh once
      // the lot is invoiced, so a number added to the master afterwards lives
      // only there — and this screen is where you go to pay that seller.
      const ors = [`UPPER(l.name) LIKE ?`];
      params.push(`%${seller.toUpperCase()}%`);
      const phone = smartPhoneDigits(seller);
      if (phone) {
        ors.push(`${smartPhoneSql('l.tel')} LIKE ?`);
        params.push(`%${phone}%`);
        ors.push(`EXISTS (SELECT 1 FROM traders t
                           WHERE t.id = l.trader_id
                             AND (${smartPhoneSql('t.tel')} LIKE ? OR ${smartPhoneSql('t.whatsapp')} LIKE ?))`);
        params.push(`%${phone}%`, `%${phone}%`);
      }
      where.push(`(${ors.join(' OR ')})`);
    }
    if (lotTokens.length) {
      // Verbatim match OR numeric match — "024" and "24" are the same lot to
      // an operator, and both spellings exist across imported trades.
      const ph = lotTokens.map(() => '?').join(',');
      const numeric = lotTokens.filter(t => /^\d+$/.test(t));
      let clause = `TRIM(l.lot_no) IN (${ph})`;
      params.push(...lotTokens);
      if (numeric.length) {
        clause += ` OR CAST(l.lot_no AS INTEGER) IN (${numeric.map(() => '?').join(',')})`;
        params.push(...numeric.map(t => parseInt(t, 10)));
      }
      where.push(`(${clause})`);
    }

    // Ordered by LOT NUMBER, not by seller — the operator reads this screen
    // against a lot list. The bank export mirrors it (orderByLot below), so
    // the exported sheet comes out in the same order as the rows on screen.
    // Numeric cast first so "9" precedes "10"; the raw lot_no breaks ties for
    // non-numeric lot numbers, which all cast to 0.
    const lots = db.all(
      `SELECT l.id, l.lot_no, l.name, l.trader_id, l.branch, l.qty,
              l.balance AS payable, l.amount, l.bank_id, l.immediate_payment,
              l.locked_at,
              -- Paid-out marker (lot-wise Payments export). Non-NULL rows stay
              -- in the list but are badged "Paid on …", tinted, and locked out
              -- of selection / re-export on the client.
              l.paid_at
         FROM lots l
        WHERE ${where.join(' AND ')}
        ORDER BY CAST(l.lot_no AS INTEGER), l.lot_no`,
      params
    ) || [];

    // Advances already paid against these lots ("Pay Advance" on this screen).
    // Read separately rather than joined so a DB that predates the table
    // degrades to "no advances" instead of failing the whole search.
    const advByLot = {};
    try {
      for (const a of db.all(
        `SELECT lot_id, advance, bank_id, paid_at FROM lot_advances WHERE auction_id = ?`,
        [auctionId]) || []) {
        advByLot[a.lot_id] = a;
      }
    } catch (_) { /* table missing on an old DB — no advances to net off */ }

    // Every account of every seller in the result — the client renders one
    // dropdown per row from this, and re-renders after adding an account.
    const traderIds = [...new Set(lots.map(l => l.trader_id).filter(id => id != null))];
    const banksByTrader = {};
    const legacyByTrader = {};
    if (traderIds.length) {
      const ph = traderIds.map(() => '?').join(',');
      const banks = db.all(
        `SELECT id, trader_id, bank_name, branch, acctnum, ifsc, holder_name, account_type, is_default
           FROM trader_banks WHERE trader_id IN (${ph})
          ORDER BY trader_id, is_default DESC, id`,
        traderIds
      ) || [];
      for (const b of banks) (banksByTrader[b.trader_id] = banksByTrader[b.trader_id] || []).push(b);
      // Legacy single-account sellers: the account lives on the traders row
      // itself with no trader_banks row to point a lot's bank_id at. The
      // bank-payment export still routes to it, so it counts as linked — it
      // just can't be picked per lot until a real account is added.
      const legacy = db.all(
        `SELECT id, acctnum, ifsc, holder_name FROM traders WHERE id IN (${ph})`, traderIds) || [];
      for (const t of legacy) {
        if (!banksByTrader[t.id] && (String(t.acctnum || '').trim() || String(t.ifsc || '').trim())) {
          legacyByTrader[t.id] = { acctnum: t.acctnum || '', ifsc: t.ifsc || '', holder_name: t.holder_name || '' };
        }
      }
    }

    // Where a lot's payment actually routes, in the same order the export
    // resolves it:
    //   explicit — lots.bank_id points at a live account
    //   default  — no bank_id, but the seller has accounts (first/default wins)
    //   legacy   — no trader_banks rows, account held on the traders row
    //   none     — nothing to pay into. THIS is what "unlinked" means.
    const routeOfLot = (l) => {
      const banks = banksByTrader[l.trader_id] || [];
      if (l.bank_id != null && banks.some(b => b.id === l.bank_id)) return 'explicit';
      if (banks.length) return 'default';
      if (legacyByTrader[l.trader_id]) return 'legacy';
      return 'none';
    };
    let out = lots.map(l => {
      const route = routeOfLot(l);
      const banks = banksByTrader[l.trader_id] || [];
      // The account this lot pays into today — explicit pick, else the
      // seller's default. Null for legacy/none (no account row to name).
      const effective = (route === 'explicit')
        ? banks.find(b => b.id === l.bank_id)
        : (route === 'default' ? (banks.find(b => b.is_default) || banks[0]) : null);
      // Advance already paid against THIS lot. `payable` is reported net of it
      // — it is what still has to go out — with the pre-advance figure kept as
      // `payable_gross` so the row can show both. Clamped at 0: an advance can
      // never be written above the lot's balance (the endpoint rejects that),
      // but a re-price afterwards could lower the balance under it, and a
      // negative payable is not a thing the bank can pay.
      const adv = advByLot[l.id] || null;
      const gross = Number(l.payable) || 0;
      const advance = adv ? Math.max(0, Number(adv.advance) || 0) : 0;
      return {
        ...l,
        qty: Number(l.qty) || 0,
        payable: Math.max(0, gross - advance),
        payable_gross: gross,
        advance,
        advance_at: adv ? (adv.paid_at || '') : '',
        advance_bank_id: adv && adv.bank_id != null ? Number(adv.bank_id) : null,
        route,
        linked: route !== 'none',
        effectiveBankId: effective ? effective.id : null,
        // An explicit bank_id whose account has since been deleted — surfaced
        // rather than silently reading as "follows the default".
        staleBankId: (l.bank_id != null && !banks.some(b => b.id === l.bank_id)) ? l.bank_id : null,
      };
    });

    // Counts over the whole match, taken BEFORE either filter narrows it, so
    // the client can say "12 of 40 matching lots have no account" and label
    // each status option with what picking it would show.
    const totalMatched = out.length;
    const unlinkedCount = out.filter(l => !l.linked).length;
    // Where each lot stands in the payment run. Written once here so the
    // filter, the counts and the missing-lot explanation all read the same
    // rule; see the route doc above for why a paid lot is `paid` even when an
    // advance was taken against it first.
    const statusOf = (l) => l.paid_at ? 'paid' : (Number(l.advance) > 0 ? 'advance' : 'unpaid');
    const statusCounts = { paid: 0, advance: 0, unpaid: 0 };
    for (const l of out) statusCounts[statusOf(l)]++;
    if (link === 'linked')   out = out.filter(l => l.linked);
    if (link === 'unlinked') out = out.filter(l => !l.linked);
    if (status !== 'all')    out = out.filter(l => statusOf(l) === status);
    const finalIds = new Set(out.map(l => l.id));

    res.json({
      auctionId,
      link,
      status,
      count: out.length,
      totalMatched,
      unlinkedCount,
      statusCounts,
      lots: out,
      banksByTrader,
      legacyByTrader,
      // Per-token explanation for lot numbers that were asked for but are
      // not in `lots` — "001 is withdrawn" beats an empty table. Only the
      // individually-typed lots are explained; gaps inside a range are not
      // flagged as missing.
      missing: explainMissingLots(db, auctionId, explicitTokens, { seller, link, status, finalIds }),
    });
  } catch (e) {
    console.error('lot-wise payments search error:', e);
    res.status(500).json({ error: 'Lot search failed: ' + (e.message || e) });
  }
});

// Mark lots PAID (lot-wise Payments screen) — called right after their bank
// payment file is exported. Stamps lots.paid_at with the local datetime, once:
// a lot already paid keeps its original date (never re-stamped, so a re-export
// of a mixed selection can't move a paid lot's date). Body: { lotIds:[...] }.
// Scoped to the auction so a stray id from another trade is ignored. Returns
// the number newly marked and the date used, so the client can badge them.
app.post('/api/payments/lots/:auctionId/mark-paid', requireLotWrite, (req, res) => {
  try {
    const db = getDb();
    const auctionId = Number(req.params.auctionId);
    if (!auctionId) return res.status(400).json({ error: 'auctionId is required' });
    const ids = Array.isArray(req.body && req.body.lotIds)
      ? [...new Set(req.body.lotIds.map(n => parseInt(n, 10)).filter(Number.isFinite))]
      : [];
    if (!ids.length) return res.status(400).json({ error: 'lotIds (array) is required' });
    const paidAt = db.get(`SELECT datetime('now','localtime') AS d`).d;
    const ph = ids.map(() => '?').join(',');
    db.run(
      `UPDATE lots SET paid_at = ?
        WHERE auction_id = ? AND id IN (${ph}) AND paid_at IS NULL`,
      [paidAt, auctionId, ...ids]
    );
    // Report the count actually marked (already-paid ids are left untouched).
    const marked = db.get(
      `SELECT COUNT(*) AS c FROM lots WHERE auction_id = ? AND id IN (${ph}) AND paid_at = ?`,
      [auctionId, ...ids, paidAt]
    ).c;
    res.json({ success: true, marked, paidAt });
  } catch (e) {
    console.error('mark-paid error:', e);
    res.status(500).json({ error: 'Mark paid failed: ' + (e.message || e) });
  }
});

// Undo mark-paid — clears paid_at so the lots become selectable/exportable
// again. Admin only: reversing a settled payment is a supervisory action, not
// part of the normal export flow. Body: { lotIds: [...] }.
app.post('/api/payments/lots/:auctionId/unmark-paid', requireAdmin, (req, res) => {
  try {
    const db = getDb();
    const auctionId = Number(req.params.auctionId);
    if (!auctionId) return res.status(400).json({ error: 'auctionId is required' });
    const ids = Array.isArray(req.body && req.body.lotIds)
      ? [...new Set(req.body.lotIds.map(n => parseInt(n, 10)).filter(Number.isFinite))]
      : [];
    if (!ids.length) return res.status(400).json({ error: 'lotIds (array) is required' });
    const ph = ids.map(() => '?').join(',');
    // Count what was actually paid BEFORE clearing, so the caller learns how
    // many rows the undo touched (unpaid ids are no-ops).
    const cleared = db.get(
      `SELECT COUNT(*) AS c FROM lots WHERE auction_id = ? AND id IN (${ph}) AND paid_at IS NOT NULL`,
      [auctionId, ...ids]
    ).c;
    db.run(
      `UPDATE lots SET paid_at = NULL
        WHERE auction_id = ? AND id IN (${ph}) AND paid_at IS NOT NULL`,
      [auctionId, ...ids]
    );
    res.json({ success: true, cleared });
  } catch (e) {
    console.error('unmark-paid error:', e);
    res.status(500).json({ error: 'Unmark paid failed: ' + (e.message || e) });
  }
});

// ── Pay Advance, lot-wise ────────────────────────────────────────────────
// Records an advance already paid against individual LOTS, from the lot-wise
// Payments screen. Each item is { lotId, advance, bankId? }:
//
//   advance > 0  upsert the lot's advance (one row per lot) and stamp when it
//                was paid. Re-paying a lot that already carries an advance
//                REPLACES the figure rather than adding to it — the modal
//                pre-fills the current value, so what the operator sees in the
//                box is what the lot ends up with.
//   advance = 0  clear the lot's advance entirely.
//
// `bankId` is the account the money actually went to. It is optional (a seller
// with no accounts on file can still have an advance recorded against them),
// but when supplied it must belong to the LOT'S OWN seller: trader_banks ids
// are recycled as sellers are re-saved, so an id from another seller would
// record this lot's money against a stranger's account.
//
// The whole batch is validated before anything is written — a half-applied
// "pay advance on 40 lots" is far worse than an outright rejection.
app.post('/api/payments/lots/:auctionId/advance', requireLotWrite, (req, res) => {
  try {
    const db = getDb();
    const auctionId = Number(req.params.auctionId);
    if (!auctionId) return res.status(400).json({ error: 'auctionId is required' });
    const items = Array.isArray(req.body && req.body.items) ? req.body.items : [];
    if (!items.length) return res.status(400).json({ error: 'items (array) is required' });

    // Collapse duplicate lotIds — last one typed wins, matching the modal,
    // where a lot appears on exactly one row.
    const wanted = new Map();
    for (const it of items) {
      const lotId = parseInt(it && it.lotId, 10);
      if (!Number.isFinite(lotId)) continue;
      const advance = Math.round((Number(it.advance) || 0) * 100) / 100;
      if (!(advance >= 0)) return res.status(400).json({ error: `Advance for lot id ${lotId} is not a number` });
      const rawBank = (it.bankId === '' || it.bankId == null) ? null : parseInt(it.bankId, 10);
      wanted.set(lotId, { lotId, advance, bankId: Number.isFinite(rawBank) ? rawBank : null });
    }
    if (!wanted.size) return res.status(400).json({ error: 'No valid lot ids in items' });

    const ids = [...wanted.keys()];
    const ph = ids.map(() => '?').join(',');
    const rows = db.all(
      `SELECT id, lot_no, name, trader_id, balance, amount, paid_at
         FROM lots WHERE auction_id = ? AND id IN (${ph})`,
      [auctionId, ...ids]) || [];
    const lotById = new Map(rows.map(r => [r.id, r]));

    // Which trader_banks rows each affected seller actually owns.
    const traderIds = [...new Set(rows.map(r => r.trader_id).filter(t => t != null))];
    const ownedBanks = new Set();
    if (traderIds.length) {
      const tph = traderIds.map(() => '?').join(',');
      for (const b of db.all(
        `SELECT id, trader_id FROM trader_banks WHERE trader_id IN (${tph})`, traderIds) || []) {
        ownedBanks.add(`${b.trader_id}:${b.id}`);
      }
    }

    const problems = [];
    for (const w of wanted.values()) {
      const lot = lotById.get(w.lotId);
      if (!lot) { problems.push(`Lot id ${w.lotId} is not in this trade`); continue; }
      const where = `lot ${String(lot.lot_no || w.lotId)}`;
      if (lot.paid_at) { problems.push(`${where} is already marked paid — undo the paid stamp first`); continue; }
      if (w.advance === 0) continue;                     // clearing needs no further checks
      const balance = Math.round((Number(lot.balance) || 0) * 100) / 100;
      if (!(balance > 0)) { problems.push(`${where} has nothing payable yet — price it before paying an advance`); continue; }
      if (w.advance > balance) {
        problems.push(`${where}: advance ${w.advance.toFixed(2)} is more than its payable ${balance.toFixed(2)}`);
        continue;
      }
      if (w.bankId != null && !ownedBanks.has(`${lot.trader_id}:${w.bankId}`)) {
        problems.push(`${where}: the chosen bank account does not belong to ${lot.name || 'this seller'}`);
      }
    }
    if (problems.length) return res.status(400).json({ error: problems.join('; '), problems });

    const paidAt = db.get(`SELECT datetime('now','localtime') AS d`).d;
    let saved = 0, cleared = 0;
    for (const w of wanted.values()) {
      if (w.advance > 0) {
        db.run(
          `INSERT INTO lot_advances (lot_id, auction_id, advance, bank_id, paid_at, updated_at)
           VALUES (?, ?, ?, ?, ?, ?)
           ON CONFLICT(lot_id)
           DO UPDATE SET auction_id = excluded.auction_id, advance = excluded.advance,
                         bank_id = excluded.bank_id, paid_at = excluded.paid_at,
                         updated_at = excluded.updated_at`,
          [w.lotId, auctionId, w.advance, w.bankId, paidAt, paidAt]);
        saved++;
      } else {
        const had = db.get('SELECT lot_id FROM lot_advances WHERE lot_id = ?', [w.lotId]);
        if (had) { db.run('DELETE FROM lot_advances WHERE lot_id = ?', [w.lotId]); cleared++; }
      }
    }
    res.json({ success: true, saved, cleared, paidAt });
  } catch (e) {
    console.error('lot advance save error:', e);
    res.status(500).json({ error: 'Advance save failed: ' + (e.message || e) });
  }
});

// Set (or clear) a seller's advance for this auction. The advance is
// deducted from the Payments payable (Payable = Net − Advance) and flows
// into the payment statement, bank export and party-wise reports via
// getPaymentSummary/getBankPaymentData. Body: { name, advance }.
app.post('/api/payments/:auctionId/advance', requireLotWrite, (req, res) => {
  try {
    const db = getDb();
    const auctionId = Number(req.params.auctionId);
    const name = String(req.body.name || '').trim();
    const advance = Math.max(0, Number(req.body.advance) || 0);
    if (!auctionId || !name) return res.status(400).json({ error: 'auctionId and name are required' });
    const auction = db.get('SELECT id FROM auctions WHERE id = ?', [auctionId]);
    if (!auction) return res.status(404).json({ error: 'Auction not found' });
    // `name_key` holds the seller IDENTITY, not the raw name. Two sellers can
    // share a name, and a name-keyed advance would be deducted from both.
    // Rows written before this carry the bare uppercase name and still resolve
    // through the readers' name fallback, so no data migration is needed.
    const traderId = Number(req.body.trader_id);
    const legacyKey = name.toUpperCase();
    const nameKey = Number.isFinite(traderId) && traderId > 0 ? `id:${traderId}` : legacyKey;
    if (advance > 0) {
      // Writing an id-keyed row supersedes any legacy name-keyed one for this
      // seller — leaving it behind would let the readers' name fallback apply
      // this seller's old advance to their namesake.
      if (nameKey !== legacyKey) {
        db.run('DELETE FROM payment_advances WHERE auction_id = ? AND name_key = ?', [auctionId, legacyKey]);
      }
      // Upsert — one row per (auction, seller). REPLACE keeps it simple and
      // idempotent; the PRIMARY KEY (auction_id, name_key) is the conflict key.
      db.run(
        `INSERT INTO payment_advances (auction_id, name_key, name, advance, updated_at)
         VALUES (?, ?, ?, ?, datetime('now','localtime'))
         ON CONFLICT(auction_id, name_key)
         DO UPDATE SET advance = excluded.advance, name = excluded.name,
                       updated_at = datetime('now','localtime')`,
        [auctionId, nameKey, name, advance]);
    } else {
      // Zero advance → remove the row so it doesn't linger as a stale record.
      // Clear both spellings so an old name-keyed row can't resurrect.
      db.run('DELETE FROM payment_advances WHERE auction_id = ? AND name_key IN (?, ?)',
        [auctionId, nameKey, legacyKey]);
    }
    res.json({ success: true, name, advance });
  } catch (e) {
    res.status(500).json({ error: 'Advance save failed: ' + (e.message || e) });
  }
});

// Opt in/out of the display-only settlement discount for this auction. When
// applied=true the "Calculate All Discounts" button flips auctions.discount_applied
// so getPaymentSummary + the statements/exports surface the days-based discount
// for every seller at once. Discount never changes Payable. Body: { applied }.
app.post('/api/payments/:auctionId/apply-discount', requireLotWrite, (req, res) => {
  try {
    const db = getDb();
    const auctionId = Number(req.params.auctionId);
    const applied = req.body.applied === false ? 0 : 1;
    if (!auctionId) return res.status(400).json({ error: 'auctionId is required' });
    const auction = db.get('SELECT id FROM auctions WHERE id = ?', [auctionId]);
    if (!auction) return res.status(404).json({ error: 'Auction not found' });
    db.run('UPDATE auctions SET discount_applied = ? WHERE id = ?', [applied, auctionId]);
    res.json({ success: true, applied: !!applied });
  } catch (e) {
    res.status(500).json({ error: 'Discount toggle failed: ' + (e.message || e) });
  }
});

// Delete the lots + DNs for a list of sellers in one auction. Powers
// the "Delete Selected" button on the Payments tab. Each row in the
// payments table is a roll-up of one seller's lots in the trade, so
// deleting a payment "row" means clearing those underlying lots.
//
// Body: { sellerNames: ['DealerA', 'DealerB', ...] }
//
// Trade-scoped — only touches data in this auction. Names are matched
// case-insensitively to be tolerant of legacy data inconsistencies.
app.post('/api/payments/:auctionId/delete-sellers', requireDelete, (req, res) => {
  try {
    const db = getDb();
    const auctionId = req.params.auctionId;
    const names = Array.isArray(req.body.sellerNames) ? req.body.sellerNames : [];
    if (!names.length) {
      return res.status(400).json({ error: 'sellerNames array is required' });
    }
    const auction = db.get('SELECT ano FROM auctions WHERE id = ?', [auctionId]);
    if (!auction) return res.status(404).json({ error: 'Auction not found' });

    // Build a parameterised IN clause. SQLite max parameters is 999;
    // we cap chunks at 500 names per query to stay well within limits.
    const CHUNK = 500;
    let lotsDeleted = 0, dnsDeleted = 0;
    for (let i = 0; i < names.length; i += CHUNK) {
      const batch = names.slice(i, i + CHUNK).map(s => String(s).trim()).filter(Boolean);
      if (!batch.length) continue;
      const placeholders = batch.map(() => '?').join(',');
      // Lots — case-insensitive match. UPPER() on both sides handles
      // legacy case mismatches (data sometimes imported as title case,
      // sometimes uppercased).
      const upperBatch = batch.map(n => n.toUpperCase());
      const lotsBefore = db.get(
        `SELECT COUNT(*) AS c FROM lots
          WHERE auction_id = ?
            AND UPPER(COALESCE(name,'')) IN (${placeholders})`,
        [auctionId, ...upperBatch]
      ).c;
      // Advances against those lots first — they are keyed by lot id, so once
      // the lots are gone there is nothing left to match them on.
      db.run(
        `DELETE FROM lot_advances
          WHERE lot_id IN (SELECT id FROM lots
                            WHERE auction_id = ?
                              AND UPPER(COALESCE(name,'')) IN (${placeholders}))`,
        [auctionId, ...upperBatch]
      );
      db.run(
        `DELETE FROM lots
          WHERE auction_id = ?
            AND UPPER(COALESCE(name,'')) IN (${placeholders})`,
        [auctionId, ...upperBatch]
      );
      lotsDeleted += lotsBefore;

      // Cascading DN cleanup — debit_notes for these sellers in this
      // trade are now orphaned references, so delete them too.
      const dnsBefore = db.get(
        `SELECT COUNT(*) AS c FROM debit_notes
          WHERE ano = ?
            AND UPPER(COALESCE(name,'')) IN (${placeholders})`,
        [auction.ano, ...upperBatch]
      ).c;
      db.run(
        `DELETE FROM debit_notes
          WHERE ano = ?
            AND UPPER(COALESCE(name,'')) IN (${placeholders})`,
        [auction.ano, ...upperBatch]
      );
      dnsDeleted += dnsBefore;
    }

    res.json({
      success: true,
      sellers: names.length,
      lotsDeleted,
      dnsDeleted,
    });
  } catch (e) {
    res.status(500).json({ error: 'Delete failed: ' + (e.message || e) });
  }
});

// ── Bank payment data (BANKPAY.PRG) ──────────────────────────
app.get('/api/payments/bank/:auctionId', requireView, (req, res) => {
  const cfg = getSettingsFlat(getDb());
  const data = getBankPaymentData(getDb(), req.params.auctionId, cfg);
  res.json(data);
});

// ── Payment Statement PDF (per-seller) ────────────────────────
// Lightweight A4 PDF showing the payment due to one seller for one
// auction: header, seller block, lots breakdown, totals. Powers both
// "Print" and "WhatsApp" actions on the Payments tab.
// `userId` (optional) is the seller's USER ID from the Sellers master. Two
// masters can share a name, so when it is supplied every lookup below narrows
// on it — without it a statement for "BASKARAN S" listed BOTH sellers' lots
// and printed whichever of the two phone numbers came first.
function _renderPaymentStatement(doc, db, auctionId, sellerName, cfg, lotIds, userId) {
  const uid = String(userId || '').trim();
  // Applied to `lots` queries; `l` is not aliased in them, hence bare columns.
  const uidLotSql = uid ? ` AND TRIM(COALESCE(user_id,'')) = ?` : '';
  const uidLotArg = uid ? [uid] : [];
  const auction = db.get('SELECT * FROM auctions WHERE id = ?', [auctionId]) || { ano:'', date:'' };
  // The lots table stores the per-kg price in `price` (not `rate`). The
  // query previously selected `rate`, which doesn't exist — sql.js
  // throws "no such column: rate" and the outer try/catch closes the
  // already-piped PDF stream early, producing a near-empty file. Aliasing
  // `price AS rate` keeps the existing rendering code (which reads
  // `row.rate`) working without further changes.
  //
  // Optional `lotIds` narrows the statement to a caller-chosen subset of
  // the seller's lots — supports the Payments tab's "partial payment"
  // flow where the operator picks specific lots to settle now and leaves
  // the rest for a later visit.
  const lotIdFilter = Array.isArray(lotIds)
    ? lotIds.map(n => parseInt(n, 10)).filter(Number.isFinite)
    : [];
  let lotSql = `SELECT lot_no, qty, price AS rate, amount, puramt, refund, com, balance, cgst, sgst, igst, cr, aadhar, immediate_payment
       FROM lots WHERE auction_id = ? AND name = ? AND amount > 0${uidLotSql}`;
  const lotParams = [auctionId, sellerName, ...uidLotArg];
  if (lotIdFilter.length) {
    lotSql += ` AND id IN (${lotIdFilter.map(() => '?').join(',')})`;
    lotParams.push(...lotIdFilter);
  }
  lotSql += ' ORDER BY lot_no';
  const lots = db.all(lotSql, lotParams) || [];

  // TDS (u/s 194Q) is held once per seller on the purchase invoice — not on the
  // lots. Pull it and allocate across the rendered lots in proportion to lot
  // amount so a partial (selected-lot) statement carries a matching share and
  // the column total reconciles to the seller's purchase TDS. The remainder
  // lands on the last lot to keep the sum exact.
  const _tdsRow = db.get(
    'SELECT SUM(COALESCE(tds,0)) AS tds FROM purchases WHERE auction_id = ? AND LOWER(name) = LOWER(?)',
    [auctionId, sellerName]) || {};
  // When the statement covers a subset of lots, scale TDS to that subset's
  // share of the seller's full sale amount so it doesn't over-state.
  const _fullTds = Number(_tdsRow.tds) || 0;
  const _allAmt = Number((db.get(
    `SELECT SUM(amount) AS a FROM lots WHERE auction_id = ? AND name = ? AND amount > 0${uidLotSql}`,
    [auctionId, sellerName, ...uidLotArg]) || {}).a) || 0;
  const _shownAmt = lots.reduce((a, l) => a + (Number(l.amount) || 0), 0);
  const _stmtTds = (_allAmt > 0) ? Math.round(_fullTds * (_shownAmt / _allAmt) * 100) / 100 : 0;
  let _tdsAlloc = 0;
  lots.forEach((l, i) => {
    if (i === lots.length - 1) {
      l._tds = Math.max(0, Math.round((_stmtTds - _tdsAlloc) * 100) / 100);
    } else {
      const v = _shownAmt > 0 ? Math.round(_stmtTds * (Number(l.amount) || 0) / _shownAmt * 100) / 100 : 0;
      l._tds = v; _tdsAlloc += v;
    }
  });

  // User id first — the name alone can match the wrong master row.
  const trader = (uid && db.get(
      "SELECT * FROM traders WHERE UPPER(TRIM(COALESCE(user_id,''))) = UPPER(?) LIMIT 1", [uid]))
    || db.get('SELECT * FROM traders WHERE LOWER(name) = LOWER(?) ORDER BY id LIMIT 1', [sellerName]);
  const fmtAmt = (n) => Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const fmtQty = (n) => Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 3, maximumFractionDigits: 3 });
  const fmtDate = (d) => { if (!d) return ''; const m = String(d).match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? `${m[3]}/${m[2]}/${m[1]}` : String(d); };
  const company = (cfg.trade_name || cfg.short_name || cfg.tally_company_name || cfg.legal_name || 'Company').toString();

  const PAGE_L = 30, PAGE_R = 565, PAGE_W = PAGE_R - PAGE_L;
  let y = 40;
  doc.font('Helvetica-Bold').fontSize(16).text(company.toUpperCase(), PAGE_L, y, { width: PAGE_W, align: 'center' });
  y = doc.y + 4;
  doc.font('Helvetica-Bold').fontSize(13).text('PAYMENT STATEMENT', PAGE_L, y, { width: PAGE_W, align: 'center' });
  y = doc.y + 10;
  doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).lineWidth(1).stroke();
  y += 10;

  doc.font('Helvetica').fontSize(10);
  doc.text(`Seller: ${sellerName}`, PAGE_L, y); doc.text(`Auction: ${auction.ano}`, PAGE_L + 280, y);
  y += 14;
  doc.text(`Phone: ${trader && trader.tel ? trader.tel : '-'}`, PAGE_L, y);
  doc.text(`Date: ${fmtDate(auction.date)}`, PAGE_L + 280, y);
  y += 18;

  // 8 columns sized to fill the 535pt usable width (sum of w === PAGE_W).
  // Purchase = amount + sample-bag refund, matching the main Payments list's
  // purchase_value (calculations.js) so the list, this statement, and the
  // lot-selection modal all show the same Amount and Purchase figures.
  const cols = [
    { k: 'lot_no',   label: 'Lot#',       x: PAGE_L,        w: 42,  align: 'left' },
    { k: 'qty',      label: 'Qty',        x: PAGE_L + 42,   w: 58,  align: 'right', fmt: fmtQty },
    { k: 'rate',     label: 'Rate',       x: PAGE_L + 100,  w: 48,  align: 'right', fmt: fmtAmt },
    { k: 'amount',   label: 'Amount',     x: PAGE_L + 148,  w: 66,  align: 'right', fmt: fmtAmt },
    { k: 'purchase', label: 'Purchase',   x: PAGE_L + 214,  w: 66,  align: 'right', fmt: fmtAmt },
    { k: 'com',      label: 'Commission', x: PAGE_L + 280,  w: 60,  align: 'right', fmt: fmtAmt },
    { k: 'tax',      label: 'GST',        x: PAGE_L + 340,  w: 52,  align: 'right', fmt: fmtAmt },
    { k: 'tds',      label: 'TDS',        x: PAGE_L + 392,  w: 52,  align: 'right', fmt: fmtAmt },
    { k: 'balance',  label: 'Net Amt',    x: PAGE_L + 444,  w: 91,  align: 'right', fmt: fmtAmt },
  ];
  doc.font('Helvetica-Bold').fontSize(9);
  doc.rect(PAGE_L, y, PAGE_W, 18).fillAndStroke('#f3f4f6', '#999').fillColor('#000');
  for (const c of cols) doc.text(c.label, c.x + 2, y + 5, { width: c.w - 4, align: c.align });
  y += 18;
  doc.font('Helvetica').fontSize(9).fillColor('#000');
  let tQty=0,tAmt=0,tPur=0,tDisc=0,tTax=0,tPay=0,tTds=0;
  for (const l of lots) {
    const tax = (Number(l.cgst)||0)+(Number(l.sgst)||0)+(Number(l.igst)||0);
    const purchase = (Number(l.amount)||0)+(Number(l.refund)||0);
    const row = { ...l, tax, purchase, tds: Number(l._tds)||0 };
    tQty+=Number(l.qty)||0; tAmt+=Number(l.amount)||0; tPur+=purchase; tDisc+=Number(l.com)||0; tTax+=tax; tPay+=Number(l.balance)||0; tTds+=Number(l._tds)||0;
    if (y > 770) { doc.addPage(); y = 40; }
    for (const c of cols) {
      const v = c.fmt ? c.fmt(row[c.k]) : String(row[c.k] ?? '');
      doc.text(v, c.x + 2, y + 4, { width: c.w - 4, align: c.align });
    }
    y += 14;
    doc.moveTo(PAGE_L, y).lineTo(PAGE_R, y).strokeColor('#e5e7eb').lineWidth(0.5).stroke().strokeColor('#000');
  }
  doc.font('Helvetica-Bold').fontSize(10);
  doc.rect(PAGE_L, y, PAGE_W, 20).fillAndStroke('#f3f4f6', '#666').fillColor('#000');
  // Render each total under its own column (driven by the cols layout) so
  // the figures stay aligned with the data rows and the Purchase total fits.
  const totalsByKey = {
    lot_no:  'TOTAL',
    qty:     fmtQty(tQty),
    amount:  fmtAmt(tAmt),
    purchase:fmtAmt(tPur),
    com:     fmtAmt(tDisc),
    tax:     fmtAmt(tTax),
    tds:     fmtAmt(tTds),
    balance: fmtAmt(tPay),
  };
  for (const c of cols) {
    const v = totalsByKey[c.k];
    if (v == null) continue;
    doc.text(v, c.x + 2, y + 6, { width: c.w - 4, align: c.k === 'lot_no' ? 'left' : 'right' });
  }
  y += 30;

  // ── Net Amount → Advance → Payable (with display-only Discount) ──
  // tPay (Σ balance) is the Net Amount. Payable = Net − Advance already paid.
  // The days-based settlement discount is DISPLAY-ONLY (opt-in per auction) and
  // is shown as a reference line below Payable — it never changes Payable.
  const _discPct    = Number(cfg.discount_pct)  || 0;
  const _poolerDays = Number(cfg.discount_days) || 0;
  const _dealerDays = Number(cfg.dealer_days)   || 0;
  const _isDealer   = hasValidGstin((lots[0] || {}).cr);
  const _days       = _isDealer ? _dealerDays : _poolerDays;
  const _netAmount  = tPay;

  // Advance already paid to this seller for this auction. On a partial
  // (lot-picked) statement, scale it to the shown share of the seller's full
  // amount — same proportional basis as the TDS allocation above — so it never
  // over-deducts on a subset of lots.
  let _advance = 0;
  try {
    // Identity key first ('id:<trader_id>'), then the legacy name key. The
    // trader is resolved above from the user id / name for this statement.
    const _advKeys = [];
    if (trader && trader.id != null) _advKeys.push(`id:${trader.id}`);
    _advKeys.push(String(sellerName || '').trim().toUpperCase());
    let _advRow = null;
    for (const k of _advKeys) {
      _advRow = db.get(
        'SELECT advance FROM payment_advances WHERE auction_id = ? AND UPPER(name_key) = UPPER(?)',
        [auctionId, k]);
      if (_advRow) break;
    }
    const _fullAdv = _advRow ? (Number(_advRow.advance) || 0) : 0;
    _advance = (lotIdFilter.length && _allAmt > 0)
      ? Math.round(_fullAdv * (_shownAmt / _allAmt) * 100) / 100
      : _fullAdv;
  } catch (_) { _advance = 0; }
  const _payable    = _netAmount - _advance;

  // Display-only settlement discount — only when the operator has applied it
  // for this auction (Payments tab → "Calculate All Discounts").
  let _discountApplied = 0;
  try {
    const _a = db.get('SELECT discount_applied FROM auctions WHERE id = ?', [auctionId]);
    _discountApplied = _a && Number(_a.discount_applied) === 1 ? 1 : 0;
  } catch (_) { _discountApplied = 0; }
  // "For all sellers" mode — discount is computed on the seller's FULL net
  // amount (_netAmount), not just immediate-payment lots, so it's non-zero even
  // when no lots are flagged immediate. Display-only; never reduces Payable.
  const _discount   = _discountApplied ? Math.round(_netAmount / 1000 * _days * _discPct) : 0;

  // Wide label column + lineBreak:false so the captions stay on one line.
  const sVW = 95, sLW = 250, sX = PAGE_R - (sLW + sVW);
  const sumRow = (label, val, bold) => {
    doc.font(bold ? 'Helvetica-Bold' : 'Helvetica').fontSize(bold ? 11 : 9.5);
    doc.text(label, sX, y, { width: sLW, align: 'right', lineBreak: false });
    doc.text(val,   sX + sLW, y, { width: sVW, align: 'right', lineBreak: false });
    y += bold ? 18 : 15;
  };
  sumRow('Net Amount', fmtAmt(_netAmount));
  if (tTds > 0) sumRow('TDS (u/s 194Q) on Purchase', fmtAmt(tTds));
  if (_advance > 0) sumRow('Less: Advance paid', '- ' + fmtAmt(_advance));
  doc.moveTo(sX, y).lineTo(sX + sLW + sVW, y).lineWidth(0.5).stroke();
  y += 4;
  sumRow('Payable', fmtAmt(_payable), true);
  // Discount is informational only — shown after Payable and clearly captioned
  // so it's never mistaken for a deduction from the amount payable.
  if (_discountApplied && _discount > 0) {
    doc.font('Helvetica-Oblique').fontSize(8.5).fillColor('#666');
    doc.text(`Settlement discount (for reference only, not deducted · ${_isDealer ? 'dealer' : 'pooler'} · ${_days}d): ${fmtAmt(_discount)}`,
      sX - 120, y, { width: sLW + sVW + 120, align: 'right', lineBreak: false });
    doc.fillColor('#000');
    y += 14;
  }
  y += 10;

  doc.font('Helvetica').fontSize(9).text(`Generated: ${new Date().toLocaleString('en-IN')}`, PAGE_L, y, { width: PAGE_W, align: 'right' });
  return _payable;
}

app.get('/api/payments/pdf/:auctionId/:sellerName', requireView, (req, res) => {
  let doc, piped = false;
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const auctionId = req.params.auctionId;
    const sellerName = decodeURIComponent(req.params.sellerName);
    // Validate BEFORE piping — once we pipe, any subsequent throw can't
    // be turned into a JSON response (headers + body already going out).
    const auction = db.get('SELECT id FROM auctions WHERE id = ?', [auctionId]);
    if (!auction) return res.status(404).json({ error: 'Auction not found' });
    const PDFDocument = require('pdfkit');
    doc = new PDFDocument({ size: 'A4', margin: 30 });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="Payment_${req.params.sellerName}_${auctionId}.pdf"`);
    doc.pipe(res); piped = true;
    res.on('close', () => { try { doc.destroy(); } catch(_){} });
    _renderPaymentStatement(doc, db, auctionId, sellerName, cfg, null, req.query.userId);
    doc.end();
  } catch (e) {
    if (piped && doc) { try { doc.end(); } catch(_){} }
    else if (!res.headersSent) res.status(500).json({ error: e.message || 'PDF failed' });
  }
});

// Per-seller, lot-filtered PDF. Body { auction_id, seller_name, lot_ids: [...] }
// Powers the Payments tab's "partial payment" flow — the operator opens the
// per-seller lots modal, ticks the lots they're settling now, and prints a
// statement covering only that subset. Remaining lots can be paid later.
app.post('/api/payments/pdf-lots', requireView, (req, res) => {
  let doc, piped = false;
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const auctionId = Number(req.body.auction_id);
    const sellerName = String(req.body.seller_name || '').trim();
    const lotIds = Array.isArray(req.body.lot_ids) ? req.body.lot_ids : [];
    if (!auctionId || !sellerName || !lotIds.length) {
      return res.status(400).json({ error: 'auction_id, seller_name and lot_ids[] are required' });
    }
    const auction = db.get('SELECT id FROM auctions WHERE id = ?', [auctionId]);
    if (!auction) return res.status(404).json({ error: 'Auction not found' });
    const PDFDocument = require('pdfkit');
    doc = new PDFDocument({ size: 'A4', margin: 30 });
    res.setHeader('Content-Type', 'application/pdf');
    const safeName = sellerName.replace(/[^\w]/g, '_').slice(0, 80) || 'seller';
    res.setHeader('Content-Disposition', `inline; filename="Payment_${safeName}_${auctionId}_partial.pdf"`);
    doc.pipe(res); piped = true;
    res.on('close', () => { try { doc.destroy(); } catch(_){} });
    _renderPaymentStatement(doc, db, auctionId, sellerName, cfg, lotIds, req.body.user_id);
    doc.end();
  } catch (e) {
    if (piped && doc) { try { doc.end(); } catch(_){} }
    else if (!res.headersSent) res.status(500).json({ error: e.message || 'PDF failed' });
  }
});

// Bulk: Body { auction_id, names: [...] } → one merged PDF, page-break per seller.
app.post('/api/payments/pdf-bulk', requireView, (req, res) => {
  let doc, piped = false;
  try {
    const db = getDb();
    const cfg = getSettingsFlat(db);
    const auctionId = Number(req.body.auction_id);
    // Each entry is either a bare name (legacy callers) or {name, user_id} —
    // the latter disambiguates two sellers who share a name.
    const names = (Array.isArray(req.body.names) ? req.body.names : [])
      .map(n => (n && typeof n === 'object') ? n : { name: n, user_id: '' })
      .filter(n => String(n.name || '').trim() !== '');
    if (!auctionId || !names.length) return res.status(400).json({ error: 'auction_id and names[] required' });
    const auction = db.get('SELECT id FROM auctions WHERE id = ?', [auctionId]);
    if (!auction) return res.status(404).json({ error: 'Auction not found' });
    const PDFDocument = require('pdfkit');
    doc = new PDFDocument({ size: 'A4', margin: 30 });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `inline; filename="Payments_Batch_${names.length}.pdf"`);
    doc.pipe(res); piped = true;
    res.on('close', () => { try { doc.destroy(); } catch(_){} });
    names.forEach((entry, i) => {
      const nm = String(entry.name || '');
      if (i > 0) doc.addPage();
      try { _renderPaymentStatement(doc, db, auctionId, nm, cfg, null, entry.user_id); }
      catch (e) { try { doc.font('Helvetica').fontSize(10).text(`Error rendering ${nm}: ${e.message}`); } catch(_){} }
    });
    doc.end();
  } catch (e) {
    if (piped && doc) { try { doc.end(); } catch(_){} }
    else if (!res.headersSent) res.status(500).json({ error: e.message || 'PDF failed' });
  }
});

