// Resolve the business-facing auction number (`ano`) for use in download
// filenames. Export *contents* already resolve `ano` internally; this keeps
// the downloaded file NAME consistent with what users recognise (e.g.
// "LotSlip_42.xlsx" instead of "LotSlip_7.xlsx" where 7 is the internal id).
// Falls back to the raw id when the auction can't be found. The result is
// sanitised so values like "42/A" stay filesystem-safe.
function anoForFilename(db, auctionId) {
  let val = auctionId;
  try {
    const a = db.get('SELECT ano FROM auctions WHERE id = ?', [auctionId]);
    if (a && a.ano != null && String(a.ano).trim()) val = String(a.ano).trim();
  } catch (_) {}
  return String(val).replace(/[\/\\:*?"<>|]+/g, '-');
}

app.get('/api/exports/:type/:auctionId', requireExport, async (req, res) => {
  const { type, auctionId } = req.params;
  const format = (req.query.format || 'xlsx').toLowerCase();

  if (format === 'pdf') {
    try {
      const db = getDb();
      const cfg = getSettingsFlat(db);
      const buffer = await exportAnyPdf(db, type, auctionId, cfg, { state: req.query.state });
      const niceName = (EXPORT_TYPES[type] && EXPORT_TYPES[type].name) || type;
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="${niceName}_${anoForFilename(db, auctionId)}.pdf"`);
      return res.send(buffer);
    } catch (e) {
      return res.status(500).json({ error: e.message });
    }
  }

  const exportDef = EXPORT_TYPES[type];
  if (!exportDef) return res.status(400).json({ error: 'Unknown export type', available: Object.keys(EXPORT_TYPES) });

  try {
    const db = getDb();
    let buffer;
    // Extra filters (branch, sale type, etc.) — passed through to the
    // export function so it can restrict aggregates. Backward-compatible:
    // existing exports that ignore the trailing arg are unaffected.
    const extra = {
      branch:   req.query.branch   || '',
      saleType: req.query.saleType || req.query.sale_type || '',
      // Optional bulk-action filter: comma-separated seller names from the
      // Payments tab. Empty → no filter (full trade export).
      sellers:  req.query.sellers
        ? String(req.query.sellers).split(',').map(s => s.trim()).filter(Boolean)
        : [],
    };
    if (exportDef.needsCfg) {
      const cfg = getSettingsFlat(db);
      // Pass state too so exports that need both (e.g. Praman) can filter
      // by state without losing cfg context. Backward-compatible: existing
      // needsCfg exports that ignore the 4th arg are unaffected.
      buffer = await exportDef.fn(db, auctionId, cfg, req.query.state, extra);
    } else {
      buffer = await exportDef.fn(db, auctionId, req.query.state, extra);
    }
    // Per-export-type content-type/extension override (defaults to xlsx).
    // CSV exports like Praman use ext:'csv', mime:'text/csv'.
    let ext  = exportDef.ext  || 'xlsx';
    let mime = exportDef.mime || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    // ?format=csv on an export that natively emits XLSX — convert the
    // workbook we just built. Drives the Auction Downloads screen's "CSV
    // Downloads" section, where the operator wants the same report as a
    // flat file. An export that is ALREADY csv (Praman) falls straight
    // through; converting it would be a no-op round trip.
    if (format === 'csv' && ext !== 'csv') {
      buffer = await xlsxToCsvBuffer(Buffer.from(buffer));
      ext = 'csv';
      mime = 'text/csv; charset=utf-8';
    }
    // The mirror image: ?format=xlsx on an export that natively writes CSV
    // text (Commission Bill, Dealer Invoice). The Auction Downloads screen
    // now hands every tile a spreadsheet, and those two feeds build no
    // workbook of their own — so the CSV they produced is re-read into one.
    // Gated on the format being asked for EXPLICITLY, not on the route's
    // `|| 'xlsx'` default: a caller that names no format still gets the
    // native bytes, exactly as it did before.
    else if (ext === 'csv' && String(req.query.format || '').toLowerCase() === 'xlsx') {
      buffer = await csvToXlsxBuffer(Buffer.from(buffer), exportDef.name);
      ext = 'xlsx';
      mime = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    }
    res.setHeader('Content-Type', mime);
    res.setHeader('Content-Disposition', `attachment; filename="${exportDef.name}_${anoForFilename(db, auctionId)}.${ext}"`);
    // The PWA can run off a different origin; without this the browser hides
    // Content-Disposition and the client can't name the blob it downloads.
    res.setHeader('Access-Control-Expose-Headers', 'Content-Disposition');
    res.send(Buffer.from(buffer));
  } catch(e) {
    res.status(500).json({ error: e.message });
  }
});

// POST variant — powers the Payments tab's tracked "Export Selected" flow.
// Body { names:[...], lots:{seller:[lot_no,…]}, excludeLots:{seller:[lot_no,…]},
// format, state, orderBy }. names → seller filter; lots → per-seller picked subset;
// excludeLots → lots already shipped in a prior export (skipped so re-export
// doesn't double-pay them). XLSX/CSV only (the GET route handles PDF).
app.post('/api/exports/:type/:auctionId', requireExport, async (req, res) => {
  const { type, auctionId } = req.params;
  const body = req.body || {};
  if (String(body.format || 'xlsx').toLowerCase() === 'pdf') {
    return res.status(400).json({ error: 'PDF not supported on the selected-export route. Use the GET endpoint for a full PDF.' });
  }
  const exportDef = EXPORT_TYPES[type];
  if (!exportDef) return res.status(400).json({ error: 'Unknown export type', available: Object.keys(EXPORT_TYPES) });
  try {
    const db = getDb();
    const names = Array.isArray(body.names) ? body.names.map(s => String(s || '').trim()).filter(Boolean) : [];
    const cleanMap = (src) => {
      if (!src || typeof src !== 'object' || Array.isArray(src)) return null;
      const out = {};
      for (const k of Object.keys(src)) {
        const arr = Array.isArray(src[k]) ? src[k].map(v => String(v || '').trim()).filter(Boolean) : [];
        if (arr.length) out[k] = arr;
      }
      return Object.keys(out).length ? out : null;
    };
    // sellerKeys are the identity form of the same selection ('id:<trader_id>').
    // Sent by the Payments tab's tracked export; when present they override the
    // name filter so ticking one of two same-named sellers exports only that
    // one. `names` stays for older callers and for the on-screen labels.
    const sellerKeys = Array.isArray(body.sellerKeys)
      ? body.sellerKeys.map(s => String(s || '').trim()).filter(Boolean) : [];
    const extra = {
      branch: '', saleType: '',
      sellers: names,
      sellerKeys: sellerKeys.length ? sellerKeys : null,
      lots:        cleanMap(body.lots),
      excludeLots: cleanMap(body.excludeLots),
      // 'lot' → order the rows by lot number instead of by seller. Sent by the
      // Lot-wise Payments screen, which itself lists lots in that order; the
      // classic seller-wise screen sends nothing and keeps its own ordering.
      orderByLot: String(body.orderBy || '').toLowerCase() === 'lot',
    };
    let buffer;
    if (exportDef.needsCfg) {
      const cfg = getSettingsFlat(db);
      buffer = await exportDef.fn(db, auctionId, cfg, body.state || null, extra);
    } else {
      buffer = await exportDef.fn(db, auctionId, body.state || null, extra);
    }
    const ext  = exportDef.ext  || 'xlsx';
    const mime = exportDef.mime || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
    res.setHeader('Content-Type', mime);
    res.setHeader('Content-Disposition', `attachment; filename="${exportDef.name}_selected_${anoForFilename(db, auctionId)}.${ext}"`);
    res.send(Buffer.from(buffer));
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// TDS export (supports ?format=pdf)
app.get('/api/exports/tds-return', requireExport, async (req, res) => {
  const { from, to } = req.query;
  const format = (req.query.format || 'xlsx').toLowerCase();
  if (!from || !to) return res.status(400).json({ error: 'from/to required' });
  if (format === 'pdf') {
    const buffer = await exportAnyPdf(getDb(), 'tds_return', null, null, { from, to });
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', 'attachment; filename="TDSReturn.pdf"');
    return res.send(buffer);
  }
  const { exportTDSReturn } = require('./exports');
  const buffer = await exportTDSReturn(getDb(), from, to);
  res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  res.setHeader('Content-Disposition', 'attachment; filename="TDSReturn.xlsx"');
  res.send(Buffer.from(buffer));
});

